window.JPG=window.JPG||{};JPG.N4=[{"id":"g4_001","t":"AとかBとか","ko":"A라든가 B라든가, A나 B 같은","cat":"조사","conn":[{"w":"명사","f":"映画とか買い物とか"},{"w":"동사 사전형","f":"本を読むとか、音楽を聞くとか"},{"w":"い형용사","f":"高いとか安いとか"},{"w":"마지막 とか 생략","f":"パンとかケーキが好きです"}],"rule":["예로 들 말(명사 등) 바로 뒤에 とか를 붙인다.","두 번째 예 뒤에도 とか를 붙여 'A とか B とか'로 늘어놓는다. 마지막 とか는 생략할 수 있다.","とか 자체는 바뀌지 않고, 뒤에는 조사(が・を 등)나 동사가 이어진다(映画とか買い物とかをする / 映画とか買い物が好きだ)."],"why":"","nu":"회화체다. 여러 예 가운데 몇 개만 꺼내 보이는 표현이라 '그 밖에도 있다'는 느낌이 있다. 글이나 격식 있는 자리에서는 名詞や名詞(など)를 쓴다. 동사·형용사도 늘어놓을 수 있다는 점이 や와 다르다. 젊은 층에서 단정을 피하려고 한 개만 들어 'コーヒーとか飲む?'처럼 쓰기도 한다.","cmp":[{"g":"AやBなど","d":"명사만 잇고 문어·격식체. とか는 회화체이며 동사·형용사도 이을 수 있다."},{"g":"AとB","d":"말한 것이 전부(완전 나열). とか는 일부만 예로 든다."}],"ex":[{"jp":"週末[しゅうまつ]は映画[えいが]とか買[か]い物[もの]とかに行[い]きます。","ko":"주말엔 영화라든가 쇼핑 같은 데 가요."},{"jp":"休[やす]みの日[ひ]は本[ほん]を読[よ]むとか、音楽[おんがく]を聞[き]くとかしています。","ko":"쉬는 날엔 책을 읽거나 음악을 듣거나 해요."},{"jp":"野菜[やさい]とか果物[くだもの]とか、体[からだ]にいいものを食[た]べたほうがいいよ。","ko":"채소라든가 과일이라든가, 몸에 좋은 걸 먹는 게 좋아."}],"dr":[{"t":"make","q":"すし / てんぷら → 'すし라든가 てんぷら라든가'","a":"すしとかてんぷらとか","hint":"각 명사 뒤에 とか를 붙인다."},{"t":"make","q":"テニスをする / 泳ぐ → '테니스를 치거나 수영하거나'","a":"テニスをするとか泳ぐとか","hint":"동사는 사전형 그대로 + とか."},{"t":"fill","q":"昼[ひる]ご飯[はん]はパン（　）おにぎり（　）を買[か]います。","a":"とか","opts":["とか","より","ほど","しか"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%8B-%E3%81%A8%E3%81%8B"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_083","t":"～ずつ","ko":"~씩","cat":"조사","conn":[{"w":"수량사","f":"二つ + ずつ"},{"w":"정도를 나타내는 말","f":"少し + ずつ"},{"w":"사람 수","f":"一人 + ずつ"}],"rule":["1. 수량이나 정도를 나타내는 말 바로 뒤에 ずつ를 붙인다(二つ→二つずつ).","2. 앞의 말은 형태가 바뀌지 않는다(少し→少しずつ, 一人→一人ずつ).","3. 문장 안에서는 보통 '명사 + を + 수량 + ずつ + 동사' 순서가 된다(りんごを二つずつ配る)."],"why":"","nu":"같은 양을 각각에 나누는 뜻(一人に二つずつ)과, 같은 양을 반복하는 뜻(毎日少しずつ, 一人ずつ入る)이 있다. 수량이 아닌 일반 명사에는 붙지 않는다(×りんごずつ). 한국어 '-씩'과 거의 같지만 '조금씩'은 少しずつ, '하나씩'은 一つずつ로 수량사가 꼭 필요하다.","cmp":[{"g":"～ごとに","d":"'~마다'로 단위·간격마다 반복됨을 나타낸다(一時間ごとに). ～ずつ는 할당·반복되는 양 자체를 나타낸다."}],"ex":[{"jp":"子[こ]どもたちにりんごを二[ふた]つずつあげました。","ko":"아이들에게 사과를 두 개씩 주었어요."},{"jp":"毎日[まいにち]少[すこ]しずつ漢字[かんじ]を覚[おぼ]えています。","ko":"매일 조금씩 한자를 외우고 있어요."},{"jp":"一人[ひとり]ずつ部屋[へや]に入[はい]ってください。","ko":"한 명씩 방에 들어가 주세요."}],"dr":[{"t":"make","q":"三枚 → ～ずつ","a":"三枚ずつ","hint":"수량사 뒤에 그대로 ずつ를 붙인다."},{"t":"make","q":"少し → ～ずつ","a":"少しずつ","hint":"정도를 나타내는 말 뒤에 ずつ."},{"t":"fill","q":"お菓子[かし]を一人[ひとり]三[みっ]つ（　）取[と]ってください。","a":"ずつ","opts":["ずつ","しか","より","へ"]}],"src":["https://bunpro.jp/grammar_points/ずつ"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_093","t":"～で","ko":"~로(수단), ~에서(장소)","cat":"조사","conn":[{"w":"명사(수단·도구)","f":"バス + で"},{"w":"명사(재료·언어)","f":"日本語 + で"},{"w":"명사(동작 장소)","f":"図書館 + で"},{"w":"명사(원인)","f":"病気 + で"}],"rule":["1. 명사 바로 뒤에 で를 붙인다. 형태는 바뀌지 않는다(バス+で).","2. 교통수단·도구·언어 뒤면 '~로'(バスで行く, ペンで書く, 日本語で話す).","3. 장소 뒤에 동작 동사가 오면 '~에서'(図書館で勉強する)."],"why":"","nu":"한국어 '~로'와 '~에서'를 모두 で가 맡는다. 존재(ある・いる)의 장소에는 で가 아니라 に를 쓴다(×公園で猫がいる → 公園に猫がいる). 걸어서 가는 것은 足で가 아니라 歩いて行く.","cmp":[{"g":"～に(장소)","d":"존재하는 곳이나 도착점. で는 동작이 일어나는 곳."},{"g":"～へ/～に(방향)","d":"가는 방향·목적지. で는 수단이라 バスで駅へ行く처럼 함께 쓴다."}],"ex":[{"jp":"毎朝[まいあさ]バスで学校[がっこう]に行[い]きます。","ko":"매일 아침 버스로 학교에 갑니다."},{"jp":"名前[なまえ]はボールペンで書[か]いてください。","ko":"이름은 볼펜으로 써 주세요."},{"jp":"昨日[きのう]図書館[としょかん]で勉強[べんきょう]しました。","ko":"어제 도서관에서 공부했습니다."}],"dr":[{"t":"make","q":"電車 / 行く → ～で","a":"電車で行く","hint":"수단 명사 뒤에 で."},{"t":"make","q":"はし / 食べる → ～で","a":"はしで食べる","hint":"도구 명사 뒤에 で."},{"t":"fill","q":"英語[えいご]（　）手紙[てがみ]を書[か]きました。","a":"で","opts":["で","に","を","が"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A7","https://bunpro.jp/ja/grammar_points/%E3%81%A7-by"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_109","t":"～に","ko":"~에, ~에게 (도착점·시간·대상·목적)","cat":"조사","conn":[{"w":"명사(장소·도착점)","f":"学校 + に 行く"},{"w":"명사(시각·날짜)","f":"7時 + に 起きる"},{"w":"명사(사람·대상)","f":"友達 + に 会う / 母 + に あげる"},{"w":"동사 ます형(이동 목적)","f":"買い + に 行く"},{"w":"명사(존재 장소)","f":"部屋 + に いる"}],"rule":["1. に는 형태가 바뀌지 않으며 명사 바로 뒤에 붙인다(学校＋に).","2. 이동 동사(行く・来る・帰る) 앞에서는 도착점을 나타낸다(学校に行きます).","3. 숫자가 들어간 시각·날짜 뒤에 붙여 때를 나타낸다(7時に). 今日·明日 같은 말에는 붙이지 않는다.","4. 시간과 장소를 함께 쓰면 に가 두 번 나올 수 있다(7時に学校に行きます)."],"why":"","nu":"한국어 '~에/~에게'와 대응하는 경우가 많지만 다른 점이 있다. 会う·乗る는 に를 쓴다(友達に会う, ×友達を会う, 電車に乗る). 今日·明日·毎日·去年 등 상대적 시간 표현에는 に를 붙이지 않는다(×明日に行く는 부자연스럽다). 동작이 일어나는 장소에는 で를 쓴다(×図書館に勉強する → 図書館で勉強する).","cmp":[{"g":"～へ","d":"이동의 방향을 나타낸다. 이동 동사에서는 に와 거의 바꿔 쓸 수 있지만, に는 도착점, へ는 방향 쪽에 초점이 있다."},{"g":"～で","d":"동작이 일어나는 장소(図書館で読む). に는 존재 장소(図書館にいる)나 도착점."}],"ex":[{"jp":"毎朝[まいあさ]7時[しちじ]に起[お]きます。","ko":"매일 아침 7시에 일어납니다."},{"jp":"週末[しゅうまつ]、友達[ともだち]に会[あ]いに行[い]きました。","ko":"주말에 친구를 만나러 갔습니다."},{"jp":"猫[ねこ]は机[つくえ]の下[した]にいます。","ko":"고양이는 책상 아래에 있습니다."}],"dr":[{"t":"make","q":"駅 / 行きます → ～に","a":"駅に行きます","hint":"도착점 명사 뒤에 に를 붙이고 이동 동사."},{"t":"make","q":"3時 / 帰ります → ～に","a":"3時に帰ります","hint":"숫자 시각 뒤에 に."},{"t":"fill","q":"バス（　）乗[の]って、学校[がっこう]へ行[い]きます。","a":"に","opts":["に","を","で","が"]}],"src":["https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei07_8.pdf","https://bunpro.jp/ja/grammar_points/%E3%81%AB"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_114","t":"～まで","ko":"~까지 (끝점·범위)","cat":"조사","conn":[{"w":"명사(장소)","f":"駅 + まで"},{"w":"명사(시간)","f":"5時 + まで"},{"w":"동사 사전형","f":"終わる + まで"},{"w":"から와 함께","f":"家から + 駅まで / 9時から + 5時まで"}],"rule":["1. まで는 형태가 바뀌지 않으며 명사 바로 뒤에 붙인다(駅＋まで).","2. 시작점 から와 짝지어 범위를 나타낸다(家から駅まで).","3. 동사는 사전형에 붙여 '~할 때까지'를 나타낸다(終わるまで待つ). 과거형에는 붙이지 않는다.","4. 뒤에는 그 기간 동안 계속되는 동작이 온다(5時まで働く)."],"why":"","nu":"まで는 그 시점·지점까지 동작이 '계속'됨을 나타낸다. 마감 시한 안에 한 번 일어나는 동작에는 までに를 쓴다(×5時まで宿題を出す → 5時までに宿題を出す). 한국어 '~까지'는 두 경우 모두 쓰므로 혼동이 잦다. 명사 뒤에서 '~조차, ~까지도'(子どもまで知っている)의 강조 용법도 있다.","cmp":[{"g":"～までに","d":"기한(그때까지 한 번 완료). まで는 그때까지 계속."},{"g":"～から","d":"시작점(~부터). まで와 짝지어 범위를 만든다."}],"ex":[{"jp":"家[いえ]から駅[えき]まで歩[ある]いて10分[じっぷん]です。","ko":"집에서 역까지 걸어서 10분입니다."},{"jp":"毎日[まいにち]9時[くじ]から5時[ごじ]まで働[はたら]きます。","ko":"매일 9시부터 5시까지 일합니다."},{"jp":"雨[あめ]がやむまで、ここで待[ま]ちましょう。","ko":"비가 그칠 때까지 여기서 기다립시다."}],"dr":[{"t":"make","q":"東京 / 大阪 → ～から～まで","a":"東京から大阪まで","hint":"시작점 から, 끝점 まで."},{"t":"make","q":"母が帰る / 待つ → ～まで","a":"母が帰るまで待つ","hint":"동사 사전형에 まで를 붙이고 계속 동작을 잇는다."},{"t":"fill","q":"昨日[きのう]は夜[よる]11時[じゅういちじ]（　）勉強[べんきょう]しました。","a":"まで","opts":["まで","までに","へ","を"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/200911.html","https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%A7"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_118","t":"～も","ko":"~도","cat":"조사","conn":[{"w":"명사","f":"私 + も"},{"w":"명사 + 조사","f":"東京に + も / 友達と + も"},{"w":"명사 + も ～ 명사 + も","f":"英語も 日本語も"}],"rule":["1. も는 형태가 바뀌지 않으며 명사 바로 뒤에 붙인다.","2. は・が・を 자리에서는 그 조사를 빼고 も로 바꾼다(私は → 私も, パンを → パンも).","3. に・で・と 등은 남기고 그 뒤에 も를 붙인다(東京にも, 友達とも).","4. 'AもBも'로 둘 다를 나타낸다(英語も日本語も話せます)."],"why":"","nu":"앞에 나온 것과 같은 내용이 다른 것에도 해당함을 나타낸다. 한국인은 ×私はも, ×パンをも처럼 は・を와 겹쳐 쓰는 실수를 하기 쉽다. 부정문과 함께 何も, 誰も 꼴로 '아무것도, 아무도'를 나타내기도 한다(何も食べない).","cmp":[{"g":"～は","d":"다른 것과 구별해 주제로 내세움(私は学生です). も는 앞의 것과 같다는 뜻을 더함(私も学生です)."}],"ex":[{"jp":"私[わたし]も寿司[すし]が好[す]きです。","ko":"저도 초밥을 좋아합니다."},{"jp":"姉[あね]は英語[えいご]も中国語[ちゅうごくご]も話[はな]せます。","ko":"언니는 영어도 중국어도 할 수 있습니다."},{"jp":"大阪[おおさか]にも行[い]きたいです。","ko":"오사카에도 가고 싶습니다."}],"dr":[{"t":"make","q":"私は行きます → ～も","a":"私も行きます","hint":"は를 빼고 그 자리에 も를 넣는다."},{"t":"make","q":"京都に行きました → ～も","a":"京都にも行きました","hint":"に는 남기고 그 뒤에 も를 붙인다."},{"t":"fill","q":"田中[たなか]さんは学生[がくせい]です。山田[やまだ]さん（　）学生[がくせい]です。","a":"も","opts":["も","を","で","へ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%82","https://www.seirei.ac.jp/media/about_jo-shi.pdf"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_005","t":"い形容詞＋くする／くなる","ko":"~하게 하다 / ~해지다","cat":"활용","conn":[{"w":"い형용사 + なる (변화)","f":"赤い → 赤くなる"},{"w":"い형용사 + する (변화시킴)","f":"明るい → 明るくする"},{"w":"いい (불규칙)","f":"いい → よくなる"},{"w":"~たい (い형 활용)","f":"行きたい → 行きたくなる"}],"rule":["い형용사의 어미 い를 く로 바꾼다(赤い → 赤く).","저절로 상태가 바뀌면 く 뒤에 なる를 붙인다(赤くなる = 빨개지다).","누군가 일부러 바꾸면 く 뒤에 する를 붙이고 대상에 を를 쓴다(部屋を明るくする).","いい는 よい를 바탕으로 よくなる・よくする가 된다."],"why":"형용사의 く형(연용형)은 뒤의 동사를 꾸미는 꼴이라 '빨갛게 + 되다', '밝게 + 하다'처럼 이어진다.","nu":"회화·문장 모두 쓴다. なる는 자연스러운 변화(顔が赤くなった), する는 사람의 의지로 바꾸는 것(音を小さくしてください). 과거 변화는 なりました・なった. 한국어 '-해지다'를 따라 'い + なる'(赤いなる)로 쓰거나 いい를 いくなる로 만드는 실수가 많다.","cmp":[{"g":"な형용사/명사 + に + なる/する","d":"な형용사와 명사는 く가 아니라 に를 붙인다(静かになる, 医者になる)."},{"g":"～ようになる","d":"동사로 능력·습관의 변화를 나타낸다(読めるようになる)."}],"ex":[{"jp":"りんごが赤[あか]くなりました。","ko":"사과가 빨개졌어요."},{"jp":"すみません、部屋[へや]を明[あか]るくしてください。","ko":"죄송한데 방을 밝게 해 주세요."},{"jp":"薬[くすり]を飲[の]んで、体[からだ]がよくなりました。","ko":"약을 먹고 몸이 좋아졌어요."}],"dr":[{"t":"make","q":"寒い → ～なりました","a":"寒くなりました","hint":"어미 い → く, 뒤에 なりました."},{"t":"make","q":"いい → ～なる","a":"よくなる","hint":"いい는 よい로 바꿔 よく + なる."},{"t":"fill","q":"この料理[りょうり]をもう少[すこ]し辛[から]（　）してください。","a":"く","opts":["く","に","な","で"]}],"src":["https://laits.utexas.edu/japanese/joshu/grammar/glist/y1/ch5/gl_y1_ch5_ku_naru.php"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_006","t":"な形容詞＋にする／になる","ko":"~하게 하다 / ~해지다","cat":"활용","conn":[{"w":"な형용사 + に + する (변화시킴)","f":"きれいな → きれいにする"},{"w":"な형용사 + に + なる (변화)","f":"元気な → 元気になる"},{"w":"명사 + に + なる/する","f":"医者になる, 日曜日にする"},{"w":"정중형","f":"静かになりました"}],"rule":["な형용사 뒤의 な를 に로 바꾼다(きれいな → きれいに).","누군가 일부러 바꾸면 に 뒤에 する를 붙이고 대상에 を를 쓴다(部屋をきれいにする).","저절로 상태가 바뀌면 に 뒤에 なる를 붙인다(元気になる).","명사도 같은 방식으로 명사 + に + なる/する를 쓴다."],"why":"に는 변화의 결과(도달점)를 나타내는 조사라서 'きれい한 상태로 + 하다/되다'가 된다.","nu":"회화·문장 모두 쓴다. する는 의지적으로 바꿈(静かにしてください = 조용히 해 주세요), なる는 자연스러운 변화. 명사 + にする는 '~로 정하다'(コーヒーにします = 커피로 할게요)라는 뜻도 있다. い형용사처럼 く를 붙이거나(きれいくなる) な를 남기는(きれいなになる) 실수가 흔하다. きれい는 い로 끝나지만 な형용사다.","cmp":[{"g":"い형용사 + く + なる/する","d":"い형용사는 어미 い를 く로 바꾼다(暗くなる). な형용사는 に."},{"g":"～ことにする","d":"동사로 '~하기로 결정하다'. な형용사にする는 상태를 바꾸는 것."}],"ex":[{"jp":"毎朝[まいあさ]、部屋[へや]をきれいにします。","ko":"매일 아침 방을 깨끗하게 해요."},{"jp":"よく寝[ね]て、元気[げんき]になりました。","ko":"푹 자서 건강해졌어요."},{"jp":"図書館[としょかん]では静[しず]かにしてください。","ko":"도서관에서는 조용히 해 주세요."}],"dr":[{"t":"make","q":"有名な → ～なりました","a":"有名になりました","hint":"な를 に로 바꾸고 なりました."},{"t":"make","q":"便利な / この町 → '이 동네가 편리해졌어요'","a":"この町は便利になりました","hint":"な → に + なりました."},{"t":"fill","q":"先生[せんせい]が来[き]ますから、静[しず]か（　）してください。","a":"に","opts":["に","く","な","の"]}],"src":["https://laits.utexas.edu/japanese/joshu/grammar/glist/y1/ch5/gl_y1_ch5_ku_naru.php"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_034","t":"～ている","ko":"~하고 있다 / ~해 있다(결과 상태)","cat":"활용","conn":[{"w":"1그룹 동사","f":"読む → 読んで + いる"},{"w":"2그룹 동사","f":"食べる → 食べて + いる"},{"w":"する","f":"勉強する → 勉強して + いる"},{"w":"来る","f":"来る → 来て + いる (와 있다)"},{"w":"변화 동사(결과)","f":"開く → 開いて + いる (열려 있다)"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 む・ぶ・ぬ는 んで(読む→読んで), 2그룹은 る를 떼고 て.","2. て형 뒤에 いる를 붙인다. いる는 2그룹 동사라 います, いた, いない로 활용한다.","3. 회화에서는 い가 빠져 読んでる, 食べてる처럼 줄기도 한다."],"why":"て형 + 존재 동사 いる(있다). 동작이 계속 '있는' 진행, 또는 변화가 끝난 결과가 '있는' 상태를 나타낸다.","nu":"읽다·먹다 같은 동작 동사는 진행(지금 ~하고 있다)이나 습관(매일 ~하고 있다), 열리다·부서지다·결혼하다 같은 변화 동사는 결과 상태(~해 있다)가 된다. 結婚している는 '결혼한 상태'이지 '결혼식 중'이 아니다. 知る는 '알고 있다'를 知っている로 하지만 부정은 知らない. 住む・働く도 보통 ている로 쓴다.","cmp":[{"g":"～てある","d":"누군가 의도적으로 해 둔 결과(타동사: 窓が開けてある). ～ている는 자동사의 결과 상태(窓が開いている)."}],"ex":[{"jp":"今[いま]、部屋[へや]で本[ほん]を読[よ]んでいます。","ko":"지금 방에서 책을 읽고 있어요."},{"jp":"姉[あね]は銀行[ぎんこう]で働[はたら]いています。","ko":"언니는 은행에서 일하고 있어요."},{"jp":"あれ、窓[まど]が開[あ]いていますね。","ko":"어, 창문이 열려 있네요."}],"dr":[{"t":"make","q":"書く → ～ている","a":"書いている","hint":"く → いて (イ음편) + いる"},{"t":"make","q":"待つ → ～ている","a":"待っている","hint":"つ → って (촉음편) + いる"},{"t":"fill","q":"兄[あに]はもう結婚[けっこん]して（　）。","a":"います","opts":["います","あります","おきます","みます"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201312.html"],"vf":1,"u":1,"g":1,"gp":"gg_N4_00"},{"id":"g4_056","t":"～にくい","ko":"~하기 어렵다, 잘 ~하지 않는다","cat":"활용","conn":[{"w":"1그룹 동사","f":"読む → 読み + にくい"},{"w":"2그룹 동사","f":"食べる → 食べ + にくい"},{"w":"する","f":"説明する → 説明し + にくい"},{"w":"来る","f":"来る → 来[き] + にくい"}],"rule":["1. 동사를 ます형으로 만든다. 1그룹은 어미 う단을 い단으로(読む→読み), 2그룹은 る를 뗀다(食べる→食べ).","2. 그 뒤에 にくい를 붙인다(読みにくい).","3. 결과는 い형용사처럼 활용한다(読みにくくない, 読みにくかった, 読みにくそう)."],"why":"にくい는 '어렵다'는 뜻의 難い(にくい)에서 왔다. 같은 한자를 がたい로 읽는 문어적 표현(信じがたい)도 있다.","nu":"행동이 하기 어렵다는 뜻과, 사물의 성질상 잘 그렇게 되지 않는다는 뜻(割れにくいコップ = 잘 깨지지 않는 컵)이 있다. 보통의 회화체·문장체 모두 가능. 見にくい(보기 어렵다)는 醜い(추하다)와 발음이 같아 혼동 주의. 사전형에 바로 붙이는 실수(×読むにくい)가 많다.","cmp":[{"g":"～づらい","d":"辛い(괴롭다)에서 온 말로, 하는 사람이 심리적·신체적 부담을 느낄 때 쓴다. 물건의 성질(잘 안 깨진다)에는 쓰지 않는다."},{"g":"～やすい","d":"반대 의미로 '~하기 쉽다'."}],"ex":[{"jp":"この字[じ]は小[ちい]さくて読[よ]みにくいです。","ko":"이 글씨는 작아서 읽기 어려워요."},{"jp":"この靴[くつ]は重[おも]くて歩[ある]きにくかった。","ko":"이 신발은 무거워서 걷기 힘들었다."},{"jp":"このコップは割[わ]れにくいので、子[こ]どもにも安心[あんしん]です。","ko":"이 컵은 잘 깨지지 않아서 아이에게도 안심이에요."}],"dr":[{"t":"make","q":"使う → ～にくい","a":"使いにくい","hint":"う → い (い단) + にくい"},{"t":"make","q":"覚える → ～にくい","a":"覚えにくい","hint":"2그룹: る를 떼고 + にくい"},{"t":"fill","q":"先生[せんせい]の説明[せつめい]は早口[はやくち]で、分[わ]かり（　）。","a":"にくい","opts":["にくい","なさい","たがる","そうだ"]}],"src":["https://nihongokyoshi-net.com/2019/05/01/jlptn4-grammar-nikui/","https://guidetojapanese.org/learn/grammar/easyhard"],"vf":1,"u":2,"g":1,"gp":"gg_N4_00"},{"id":"g4_057","t":"～やすい","ko":"~하기 쉽다, ~하기 편하다, 잘 ~한다","cat":"활용","conn":[{"w":"1그룹 동사","f":"書く → 書き + やすい"},{"w":"2그룹 동사","f":"食べる → 食べ + やすい"},{"w":"する","f":"運転する → 運転し + やすい"},{"w":"来る","f":"来る → 来[き] + やすい"}],"rule":["1. 동사를 ます형으로 만든다. 2그룹은 る를 뗀다(食べる→食べ).","2. 1그룹은 어미 う단을 い단으로 바꾼다(書く→書き).","3. 그 뒤에 やすい를 붙인다(食べやすい).","4. 결과는 い형용사처럼 활용한다(食べやすくない, 食べやすかった)."],"why":"やすい는 '쉽다, 편하다'는 뜻의 형용사 易い(やすい)를 ます형 뒤에 붙인 것이다. 값이 싸다는 安い와는 다른 말이다.","nu":"하기 쉽다·편하다는 긍정적 의미와, 성질상 그렇게 되기 쉽다는 의미(壊れやすい = 잘 망가진다, 太りやすい = 살찌기 쉽다)가 있다. 후자는 좋지 않은 경향에도 쓴다. 사전형에 붙이지 않도록 주의(×食べるやすい). 話しやすい人(말 걸기 편한 사람)처럼 사람에게도 쓴다.","cmp":[{"g":"～にくい","d":"반대 의미로 '~하기 어렵다'."},{"g":"簡単だ","d":"일 자체가 간단하다는 형용사. ～やすい는 특정 동작이 하기 쉽다는 뜻으로 동사에 붙는다."}],"ex":[{"jp":"この本[ほん]は字[じ]が大[おお]きくて読[よ]みやすい。","ko":"이 책은 글씨가 커서 읽기 쉽다."},{"jp":"田中[たなか]さんは優[やさ]しくて話[はな]しやすい人[ひと]です。","ko":"다나카 씨는 상냥해서 말 걸기 편한 사람이에요."},{"jp":"冬[ふゆ]は風邪[かぜ]をひきやすいので、気[き]をつけてください。","ko":"겨울에는 감기에 걸리기 쉬우니까 조심하세요."}],"dr":[{"t":"make","q":"住む → ～やすい","a":"住みやすい","hint":"む → み (い단) + やすい"},{"t":"make","q":"着る → ～やすい","a":"着やすい","hint":"2그룹: る를 떼고 + やすい"},{"t":"fill","q":"このペンは軽[かる]くて書[か]き（　）です。","a":"やすい","opts":["やすい","なさい","ながら","すぎ"]}],"src":["https://guidetojapanese.org/learn/grammar/easyhard"],"vf":1,"u":2,"g":1,"gp":"gg_N4_00"},{"id":"g4_070","t":"～出す","ko":"(갑자기) ~하기 시작하다","cat":"활용","conn":[{"w":"1그룹 동사","f":"降る → 降り + 出す"},{"w":"2그룹 동사","f":"考える → 考え + 出す"},{"w":"불규칙","f":"する → し + 出す, 来る → 来(き) + 出す"}],"rule":["1. 동사를 ます형(연용형)으로 만든다. 1그룹은 어미 う단을 い단으로 바꾼다: 降る → 降り.","2. 2그룹은 る를 뗀다: 考える → 考え.","3. 그 뒤에 出す를 붙인다: 降り出す.","4. 出す는 1그룹 동사로 활용한다: 降り出した / 降り出します."],"why":"出す(꺼내다, 내다)가 다른 동사의 ます형 뒤에 붙어 '동작이 밖으로 터져 나오다', 즉 시작의 뜻을 더하는 복합동사가 된다.","nu":"주로 의지와 관계없이 갑자기 시작되는 일(雨が降り出す, 赤ちゃんが泣き出す, 急に笑い出す)에 쓴다. 계획적으로 시작하는 일에는 ～始める가 자연스럽다(×明日から勉強し出す → 勉強し始める). 本を出す(꺼내다)처럼 단독 동사로 쓰인 出す와 구별해야 한다.","cmp":[{"g":"～始める","d":"의도적으로 시작하는 일에도 두루 쓴다. ～出す는 갑작스럽고 통제하기 어려운 시작."}],"ex":[{"jp":"急[きゅう]に雨[あめ]が降[ふ]り出した。","ko":"갑자기 비가 내리기 시작했다."},{"jp":"赤[あか]ちゃんが夜中[よなか]に泣[な]き出しました。","ko":"아기가 한밤중에 울기 시작했어요."},{"jp":"犬[いぬ]を見[み]て、子[こ]どもが走[はし]り出した。","ko":"개를 보고 아이가 달려 나가기 시작했다."}],"dr":[{"t":"make","q":"笑う → ～出した","a":"笑い出した","hint":"う → い (ます형) + 出した"},{"t":"make","q":"泣く → ～出しました","a":"泣き出しました","hint":"く → き (ます형) + 出しました"},{"t":"fill","q":"空[そら]が暗[くら]くなって、雨[あめ]が降[ふ]り（　）。","a":"出した","opts":["出した","終わった","すぎた","やすい"]}],"src":["https://bunpro.jp/grammar_points/だす"],"vf":1,"u":2,"g":1,"gp":"gg_N4_00"},{"id":"g4_072","t":"～終わる","ko":"다 ~하다, ~하기를 끝내다","cat":"활용","conn":[{"w":"1그룹 동사","f":"読む → 読み + 終わる"},{"w":"2그룹 동사","f":"食べる → 食べ + 終わる"},{"w":"불규칙","f":"する → し + 終わる"}],"rule":["1. 동사를 ます형으로 만든다. 1그룹은 어미 う단을 い단으로 바꾼다: 読む → 読み.","2. 2그룹은 る를 뗀다: 食べる → 食べ.","3. 뒤에 終わる를 붙인다: 読み終わる.","4. 終わる는 1그룹 동사로 활용한다: 読み終わった / 読み終わりました."],"why":"終わる(끝나다)가 다른 동사의 ます형 뒤에 붙어 그 동작이 끝까지 완료됨을 나타내는 복합동사가 된다. 타동사형 終える를 붙인 ～終える도 같은 뜻이다.","nu":"회화·문어 모두 쓴다. 처음과 끝이 있는 동작(読む, 食べる, 書く)에 쓰며, 끝이 없는 상태나 순간 동사에는 어색하다(×死に終わる). 한국어 '다 먹었다'를 食べてしまった로만 옮기기 쉬운데, てしまう는 아쉬움·실수의 뉘앙스가 더해진다.","cmp":[{"g":"～てしまう","d":"완료 외에 후회·뜻밖의 결과 뉘앙스가 붙는다. ～終わる는 단순히 동작이 끝남."},{"g":"～始める","d":"반대로 동작의 시작."}],"ex":[{"jp":"この本[ほん]はもう読[よ]み終[お]わりました。","ko":"이 책은 벌써 다 읽었어요."},{"jp":"みんなが食[た]べ終[お]わったら、片付[かたづ]けましょう。","ko":"모두 다 먹으면 정리합시다."},{"jp":"レポートを書[か]き終[お]わるまで、寝[ね]られない。","ko":"리포트를 다 쓸 때까지 잘 수 없다."}],"dr":[{"t":"make","q":"書く → ～終わった","a":"書き終わった","hint":"く → き (ます형) + 終わった"},{"t":"make","q":"使う → ～終わったら","a":"使い終わったら","hint":"う → い (ます형) + 終わったら"},{"t":"fill","q":"宿題[しゅくだい]をやり（　）から、遊[あそ]びに行[い]く。","a":"終わって","opts":["終わって","出して","やすくて","すぎて"]}],"src":["https://bunpro.jp/grammar_points/おわる"],"vf":1,"u":2,"g":1,"gp":"gg_N4_01"},{"id":"g4_073","t":"～続ける","ko":"계속 ~하다","cat":"활용","conn":[{"w":"1그룹 동사","f":"走る → 走り + 続ける"},{"w":"2그룹 동사","f":"考える → 考え + 続ける"},{"w":"불규칙","f":"する → し + 続ける, 来る → 来(き) + 続ける"}],"rule":["1. 동사를 ます형으로 만든다. 1그룹은 어미 う단을 い단으로 바꾼다: 走る(1그룹) → 走り.","2. 2그룹은 る를 뗀다: 考える → 考え.","3. 뒤에 続ける를 붙인다: 走り続ける.","4. 続ける는 2그룹 동사로 활용한다: 走り続けた / 走り続けています."],"why":"続ける(계속하다)가 다른 동사의 ます형 뒤에 붙어, 그 동작이 끊기지 않고 이어짐을 나타내는 복합동사가 된다.","nu":"회화·문어 모두 쓴다. 의지적 동작(走る, 勉強する)뿐 아니라 雨が降り続ける처럼 자연현상에도 쓴다. ている보다 '계속'이 강조된다. 走る・帰る・入る는 る로 끝나도 1그룹이라 走り続ける가 되는 점에 주의(×走続ける).","cmp":[{"g":"～ている","d":"진행 중인 동작·상태를 나타낼 뿐. ～続ける는 지속·계속을 강조."},{"g":"～出す","d":"동작의 (갑작스러운) 시작. ～続ける는 시작된 동작이 이어짐."}],"ex":[{"jp":"彼[かれ]は三時間[さんじかん]も走[はし]り続けた。","ko":"그는 세 시간이나 계속 달렸다."},{"jp":"昨日[きのう]から雨[あめ]が降[ふ]り続けています。","ko":"어제부터 비가 계속 내리고 있어요."},{"jp":"これからも日本語[にほんご]の勉強[べんきょう]を続[つづ]けたいです。","ko":"앞으로도 일본어 공부를 계속하고 싶어요."}],"dr":[{"t":"make","q":"待つ → ～続けた","a":"待ち続けた","hint":"つ → ち (ます형) + 続けた"},{"t":"make","q":"歩く → ～続けています","a":"歩き続けています","hint":"く → き (ます형) + 続けています"},{"t":"fill","q":"一日中[いちにちじゅう]、雪[ゆき]が降[ふ]り（　）。","a":"続けた","opts":["続けた","出した","終わった","すぎた"]}],"src":["https://bunpro.jp/grammar_points/つづける"],"vf":1,"u":2,"g":1,"gp":"gg_N4_01"},{"id":"g4_022","t":"～たことがある","ko":"~한 적이 있다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"行く → 行ったことがある"},{"w":"2그룹 동사","f":"食べる → 食べたことがある"},{"w":"する","f":"する → したことがある"},{"w":"来る","f":"来る → 来(き)たことがある"},{"w":"부정(없다)","f":"見る → 見たことがない"}],"rule":["동사를 た형으로 바꾼다. 行く는 예외로 く가 った가 된다(行く → 行った).","た형 뒤에 こと(일·경험) + が + ある를 붙인다: 行った + ことがある.","경험이 없으면 ある 대신 ない를 쓴다(行ったことがない). 정중형은 ことがあります / ありません."],"why":"こと는 '일, 사실'을 뜻하는 형식명사로, '~한 일이 있다'가 그대로 '~한 경험이 있다'가 된다.","nu":"회화·문어 모두 쓴다. 과거 어느 때의 '경험'을 말하므로 어제처럼 가까운 일이나 매일 하는 일(朝ご飯を食べたことがある ×)에는 쓰지 않는다. こと를 の로 바꿀 수 없다. 사전형 + ことがある(行くことがある)는 '~할 때가 있다(가끔)'라는 다른 뜻이니 혼동 주의.","cmp":[{"g":"～ることがある","d":"사전형에 붙어 '가끔 ~할 때가 있다'. た형은 '경험'."}],"ex":[{"jp":"京都[きょうと]へ行[い]ったことがあります。","ko":"교토에 가 본 적이 있어요."},{"jp":"納豆[なっとう]を食[た]べたことがありますか。","ko":"낫토를 먹어 본 적이 있나요?"},{"jp":"私[わたし]は一度[いちど]も入院[にゅういん]したことがない。","ko":"나는 한 번도 입원한 적이 없다."}],"dr":[{"t":"make","q":"見る → '본 적이 있다'","a":"見たことがある","hint":"る를 떼고 た + ことがある."},{"t":"make","q":"泳ぐ → '수영한 적이 없다'","a":"泳いだことがない","hint":"ぐ는 いだ로 바꾸고 ことがない."},{"t":"fill","q":"富士山[ふじさん]に登[のぼ]った（　）があります。","a":"こと","opts":["こと","ため","はず","まま"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%81%93%E3%81%A8%E3%81%8C%E3%81%82%E3%82%8B","https://tofugu.com/japanese-grammar/takotogaaru"],"vf":1,"u":2,"g":1,"gp":"gg_N4_01"},{"id":"g4_025","t":"～たほうがいい","ko":"~하는 편이 좋다, ~하는 게 좋겠다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"休む → 休んだほうがいい"},{"w":"2그룹 동사","f":"寝る → 寝たほうがいい"},{"w":"する","f":"する → したほうがいい"},{"w":"来る","f":"来る → 来(き)たほうがいい"},{"w":"부정(하지 않는 편이)","f":"飲む → 飲まないほうがいい"}],"rule":["동사를 た형으로 바꾼다(寝る → 寝た: 2그룹은 る를 떼고 た).","た형 뒤에 ほう(方) + が + いい를 붙인다: 寝た + ほうがいい.","'~하지 않는 편이 좋다'는 た형이 아니라 ない형에 붙인다(飲まないほうがいい, 飲まなかったほうがいい ×). 정중형은 ほうがいいです."],"why":"ほう(方)는 '쪽, 방향'이라는 뜻이라 '~한 쪽이 좋다', 즉 여러 선택지 중 그쪽이 낫다는 충고가 된다.","nu":"상대에게 직접 하는 꽤 강한 충고로, 하지 않으면 좋지 않은 일이 생길 수 있다는 느낌이 있다. 윗사람에게는 직접 쓰지 않는 게 좋고, 부드럽게 말하려면 ～たらどうですか・～ばいい 등을 쓴다. 사전형 + ほうがいい(寝るほうがいい)도 쓰이지만 일반론·비교에 가깝고, 특정한 상대에게 하는 충고에는 た형이 자연스럽다. 한국어 '~하는 게 좋다'에 끌려 사전형으로 쓰는 실수가 많다.","cmp":[{"g":"～ばいい","d":"'~하면 된다' 방법 제시로 더 부드러움. たほうがいい는 다른 선택보다 낫다는 직접적 충고."}],"ex":[{"jp":"顔色[かおいろ]が悪[わる]いですよ。今日[きょう]は早[はや]く寝[ね]たほうがいいです。","ko":"안색이 안 좋아요. 오늘은 일찍 자는 게 좋겠어요."},{"jp":"雨[あめ]が降[ふ]りそうだから、傘[かさ]を持[も]って行[い]ったほうがいいよ。","ko":"비가 올 것 같으니까 우산을 가져가는 게 좋아."},{"jp":"熱[ねつ]があるときは、お風呂[ふろ]に入[はい]らないほうがいい。","ko":"열이 있을 때는 목욕하지 않는 게 좋다."}],"dr":[{"t":"make","q":"休む → '쉬는 게 좋다'","a":"休んだほうがいい","hint":"む는 んだ로 바꾸고 + ほうがいい."},{"t":"make","q":"たばこを吸う → '피우지 않는 게 좋다'","a":"たばこを吸わないほうがいい","hint":"부정은 ない형(吸わない) + ほうがいい."},{"t":"fill","q":"風邪[かぜ]なら、薬[くすり]を飲[の]んだ（　）いいですよ。","a":"ほうが","opts":["ほうが","ために","つもりで","ところが"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%81%BB%E3%81%86%E3%81%8C%E3%81%84%E3%81%84"],"vf":1,"u":2,"g":1,"gp":"gg_N4_01"},{"id":"g4_027","t":"～つもり","ko":"~할 생각(작정)이다, ~할 예정이다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"行く + つもり"},{"w":"동사 ない형","f":"行かない + つもり"},{"w":"동사 た형(했다고 생각함)","f":"言った + つもり"},{"w":"명사","f":"冗談の + つもり"}],"rule":["동사 사전형(보통형) 뒤에 つもり를 붙인다. 동사 형태는 바뀌지 않는다(行く + つもり).","문장 끝에서는 だ/です를 붙인다: 行くつもりです. ます형에는 붙이지 않는다(行きますつもり ×).","'안 할 생각'은 ない형 + つもり(行かないつもり), 더 강한 '할 생각이 전혀 없다'는 つもりはない(行くつもりはない)."],"why":"","nu":"미리 정해 둔 자기 의도·계획을 말한다(그 자리에서 정한 일에는 ～よう(意向形)と思う가 자연스럽다). 3인칭의 의도에는 つもりらしい・つもりのようだ처럼 추측을 붙이고, 2인칭에는 주로 질문으로 쓴다. 윗사람에게 '~するつもりですか'라고 묻는 것은 실례가 될 수 있어 '～ご予定ですか' 등을 쓴다. た형 + つもり는 '~했다고 생각한다(실제는 다를 수 있음)'라는 별도 용법.","cmp":[{"g":"～(よ)うと思う","d":"지금 막 마음먹은 생각에도 씀. つもり는 이미 굳힌 계획."},{"g":"～予定だ","d":"정해진 일정(남과 정한 것 포함). つもり는 개인의 의도."}],"ex":[{"jp":"夏休[なつやす]みに北海道[ほっかいどう]へ行[い]くつもりです。","ko":"여름방학에 홋카이도에 갈 생각이에요."},{"jp":"今年[ことし]はお酒[さけ]を飲[の]まないつもりだ。","ko":"올해는 술을 안 마실 작정이다."},{"jp":"ちゃんと説明[せつめい]したつもりですが、分[わ]かりにくかったですか。","ko":"제대로 설명했다고 생각하는데, 알기 어려웠나요?"}],"dr":[{"t":"make","q":"買う → '살 생각입니다'","a":"買うつもりです","hint":"사전형 그대로 + つもりです."},{"t":"make","q":"結婚する → '결혼할 생각은 없다'","a":"結婚するつもりはない","hint":"사전형 + つもりはない."},{"t":"fill","q":"来年[らいねん]、日本[にほん]で働[はたら]く（　）です。","a":"つもり","opts":["つもり","ながら","ほど","しか"]}],"src":["https://www.tofugu.com/japanese-grammar/tsumori/"],"vf":1,"u":2,"g":1,"gp":"gg_N4_01"},{"id":"g4_029","t":"～てある","ko":"~해져 있다, ~해 두었다 (누군가 일부러 한 결과)","cat":"문말표현","conn":[{"w":"타동사(1그룹)","f":"書く → 書いてある"},{"w":"타동사(2그룹)","f":"開ける → 開けてある"},{"w":"타동사 する","f":"予約する → 予約してある"}],"rule":["타동사를 て형으로 바꾼다(開ける → 開けて: 2그룹은 る를 떼고 て).","て형 뒤에 ある를 붙인다: 開けて + ある.","원래 を로 표시되던 대상이 が로 바뀌어 주어 자리에 온다(窓を開ける → 窓が開けてある). 준비했다는 점을 강조할 때는 を를 그대로 쓰기도 한다(ホテルを予約してある)."],"why":"","nu":"누군가가 의도를 갖고 한 행동의 결과가 지금 남아 있음을 말하며, 한 사람은 보통 말하지 않는다. 타동사에만 붙는다. 자동사의 결과 상태는 ～ている를 쓴다(窓が開いている). 그래서 終わる 같은 자동사로 '終わってある'라고 하는 것은 틀린 문장이다(終わっている / 終わらせてある가 맞음). 회화·문어 모두 쓴다.","cmp":[{"g":"自動詞 + ている","d":"窓が開いている: 그냥 열려 있는 상태. 窓が開けてある: 누군가 일부러 열어 둔 상태."},{"g":"～ておく","d":"'미리 ~해 두다'라는 행위 자체. てある는 그 결과 상태."}],"ex":[{"jp":"窓[まど]が開[あ]けてあります。","ko":"창문이 열려 있어요(누군가 열어 두었어요)."},{"jp":"黒板[こくばん]に明日[あした]の予定[よてい]が書[か]いてある。","ko":"칠판에 내일 일정이 적혀 있다."},{"jp":"レストランはもう予約[よやく]してあるから、大丈夫[だいじょうぶ]だよ。","ko":"레스토랑은 이미 예약해 두었으니까 괜찮아."}],"dr":[{"t":"make","q":"電気をつける → '불이 켜져 있다(누군가 켜 둠)'","a":"電気がつけてある","hint":"を를 が로 바꾸고, つける → つけて + ある."},{"t":"make","q":"壁に絵を飾る → '벽에 그림이 걸려 있다'","a":"壁に絵が飾ってある","hint":"る는 って로 바꾸고 + ある, 대상은 が."},{"t":"fill","q":"冷蔵庫[れいぞうこ]にジュースが冷[ひ]やして（　）。","a":"あります","opts":["あります","います","あげます","みます"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%81%82%E3%82%8B"],"vf":1,"u":2,"g":1,"gp":"gg_N4_01"},{"id":"g4_030","t":"～ていく","ko":"~해 가다, (앞으로) 계속 ~해 나가다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"続く → 続いていく"},{"w":"2그룹 동사","f":"増える → 増えていく"},{"w":"する","f":"する → していく"},{"w":"(이동) 1그룹 동사","f":"飛ぶ → 飛んでいく"}],"rule":["동사를 て형으로 바꾼다(増える → 増えて: 2그룹은 る를 떼고 て).","て형 뒤에 いく를 붙인다: 増えて + いく. いく는 行く와 같은 활용을 하며 보통 히라가나로 쓴다.","いく 부분이 활용한다(増えていきます, 増えていった). 회화에서는 い를 줄여 増えてく라고도 한다."],"why":"いく(行く, 가다)가 보조동사가 되어 '지금 여기서 멀어져 앞으로 나아간다'는 방향을 더한다. 그래서 공간에서는 '~하며 가다', 시간에서는 '지금부터 미래로 계속 변해 가다'가 된다.","nu":"① 말하는 사람에게서 멀어지는 이동(鳥が飛んでいく) ② 지금부터 미래로 진행되는 변화(これから寒くなっていく) ③ 지금부터 계속하는 동작(これからも頑張っていきます). 과거부터 지금까지 쌓인 변화에는 てくる를 쓴다. 한국어 '~해 가다'와 비슷해 쓰기 쉽지만 과거→현재 방향에 ていく를 쓰는 실수에 주의.","cmp":[{"g":"～てくる","d":"과거에서 지금까지(또는 나에게로) 다가오는 변화·이동. ていく는 지금에서 미래로(나에게서 멀어짐)."}],"ex":[{"jp":"これから、だんだん寒[さむ]くなっていきます。","ko":"앞으로 점점 추워져 갑니다."},{"jp":"この町[まち]の人口[じんこう]は、これからも増[ふ]えていくでしょう。","ko":"이 마을의 인구는 앞으로도 늘어 가겠지요."},{"jp":"鳥[とり]が空[そら]へ飛[と]んでいった。","ko":"새가 하늘로 날아갔다."}],"dr":[{"t":"make","q":"変わる → '변해 가다'","a":"変わっていく","hint":"る(1그룹)는 って로 바꾸고 + いく."},{"t":"make","q":"続ける → '계속해 가겠습니다'","a":"続けていきます","hint":"2그룹: る를 떼고 て + いきます."},{"t":"fill","q":"これからも日本語[にほんご]の勉強[べんきょう]を続[つづ]けて（　）つもりです。","a":"いく","opts":["いく","くる","ある","くれる"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%81%84%E3%81%8F"],"vf":1,"u":3,"g":1,"gp":"gg_N4_01"},{"id":"g4_044","t":"～てしまう","ko":"~해 버리다, (그만) ~하고 말다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"言う → 言って + しまう"},{"w":"1그룹 동사(む·ぶ·ぬ)","f":"飲む → 飲んで + しまう"},{"w":"2그룹 동사","f":"食べる → 食べて + しまう"},{"w":"する 동사","f":"寝坊する → 寝坊して + しまう"},{"w":"来る","f":"来る → 来て(きて) + しまう"}],"rule":["1. 동사를 て형으로 바꾼다(食べる→食べて, 飲む→飲んで).","2. て형 뒤에 しまう를 붙인다: 食べて + しまう.","3. しまう는 1그룹 동사라 과거는 어미 う를 った로 바꿔 しまった, 정중체는 しまいました.","4. 회화에서는 てしまう→ちゃう, でしまう→じゃう로 줄인다(食べちゃった, 飲んじゃった)."],"why":"しまう(仕舞う)는 본래 '끝내다, 치우다'라는 동사다. 보조동사로 붙으면 동작이 완전히 끝나 되돌릴 수 없게 되었음을 나타내고, 여기서 '다 ~해 버리다'와 '유감·실수'의 뜻이 나온다.","nu":"두 가지 뜻이 있다. ① 완료: 끝까지 다 해 버림(宿題を全部やってしまった). ② 유감·실수: 의도하지 않았거나 후회되는 일(財布を忘れてしまった). 축약형 ちゃう/じゃう는 회화체이고, 격식 자리에서는 てしまいました를 쓴다. 한국어 '버리다'에 끌려 물건을 버리다(捨てる)와 혼동하지 말 것.","cmp":[{"g":"～ておく","d":"나중을 위해 미리 해 둔다는 준비의 뜻. てしまう는 완료나 유감."}],"ex":[{"jp":"電車[でんしゃ]に傘[かさ]を忘[わす]れてしまいました。","ko":"전철에 우산을 두고 내려 버렸어요."},{"jp":"昨日[きのう]の夜[よる]、ケーキを全部[ぜんぶ]食[た]べちゃった。","ko":"어젯밤에 케이크를 전부 먹어 버렸어."},{"jp":"弟[おとうと]が私[わたし]のジュースを飲[の]んじゃった。","ko":"남동생이 내 주스를 마셔 버렸어."}],"dr":[{"t":"make","q":"飲む → ～てしまう (과거)","a":"飲んでしまった","hint":"む는 んで, しまう의 과거는 しまった."},{"t":"make","q":"食べてしまった → 회화 축약형","a":"食べちゃった","hint":"てしまう는 ちゃう로 줄어든다(과거 ちゃった)."},{"t":"fill","q":"寝坊[ねぼう]して、バスに遅[おく]れて（　）。","a":"しまった","opts":["しまった","おいた","あげた","みた"]}],"src":["https://bunpro.jp/grammar_points/172","https://laits.utexas.edu/japanese/joshu/grammar/glist/y1/ch6/gl_y1_ch6_teshimau.php"],"vf":1,"u":3,"g":1,"gp":"gg_N4_01"},{"id":"g4_045","t":"～てほしい","ko":"(남이) ~해 주었으면 좋겠다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"読む → 読んで + ほしい"},{"w":"2그룹 동사","f":"見る → 見て + ほしい"},{"w":"する 동사","f":"勉強する → 勉強して + ほしい"},{"w":"来る","f":"来る → 来て(きて) + ほしい"},{"w":"부정","f":"言う → 言わないで + ほしい"}],"rule":["1. 동사를 て형으로 바꾼다(読む→読んで: む는 んで).","2. て형 뒤에 ほしい를 붙인다: 読んで + ほしい.","3. ほしい는 い형용사처럼 활용한다(ほしくない, ほしかった, 정중체 ほしいです).","4. 해 주길 바라는 사람은 に로 나타낸다(母に読んでほしい). '~하지 않았으면'은 ない형 + で + ほしい."],"why":"ほしい(欲しい, 갖고 싶다)가 て형 뒤에 붙어 '남의 행동이나 어떤 일이 일어나기를 원한다'는 뜻이 된다.","nu":"말하는 사람이 남에게 바라는 마음. 자기 행동은 ～たい를 쓴다. 상대에게 직접 말하면 꽤 강한 요구로 들려 윗사람에게는 무례할 수 있으므로 ～てもらいたい, ～ていただきたい를 쓴다. 사람이 아닌 일·상황에는 が를 쓴다(雨がやんでほしい). 제3자의 바람은 ～てほしがる나 ～てほしいそうだ로 말한다.","cmp":[{"g":"～たい","d":"자기 자신이 하고 싶은 것. ～てほしい는 남이 해 주길 바라는 것."},{"g":"～てもらいたい","d":"뜻은 거의 같지만 '받는다'는 고마움이 담겨 조금 부드럽다."}],"ex":[{"jp":"母[はは]にこの本[ほん]を読[よ]んでほしい。","ko":"엄마가 이 책을 읽어 줬으면 좋겠다."},{"jp":"早[はや]く雨[あめ]がやんでほしいです。","ko":"빨리 비가 그쳤으면 좋겠어요."},{"jp":"このことは誰[だれ]にも言[い]わないでほしい。","ko":"이 일은 아무에게도 말하지 않았으면 좋겠어."}],"dr":[{"t":"make","q":"来る → ～てほしい","a":"来てほしい","hint":"来る의 て형은 来て(きて), 뒤에 ほしい."},{"t":"make","q":"勉強する → ～てほしい","a":"勉強してほしい","hint":"する는 して로 바꾸고 ほしい를 붙인다."},{"t":"fill","q":"子供[こども]にもっと野菜[やさい]を食[た]べて（　）。","a":"ほしい","opts":["ほしい","たい","ながら","つもり"]}],"src":["https://www.tofugu.com/japanese-grammar/tehoshii/","https://laits.utexas.edu/japanese/joshu/grammar/glist/y2/ch6/gl_y2_ch6_tehoshii.php","https://bunpro.jp/grammar_points/てほしい"],"vf":1,"u":3,"g":1,"gp":"gg_N4_01"},{"id":"g4_046","t":"～てみる","ko":"~해 보다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"飲む → 飲んで + みる"},{"w":"1그룹 行く(예외)","f":"行く → 行って + みる"},{"w":"2그룹 동사","f":"着る → 着て + みる"},{"w":"する 동사","f":"電話する → 電話して + みる"}],"rule":["1. 동사를 て형으로 바꾼다(着る→着て: 2그룹은 る를 떼고 て, 飲む→飲んで).","2. て형 뒤에 みる를 붙인다: 着て + みる.","3. みる는 2그룹 동사처럼 활용한다(みます, みた, みたい, みよう, みてください).","4. 보조동사이므로 한자 見る가 아니라 히라가나 みる로 쓰는 것이 보통이다."],"why":"見る(보다)가 보조동사로 쓰여 '일단 해 보고 결과가 어떤지 본다'는 뜻이 된다. 한국어 '~해 보다'와 만들어지는 방식이 같다.","nu":"시험 삼아 해 보고 결과를 확인하는 표현. てみた는 실제로 해 봤다는 뜻이라, 하려고 했지만 못 한 경우에는 쓰지 않고 ～ようとした를 쓴다. 자주 쓰는 형태: てみたい(해 보고 싶다), てみよう(해 보자), てみてください(해 보세요), てみたら(해 봤더니).","cmp":[{"g":"～ようとする","d":"하려고 시도함. 실제로 못 했어도 쓸 수 있다. ～てみる는 실제로 해 본 것."}],"ex":[{"jp":"この服[ふく]を着[き]てみてもいいですか。","ko":"이 옷 입어 봐도 돼요?"},{"jp":"新[あたら]しいレストランに行[い]ってみよう。","ko":"새 레스토랑에 가 보자."},{"jp":"日本[にほん]のお酒[さけ]を飲[の]んでみたら、おいしかった。","ko":"일본 술을 마셔 봤더니 맛있었다."}],"dr":[{"t":"make","q":"食べる → ～てみる","a":"食べてみる","hint":"2그룹: る를 떼고 て + みる."},{"t":"make","q":"行く → ～てみたい","a":"行ってみたい","hint":"行く의 て형은 예외로 行って, みる→みたい."},{"t":"fill","q":"わからなかったら、先生[せんせい]に聞[き]いて（　）ください。","a":"みて","opts":["みて","ほしくて","たくて","ばかりで"]}],"src":["https://www.tofugu.com/japanese-grammar/temiru/"],"vf":1,"u":3,"g":1,"gp":"gg_N4_01"},{"id":"g4_051","t":"～ないことにする","ko":"~하지 않기로 하다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"飲む → 飲まない + ことにする"},{"w":"2그룹 동사","f":"食べる → 食べない + ことにする"},{"w":"する 동사","f":"運転する → 運転しない + ことにする"},{"w":"来る","f":"来る → 来ない(こない) + ことにする"}],"rule":["1. 동사를 ない형으로 바꾼다. 1그룹은 어미 う단→あ단 + ない(飲む→飲まない), 2그룹은 る→ない, する→しない, 来る→来ない.","2. ない형 뒤에 ことにする를 붙인다: 飲まない + ことにする.","3. 막 정한 결정은 ことにした, 정해서 계속 지키는 습관은 ことにしている."],"why":"こと(것) + に + する(~로 하다). '~하지 않는 것으로 한다'는 구조로, 말하는 사람이 자기 의지로 정했음을 나타낸다.","nu":"주어 자신의 결정이다. 남이나 상황이 정한 것은 ～ないことになる. 'ないことにする(안 하기로 하다)'와 'ことにしない(~하기로 하지 않다)'는 뜻이 다르니 부정의 위치에 주의.","cmp":[{"g":"～ないことになる","d":"내 의지가 아니라 회사·규칙·상황에 의해 '안 하게 됨'."}],"ex":[{"jp":"健康[けんこう]のために、お酒[さけ]を飲[の]まないことにした。","ko":"건강을 위해 술을 마시지 않기로 했다."},{"jp":"夜[よる]は甘[あま]いものを食[た]べないことにしています。","ko":"밤에는 단것을 먹지 않기로 하고 있어요."},{"jp":"雨[あめ]だから、今日[きょう]は出[で]かけないことにしよう。","ko":"비가 오니까 오늘은 외출하지 않기로 하자."}],"dr":[{"t":"make","q":"買う → ～ないことにする","a":"買わないことにする","hint":"어미 う는 あ가 아니라 わ로: 買わない."},{"t":"make","q":"飲む → ～ないことにした","a":"飲まないことにした","hint":"む→ま + ない, する의 과거 した."},{"t":"fill","q":"今年[ことし]から、たばこを吸[す]わないこと（　）しました。","a":"に","opts":["に","が","を","で"]}],"src":["https://bunpro.jp/grammar_points/ことにする"],"vf":1,"u":3,"g":1,"gp":"gg_N4_01"},{"id":"g4_052","t":"～ないことになる","ko":"~하지 않게 되다 (정해지다)","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"行く → 行かない + ことになる"},{"w":"2그룹 동사","f":"出る → 出ない + ことになる"},{"w":"する 동사","f":"参加する → 参加しない + ことになる"},{"w":"来る","f":"来る → 来ない(こない) + ことになる"}],"rule":["1. 동사를 ない형으로 바꾼다(行く→行かない: く→か).","2. ない형 뒤에 ことになる를 붙인다: 行かない + ことになる.","3. なる는 1그룹이라 과거는 る를 った로 바꿔 ことになった. 정해진 결과를 전할 때 주로 이 과거형을 쓴다.","4. 규칙이나 정해진 일은 ことになっている."],"why":"こと(것) + に + なる(~이 되다). '~하지 않는 것으로 되다'는 구조로, 내 의지가 아니라 다른 사람이나 상황에 의해 정해졌음을 나타낸다.","nu":"회의·회사·날씨 등 바깥 사정으로 결정된 일, 또는 자연스럽게 그렇게 된 결과에 쓴다. 자기 결정이라도 ことになりました로 말하면 겸손하고 부드럽게 들린다. ～ことになっている는 '~하지 않기로 되어 있다(규칙)'. 자기 의지를 분명히 할 때는 ～ないことにする.","cmp":[{"g":"～ないことにする","d":"말하는 사람이 스스로 '안 하기로' 정함."}],"ex":[{"jp":"雨[あめ]で、明日[あした]の試合[しあい]はしないことになった。","ko":"비 때문에 내일 시합은 하지 않게 됐다."},{"jp":"今年[ことし]の夏[なつ]は、家族[かぞく]で旅行[りょこう]に行[い]かないことになりました。","ko":"올여름에는 가족끼리 여행을 가지 않게 되었습니다."},{"jp":"この教室[きょうしつ]では、スマホを使[つか]わないことになっています。","ko":"이 교실에서는 스마트폰을 쓰지 않기로 되어 있습니다."}],"dr":[{"t":"make","q":"行く → ～ないことになった","a":"行かないことになった","hint":"く→か + ない, なる의 과거 なった."},{"t":"make","q":"参加する → ～ないことになった","a":"参加しないことになった","hint":"する의 ない형은 しない."},{"t":"fill","q":"会社[かいしゃ]の決[き]まりで、今年[ことし]は旅行[りょこう]をしないこと（　）なった。","a":"に","opts":["に","が","を","で"]}],"src":["https://bunpro.jp/grammar_points/ことになる","https://bunpro.jp/grammar_points/ことにする"],"vf":1,"u":3,"g":1,"gp":"gg_N4_01"},{"id":"g4_053","t":"～ないほうがいい","ko":"~하지 않는 편이 좋다","cat":"문말표현","conn":[{"w":"1그룹 동사(る로 끝나는 예외)","f":"走る → 走らない + ほうがいい"},{"w":"1그룹 동사","f":"飲む → 飲まない + ほうがいい"},{"w":"2그룹 동사","f":"食べる → 食べない + ほうがいい"},{"w":"する 동사","f":"無理する → 無理しない + ほうがいい"},{"w":"来る","f":"来る → 来ない(こない) + ほうがいい"}],"rule":["1. 동사를 ない형으로 바꾼다. 走る는 る로 끝나지만 1그룹이라 る를 ら로 바꾸고 ない(走らない). 2그룹이라면 る를 떼고 ない(食べない).","2. ない형 뒤에 ほうがいい(方がいい)를 붙인다: 走らない + ほうがいい.","3. 정중체는 ほうがいいです, 부드럽게는 ほうがいいと思います."],"why":"ほう(方, 쪽) + が + いい(좋다). 하는 쪽과 하지 않는 쪽을 비교해 '하지 않는 쪽'이 낫다는 구조라 충고의 뜻이 된다.","nu":"말하는 사람의 개인적 충고로, 하면 좋지 않은 결과가 있을 수 있음을 암시한다. 긍정 충고는 た형 + ほうがいい(行ったほうがいい)이지만 부정 충고는 ない형 그대로 쓴다(行かなかったほうがいい로 하지 않는다). 윗사람에게 직접 말하면 강하게 들릴 수 있어 と思います 등으로 완화한다.","cmp":[{"g":"～たほうがいい","d":"'~하는 편이 좋다'는 긍정 충고. 동사는 た형."},{"g":"～べきではない","d":"일반적 규범에 근거한 더 딱딱한 표현. ほうがいい는 개인적 조언."}],"ex":[{"jp":"床[ゆか]がぬれているから、走[はし]らないほうがいいよ。","ko":"바닥이 젖어 있으니까 뛰지 않는 게 좋아."},{"jp":"熱[ねつ]があるときは、無理[むり]をしないほうがいいです。","ko":"열이 있을 때는 무리하지 않는 편이 좋아요."},{"jp":"夜[よる]遅[おそ]くに甘[あま]いものは食[た]べないほうがいい。","ko":"밤늦게 단것은 먹지 않는 편이 좋다."}],"dr":[{"t":"make","q":"飲む → ～ないほうがいい","a":"飲まないほうがいい","hint":"む를 ま로 바꾸고 ない + ほうがいい."},{"t":"make","q":"走る → ～ないほうがいい","a":"走らないほうがいい","hint":"走る는 1그룹: る→ら + ない."},{"t":"fill","q":"風邪[かぜ]のときは、お風呂[ふろ]に入[はい]らない（　）いいですよ。","a":"ほうが","opts":["ほうが","ことが","ために","ながら"]}],"src":["https://bunpro.jp/grammar_points/ないほうがいい"],"vf":1,"u":3,"g":1,"gp":"gg_N4_02"},{"id":"g4_055","t":"～なさい","ko":"~해라, ~하렴 (지시·명령)","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"書く → 書き + なさい"},{"w":"2그룹 동사","f":"起きる → 起き + なさい"},{"w":"する","f":"勉強する → 勉強し + なさい"},{"w":"来る","f":"来る → 来[き] + なさい"}],"rule":["1. 동사를 ます형(ます를 뗀 연용형)으로 만든다. 2그룹은 끝의 る를 뗀다(起きる→起き).","2. 1그룹은 어미 う단을 い단으로 바꾼다(書く→書き, 読む→読み).","3. 불규칙 동사는 する→し, 来る→来(き)가 된다.","4. 그 뒤에 なさい를 붙인다(起きなさい, 書きなさい, 勉強しなさい)."],"why":"なさい는 する의 존경어 なさる의 명령형에서 왔다. 원래 높임말에서 나왔지만 지금은 명령문이라 아랫사람에게 쓰는 지시 표현이 되었다.","nu":"부모가 아이에게, 교사가 학생에게 쓰는 지시·명령. 명령형(起きろ)보다는 부드럽지만 윗사람에게는 절대 쓰지 않는다. 시험 지시문(正しいものを選びなさい)에도 쓰인다. 부정 명령은 なさい로 만들지 않고 ～ないで(ください)나 ～な를 쓴다. 인사말 おやすみなさい도 이 형태다. 한국어 '-하세요'처럼 정중하다고 오해하기 쉬우니 주의.","cmp":[{"g":"～てください","d":"정중한 부탁이라 누구에게나 쓸 수 있다. ～なさい는 위에서 아래로 내리는 지시."},{"g":"명령형(～ろ／～え단)","d":"起きろ, 書け처럼 더 거칠고 강한 명령. 주로 남성·긴급 상황."}],"ex":[{"jp":"もう七時[しちじ]よ。早[はや]く起[お]きなさい。","ko":"벌써 일곱 시야. 빨리 일어나렴."},{"jp":"ご飯[はん]の前[まえ]に手[て]を洗[あら]いなさい。","ko":"밥 먹기 전에 손 씻어라."},{"jp":"宿題[しゅくだい]が終[お]わったら、すぐ寝[ね]なさい。","ko":"숙제가 끝나면 바로 자거라."}],"dr":[{"t":"make","q":"書く → ～なさい","a":"書きなさい","hint":"く(う단) → き(い단) + なさい"},{"t":"make","q":"勉強する → ～なさい","a":"勉強しなさい","hint":"する → し + なさい"},{"t":"fill","q":"子[こ]どもたち、静[しず]かにし（　）。","a":"なさい","opts":["なさい","ください","たい","ながら"]}],"src":["https://bunpro.jp/grammar_points/95","https://tofugu.com/japanese-grammar/verb-imperative-form-nasai","https://en.wiktionary.org/wiki/%E3%81%AA%E3%81%95%E3%81%84"],"vf":1,"u":3,"g":1,"gp":"gg_N4_02"},{"id":"g4_058","t":"～ようと思う","ko":"~하려고 생각한다, ~할 생각이다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"行く → 行こう + と思う"},{"w":"2그룹 동사","f":"見る → 見よう + と思う"},{"w":"する","f":"する → しよう + と思う"},{"w":"来る","f":"来る → 来[こ]よう + と思う"}],"rule":["1. 동사를 의지형으로 만든다. 1그룹은 어미 う단을 お단으로 바꾸고 う를 붙인다(行く→行こう, 遊ぶ→遊ぼう).","2. 2그룹은 る를 떼고 よう를 붙인다(見る→見よう).","3. 불규칙: する→しよう, 来る→来(こ)よう.","4. 의지형 뒤에 と思う(と思います/と思っている)를 붙인다."],"why":"의지형(～う/～よう, '~하자/~해야지')에 인용의 と와 思う(생각하다)가 붙은 형태로, '~하자고 생각한다', 즉 말하는 사람의 마음속 의향을 나타낸다.","nu":"말하는 사람 자신의 계획·의향에 쓴다. ～ようと思います는 말하는 순간 마음먹은 느낌, ～ようと思っています는 전부터 계속 품어 온 생각. 제3자의 의향은 ～ようと思っている(彼は留学しようと思っている)로 쓴다. 의지로 할 수 없는 동사(分かる, 降る 등)에는 쓰지 않는다. 사전형+と思う(行くと思う)는 '갈 것 같다'는 추측이 되므로 혼동 주의.","cmp":[{"g":"～つもりだ","d":"이미 정해 둔 결심에 가깝다. ～ようと思う는 아직 마음속에 있는 생각 정도."},{"g":"～予定だ","d":"일정으로 정해져 남들도 아는 계획."}],"ex":[{"jp":"夏休[なつやす]みに日本[にほん]へ行[い]こうと思[おも]います。","ko":"여름 방학에 일본에 가려고 해요."},{"jp":"今日[きょう]は早[はや]く寝[ね]ようと思[おも]う。","ko":"오늘은 일찍 자려고 한다."},{"jp":"来年[らいねん]からピアノを習[なら]おうと思[おも]っています。","ko":"내년부터 피아노를 배우려고 생각하고 있어요."}],"dr":[{"t":"make","q":"買う → ～ようと思う","a":"買おうと思う","hint":"う → お단(お) + う + と思う"},{"t":"make","q":"食べる → ～ようと思う","a":"食べようと思う","hint":"2그룹: る를 떼고 よう + と思う"},{"t":"fill","q":"週末[しゅうまつ]は部屋[へや]を掃除[そうじ]し（　）と思[おも]っています。","a":"よう","opts":["よう","ない","たい","て"]}],"src":["https://bunpro.jp/grammar_points/122","https://langoal.com/jlpt/explain-grammar-youtoomotteimasu.html"],"vf":1,"u":3,"g":1,"gp":"gg_N4_02"},{"id":"g4_060","t":"～ようにする","ko":"~하도록 하다(노력하다), ~하려고 신경 쓰다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"寝る + ようにする"},{"w":"동사 ない형","f":"食べない + ようにする"},{"w":"する동사","f":"運動する + ようにする"}],"rule":["1. 동사를 사전형 또는 ない형으로 둔다(寝る / 食べない).","2. 그 뒤에 ように를 붙인다.","3. 마지막에 する를 붙인다. 습관으로 계속하고 있으면 する를 て형 して로 바꾸고 いる를 붙여 ようにしている.","4. 부탁할 때는 ようにしてください가 된다."],"why":"よう(상태)+に+する(하다)로 '그런 상태가 되도록 만든다', 즉 어떤 행동을 목표로 삼아 의식적으로 노력한다는 뜻이 된다.","nu":"한 번의 행동이 아니라 의식적으로 계속 신경 쓰는 노력·습관에 쓴다. ～ようにしている는 꾸준히 지키는 습관. ～ようにしてください는 부드러운 지시·조언. 가능형에는 잘 쓰지 않는다. ～ようになる(자연스러운 변화)와 혼동하기 쉽다.","cmp":[{"g":"～ようになる","d":"의지와 상관없이 결과적으로 변한 것(できるようになった). ～ようにする는 스스로 노력하는 것."},{"g":"～ことにする","d":"한 번 결정하는 것. ～ようにする는 결정 후에도 계속 신경 써서 노력하는 것."}],"ex":[{"jp":"毎晩[まいばん]十一時[じゅういちじ]までに寝[ね]るようにしています。","ko":"매일 밤 11시까지는 자려고 하고 있어요."},{"jp":"甘[あま]いものはあまり食[た]べないようにしている。","ko":"단 것은 되도록 안 먹으려고 한다."},{"jp":"授業[じゅぎょう]に遅[おく]れないようにしてください。","ko":"수업에 늦지 않도록 해 주세요."}],"dr":[{"t":"make","q":"野菜を食べる → (습관) ～ようにしている","a":"野菜を食べるようにしている","hint":"사전형 + ように + して(する의 て형) + いる"},{"t":"make","q":"忘れる → (부정, 부탁) ～ようにしてください","a":"忘れないようにしてください","hint":"る → ない + ようにしてください"},{"t":"fill","q":"健康[けんこう]のために、毎日[まいにち]歩[ある]く（　）しています。","a":"ように","opts":["ように","ために","ことに","そうに"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201310.html","https://guidetojapanese.org/learn/grammar/surunaru"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_061","t":"～ようになる","ko":"~하게 되다, ~할 수 있게 되다 (변화)","cat":"문말표현","conn":[{"w":"동사 가능형","f":"話せる + ようになる"},{"w":"동사 사전형","f":"寝る + ようになる"},{"w":"동사 ない형","f":"食べない + ようになる"}],"rule":["1. 능력의 변화는 동사를 가능형으로 바꾼다. 1그룹은 어미 う단을 え단으로 바꾸고 る를 붙인다(話す→話せる).","2. 2그룹은 る를 떼고 られる를 붙인다(見る→見られる). する→できる, 来る→来(こ)られる.","3. 습관·상태의 변화는 사전형 그대로 둔다(早く寝る).","4. 그 뒤에 ようになる를 붙이고, 변화가 일어났으면 なる를 なった로 바꾼다(話せるようになった)."],"why":"よう(상태)+に+なる(되다)로 '그런 상태에 이르다'라는 뜻이다. 과정을 거쳐 능력이나 습관이 생긴 변화를 나타낸다.","nu":"능력의 변화(できるようになった), 습관의 변화(毎朝走るようになった)에 쓰며 보통 과거형 なった로 말한다. 의지로 노력하는 것은 ～ようにする. 부정 변화는 ～なくなる가 자연스럽다(×話せないようになった보다 話せなくなった). 명사·형용사의 변화에는 쓰지 않고 になる/くなる를 쓴다(先生になる, 寒くなる). 한국어 '하게 되다'를 ～ことになる와 섞어 쓰는 실수 주의.","cmp":[{"g":"～ようにする","d":"스스로 노력해서 그렇게 하는 것. ～ようになる는 결과로 생긴 변화."},{"g":"～ことになる","d":"남이나 상황에 의해 결정되는 것(転勤することになった). 능력·습관의 변화가 아니다."}],"ex":[{"jp":"一年[いちねん]勉強[べんきょう]して、日本語[にほんご]が話[はな]せるようになりました。","ko":"1년 공부해서 일본어를 말할 수 있게 되었어요."},{"jp":"子[こ]どもが生[う]まれてから、早[はや]く寝[ね]るようになった。","ko":"아이가 태어나고 나서 일찍 자게 되었다."},{"jp":"最近[さいきん]、やっと納豆[なっとう]が食[た]べられるようになった。","ko":"요즘 드디어 낫토를 먹을 수 있게 되었다."}],"dr":[{"t":"make","q":"泳ぐ → (가능형) ～ようになった","a":"泳げるようになった","hint":"ぐ → げ (え단) + る + ようになった"},{"t":"make","q":"見る → (가능형) ～ようになった","a":"見られるようになった","hint":"2그룹: る → られる + ようになった"},{"t":"fill","q":"練習[れんしゅう]して、ピアノが弾[ひ]ける（　）なりました。","a":"ように","opts":["ように","ために","ことに","そうに"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201310.html","https://guidetojapanese.org/learn/grammar/surunaru"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_062","t":"～ように言う","ko":"~하라고 말하다 (간접 지시·전달)","cat":"문말표현","conn":[{"w":"동사 사전형","f":"片付ける + ように言う"},{"w":"동사 ない형","f":"遅れない + ように言う"},{"w":"する동사","f":"提出する + ように言う"}],"rule":["1. 하라고 한 행동을 사전형으로 둔다(片付ける). 하지 말라고 했으면 ない형으로 바꾼다(遅れる→遅れない).","2. 그 뒤에 ように를 붙인다.","3. 마지막에 言う를 붙이고, 과거면 言う→言った(言いました)로 바꾼다.","4. 지시를 받는 사람은 に로 나타낸다(弟に～ように言った). 내가 들은 경우는 수동 言われた."],"why":"よう+に가 '그렇게 되도록'이라는 내용을 나타내고, 言う가 그것을 말로 전한다. 직접 명령(片付けなさい)을 간접적으로 바꿔 전하는 방식이다.","nu":"명령·부탁·조언을 남에게 전달할 때 쓴다. 言う 대신 頼む, 注意する, 伝える도 쓸 수 있다. 직접 인용 「片付けなさい」と言った보다 부드럽고 설명적. 한국어 '~하라고'를 그대로 옮겨 ×片付けろと言った만 쓰면 거칠게 들릴 수 있다. 정중형 ます는 ように 앞에 넣지 않는다(×片付けますように言った).","cmp":[{"g":"「～てください」と言う","d":"부탁을 직접 인용한 형태. ～ように言う는 내용만 간접적으로 전한다."},{"g":"～ようにする","d":"자기 자신이 노력하는 것. ～ように言う는 남에게 하라고 지시하는 것."}],"ex":[{"jp":"母[はは]は弟[おとうと]に部屋[へや]を片付[かたづ]けるように言[い]った。","ko":"엄마는 남동생에게 방을 치우라고 말했다."},{"jp":"先生[せんせい]に明日[あした]は遅[おく]れないように言[い]われました。","ko":"선생님께 내일은 늦지 말라는 말을 들었어요."},{"jp":"田中[たなか]さんに会議室[かいぎしつ]に来[く]るように伝[つた]えてください。","ko":"다나카 씨에게 회의실로 오라고 전해 주세요."}],"dr":[{"t":"make","q":"「早く寝なさい」と言った → ～ように言った","a":"早く寝るように言った","hint":"寝なさい를 사전형 寝る로 + ように言った"},{"t":"make","q":"「お酒を飲まないで」と言った → ～ように言った","a":"お酒を飲まないように言った","hint":"하지 말라 → ない형 飲まない + ように言った"},{"t":"fill","q":"医者[いしゃ]に、たばこをやめる（　）言[い]われた。","a":"ように","opts":["ように","ために","のに","ながら"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201310.html"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_066","t":"～ことにする","ko":"~하기로 하다 (결정)","cat":"문말표현","conn":[{"w":"동사 사전형","f":"行く + ことにする"},{"w":"동사 ない형","f":"食べない + ことにする"},{"w":"する동사","f":"散歩する + ことにする"}],"rule":["1. 정한 행동을 사전형으로 둔다(行く). 하지 않기로 했으면 ない형(食べない).","2. 그 뒤에 こと와 조사 に를 붙인다.","3. 마지막에 する를 붙인다. 이미 정했으면 する→した(ことにした).","4. 정해 두고 계속 지키는 습관은 する→して+いる(ことにしている)."],"why":"こと(일)+に+する(하다)로 '그 일로 정하다'라는 뜻이다. 동사구를 こと로 명사화하고, ～にする(~으로 하다, 고르다)를 붙인 구조다.","nu":"말하는 사람이 스스로 내린 결정. 보통 과거형 ことにした로 말한다. 남이나 조직이 정한 일은 ～ことになる(会社で転勤することになった). ことにしている는 자신의 규칙·습관. 한국어 '~하기로 했다'를 ことになった와 구별 없이 쓰는 실수가 많다.","cmp":[{"g":"～ことになる","d":"자신의 의지와 상관없이 정해진 일. ～ことにする는 스스로 결정."},{"g":"～ようにする","d":"계속 신경 쓰는 노력. ～ことにする는 한 번의 결정."}],"ex":[{"jp":"来週[らいしゅう]からジムに行[い]くことにしました。","ko":"다음 주부터 헬스장에 가기로 했어요."},{"jp":"今日[きょう]から甘[あま]いものを食[た]べないことにする。","ko":"오늘부터 단 것을 먹지 않기로 하겠다."},{"jp":"毎朝[まいあさ]、駅[えき]まで歩[ある]くことにしています。","ko":"매일 아침 역까지 걷기로 하고 있어요."}],"dr":[{"t":"make","q":"この靴を買う → ～ことにした","a":"この靴を買うことにした","hint":"사전형 + こと + に + した(する의 과거)"},{"t":"make","q":"お酒を飲む → (부정) ～ことにした","a":"お酒を飲まないことにした","hint":"む → ま (あ단) + ない + ことにした"},{"t":"fill","q":"いろいろ考[かんが]えて、留学[りゅうがく]する（　）しました。","a":"ことに","opts":["ことに","ように","ために","そうに"]}],"src":["https://guidetojapanese.org/learn/grammar/surunaru"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_067","t":"～ことになる","ko":"~하게 되다 (결정·결과)","cat":"문말표현","conn":[{"w":"동사 사전형","f":"行く + ことになる"},{"w":"동사 ない형","f":"行かない + ことになる"},{"w":"する동사","f":"転勤する + ことになる"}],"rule":["1. 동사는 사전형(또는 ない형) 그대로 둔다: 行く.","2. 뒤에 こと(일·것)를 붙여 동사를 명사처럼 만든다: 行くこと.","3. 조사 に와 なる(되다)를 붙인다: 行くことになる.","4. 이미 정해졌으면 なる를 과거형 なった로 바꾼다: 行くことになった. 정중체는 なりました."],"why":"こと(일·사건)+に+なる(되다)로 '그런 일이 되다', 즉 내 뜻과 별개로 그렇게 정해졌다는 뜻이 된다. 스스로 정할 때는 なる 대신 する를 쓴 ～ことにする가 된다.","nu":"결정한 주체가 회사·남·상황일 때 쓴다(말하는 사람이 정했어도 겸손하게 돌려 말할 때 쓰기도 함). 정해진 사실은 보통 과거형 ことになった로 말하고, 규칙·예정으로 정해져 있는 것은 ～ことになっている. 한국어 '~하게 되다'를 모두 ことになる로 옮기면 틀린다: 능력·습관의 변화는 ～ようになる.","cmp":[{"g":"～ことにする","d":"말하는 사람이 스스로 결정. ～ことになる는 남·상황이 결정."},{"g":"～ようになる","d":"능력·습관이 변한 결과(話せるようになった). 결정의 뜻은 없다."}],"ex":[{"jp":"来月[らいげつ]から大阪[おおさか]の支店[してん]で働[はたら]くことになりました。","ko":"다음 달부터 오사카 지점에서 일하게 되었습니다."},{"jp":"雨[あめ]で、明日[あした]の試合[しあい]はしないことになった。","ko":"비 때문에 내일 시합은 하지 않게 되었다."},{"jp":"この部屋[へや]では、靴[くつ]を脱[ぬ]ぐことになっています。","ko":"이 방에서는 신발을 벗게 되어 있습니다."}],"dr":[{"t":"make","q":"結婚する → ～ことになった","a":"結婚することになった","hint":"사전형 그대로 + ことに + なった"},{"t":"make","q":"行かない → ～ことになりました","a":"行かないことになりました","hint":"ない형 그대로 + ことに + なりました"},{"t":"fill","q":"会社[かいしゃ]の命令[めいれい]で、東京[とうきょう]に引[ひ]っ越[こ]す（　）なった。","a":"ことに","opts":["ことに","ように","ために","そうに"]}],"src":["https://bunpro.jp/grammar_points/ことになる","https://guidetojapanese.org/learn/grammar/surunaru"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_074","t":"～かしら","ko":"~려나, ~일까 (혼잣말, 주로 여성)","cat":"문말표현","conn":[{"w":"동사 보통형","f":"降る + かしら"},{"w":"い형용사","f":"おいしい + かしら"},{"w":"な형용사","f":"静か + かしら (だ 없음)"},{"w":"명사","f":"病気 + かしら (だ 없음)"}],"rule":["1. 문장을 보통형으로 끝낸다: 雨が降る.","2. 끝에 かしら를 붙인다: 雨が降るかしら.","3. 명사·な형용사는 だ를 붙이지 않고 바로 かしら를 붙인다: 病気かしら, 静かかしら.","4. 과거·부정도 보통형 그대로 붙인다: 来ないかしら, 行ったかしら."],"why":"'か知らぬ / かしらん(~인지 모르겠다)'이 줄어든 말이라 '~인지 모르겠네', 즉 '~려나'라는 혼잣말의 뜻이 된다.","nu":"회화체. 현대어에서는 주로 여성이 쓰는 부드러운 말투이고, 남성은 보통 かな를 쓴다. 혼잣말이나 친한 사이에서 쓰며 윗사람에게 직접 묻는 말로는 でしょうか가 맞다. ～ないかしら는 '~해 주지 않으려나'라는 완곡한 바람도 된다.","cmp":[{"g":"～かな(あ)","d":"뜻은 같지만 남녀 모두 쓰는 일반적인 말투. かしら는 더 여성적이고 부드럽다."}],"ex":[{"jp":"明日[あした]は雨[あめ]が降[ふ]るかしら。","ko":"내일은 비가 오려나."},{"jp":"このケーキ、おいしいかしら。","ko":"이 케이크 맛있으려나."},{"jp":"あの人[ひと]、田中[たなか]さんかしら。","ko":"저 사람, 다나카 씨일까."}],"dr":[{"t":"make","q":"彼は来る → ～かしら","a":"彼は来るかしら","hint":"보통형 그대로 + かしら"},{"t":"make","q":"本当だ → ～かしら","a":"本当かしら","hint":"명사·な형용사는 だ를 빼고 + かしら"},{"t":"fill","q":"あの店[みせ]、今日[きょう]は開[あ]いている（　）。","a":"かしら","opts":["かしら","から","ので","のに"]}],"src":["https://bunpro.jp/grammar_points/かしら"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_076","t":"～かなあ","ko":"~려나, ~할까 (혼잣말)","cat":"문말표현","conn":[{"w":"동사 보통형","f":"晴れる + かなあ"},{"w":"い형용사","f":"おいしい + かなあ"},{"w":"な형용사","f":"元気 + かなあ (だ 없음)"},{"w":"명사","f":"病気 + かなあ (だ 없음)"}],"rule":["1. 문장을 보통형으로 끝낸다: 明日晴れる.","2. 끝에 かなあ(짧게 かな)를 붙인다: 明日晴れるかなあ.","3. 명사·な형용사는 だ를 붙이지 않고 바로 붙인다: 病気かなあ, 元気かなあ.","4. 부정형에 붙인 ～ないかなあ는 '~하면 좋겠는데'라는 바람이 된다: 早く来ないかなあ."],"why":"질문의 か와 자기 생각을 나타내는 な가 합쳐진 かな를 길게 늘인 형태로, 남에게 묻기보다 자기 자신에게 묻는 느낌을 준다.","nu":"회화체. 남녀 모두 쓰며 혼잣말이나 친한 사이에서 쓴다. あ를 늘이면 감정(기대·걱정)이 더 담긴다. 윗사람에게 묻는 말로는 でしょうか가 알맞다. 직접 질문이 아니므로 상대가 꼭 답할 필요는 없다.","cmp":[{"g":"～かしら","d":"뜻은 같지만 주로 여성이 쓰는 더 부드러운 말투."},{"g":"～でしょうか","d":"정중하게 상대에게 묻거나 추측할 때."}],"ex":[{"jp":"明日[あした]、晴[は]れるかなあ。","ko":"내일 날씨가 개려나."},{"jp":"このラーメン、おいしいかなあ。","ko":"이 라멘 맛있으려나."},{"jp":"おばあちゃん、元気[げんき]かなあ。","ko":"할머니는 잘 지내시려나."}],"dr":[{"t":"make","q":"バスが来る → ～かなあ","a":"バスが来るかなあ","hint":"보통형 그대로 + かなあ"},{"t":"make","q":"病気だ → ～かなあ","a":"病気かなあ","hint":"명사는 だ를 빼고 + かなあ"},{"t":"fill","q":"彼[かれ]、まだ怒[おこ]っている（　）。","a":"かなあ","opts":["かなあ","ので","のに","ために"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%8B%E3%81%AA"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_087","t":"～たらいい","ko":"~하면 좋겠다, ~하면 된다","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"行く → 行ったら + いい"},{"w":"2그룹 동사","f":"晴れる → 晴れたら + いい"},{"w":"する","f":"する → したら + いい"},{"w":"来る","f":"来る → 来(き)たら + いい"}],"rule":["1. 동사를 た형으로 바꾼다(晴れる→晴れた, 飲む→飲んだ, 行く→行った).","2. た형 끝에 ら를 붙여 たら(だら)를 만든다(晴れたら, 飲んだら).","3. 뒤에 いい를 붙인다(晴れたらいい). 바람은 いいな·いいですね, 질문은 いいですか로 끝맺는다."],"why":"조건 ～たら(~하면) + いい(좋다)로 '~하면 좋다'가 되어, 조언이나 바람을 나타낸다.","nu":"① 조언: 행동 방법을 권할 때(駅員に聞いたらいいよ). 의문사와 함께 どうしたらいいですか(어떻게 하면 되나요)는 매우 자주 쓴다. ② 바람: 자기 힘으로 안 되는 일을 바랄 때 いいな·いいのに를 붙인다(晴れたらいいな). ～ばいい와 거의 같은 뜻이며 ～たらいい가 더 회화적이다. 윗사람에게 직접 조언할 때 ～たらいいですよ는 가르치는 투가 될 수 있다.","cmp":[{"g":"～ばいい","d":"뜻은 거의 같고, ～ばいい는 '그것만 하면 된다'는 최소 조건의 느낌이 조금 더 있다."},{"g":"～たらどうですか","d":"상대에게 행동을 제안하는 표현으로 바람의 뜻은 없다."}],"ex":[{"jp":"明日[あした]、晴[は]れたらいいな。","ko":"내일 맑으면 좋겠다."},{"jp":"わからない時[とき]は、先生[せんせい]に聞[き]いたらいいですよ。","ko":"모를 때는 선생님께 물어보면 돼요."},{"jp":"駅[えき]までどう行[い]ったらいいですか。","ko":"역까지 어떻게 가면 되나요?"}],"dr":[{"t":"make","q":"休む → ～たらいい","a":"休んだらいい","hint":"む는 んだ로 바뀌고(음편) ら + いい를 붙인다."},{"t":"make","q":"早く治る → ～たらいい","a":"早く治ったらいい","hint":"る(1그룹)는 った로 바뀌고 ら + いい."},{"t":"fill","q":"明日[あした]の試合[しあい]、勝[か]っ（　）いいね。","a":"たら","opts":["たら","たり","ては","てから"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%89%E3%81%84%E3%81%84-%E3%81%A8%E3%81%84%E3%81%84","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201512.html"],"vf":1,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_088","t":"～たらいかがですか","ko":"~하시는 게 어떠세요?","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"休む → 休んだら + いかがですか"},{"w":"2그룹 동사","f":"食べる → 食べたら + いかがですか"},{"w":"する","f":"する → したら + いかがですか"},{"w":"来る","f":"来る → 来(き)たら + いかがですか"}],"rule":["1. 동사를 た형으로 바꾼다. 1그룹은 음편이 일어난다(休む→休んだ, 行く→行った).","2. た형 끝에 ら를 붙인다(休んだら).","3. 뒤에 いかがですか를 붙인다(休んだらいかがですか)."],"why":"～たら(~하면) + いかが(どう의 정중한 말) + ですか로, ～たらどうですか를 공손하게 한 형태다.","nu":"상대에게 어떤 행동을 정중하게 권한다. 손님·고객 응대나 처음 만난 사람에게 알맞다. 다만 상대의 행동에 대한 조언이므로, 윗사람에게는 말투가 정중해도 가르치는 듯 들릴 수 있다. 친한 사이에서는 ～たら(どう)? 정도로 짧게 말한다. 형용사·명사가 아닌 동사에 주로 쓴다.","cmp":[{"g":"～たらどうですか","d":"뜻은 같지만 덜 정중하다. 친구에게는 ～たらどう?"},{"g":"～ませんか","d":"함께 하자는 권유나 상대의 의향을 묻는 표현. ～たらいかがですか는 상대만 하는 행동을 조언한다."}],"ex":[{"jp":"お疲[つか]れのようですね。少[すこ]し休[やす]んだらいかがですか。","ko":"피곤하신 것 같네요. 조금 쉬시는 게 어떠세요?"},{"jp":"一度[いちど]、医者[いしゃ]に相談[そうだん]したらいかがですか。","ko":"한번 의사와 상담해 보시는 게 어떠세요?"},{"jp":"寒[さむ]いなら、このコートを着[き]たらいかがですか。","ko":"추우시면 이 코트를 입으시는 게 어떠세요?"}],"dr":[{"t":"make","q":"待つ → ～たらいかがですか","a":"待ったらいかがですか","hint":"つ는 った로 바뀌고 ら + いかがですか."},{"t":"make","q":"電話する → ～たらいかがですか","a":"電話したらいかがですか","hint":"する는 した, 그 뒤에 ら + いかがですか."},{"t":"fill","q":"タクシーで行[い]っ（　）いかがですか。","a":"たら","opts":["たら","ても","たり","てから"]}],"src":[],"vf":0,"u":4,"g":1,"gp":"gg_N4_02"},{"id":"g4_089","t":"～たらどうですか","ko":"~하는 게 어때요?","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"行く → 行ったら + どうですか"},{"w":"2그룹 동사","f":"寝る → 寝たら + どうですか"},{"w":"する","f":"する → したら + どうですか"},{"w":"来る","f":"来る → 来(き)たら + どうですか"}],"rule":["1. 동사를 た형으로 바꾼다. 行く는 예외로 く가 っ가 되어 行った가 된다(書く→書いた와 다름).","2. た형 끝에 ら를 붙인다(行ったら).","3. 뒤에 どうですか를 붙인다(行ったらどうですか)."],"why":"～たら(~하면) + どう(어떻게) + ですか로 '~하면 어떻습니까'가 되어 상대에게 행동을 제안한다.","nu":"상대에게 어떤 행동을 권하거나 조언한다. 친구 사이에서는 ～たらどう?, 더 줄여 ～たら?(行ったら?)로도 말한다. 말투에 따라 '좀 ~하지 그래'처럼 다그치는 느낌이 날 수 있어 윗사람에게는 피하고, 정중하게는 ～たらいかがですか를 쓴다. 자신도 함께 하자는 뜻은 없다.","cmp":[{"g":"～たらいかがですか","d":"같은 뜻의 더 정중한 표현."},{"g":"～ほうがいい","d":"～たほうがいい는 '~하는 편이 좋다'로 더 강하고 단정적인 충고."}],"ex":[{"jp":"熱[ねつ]があるなら、病院[びょういん]に行[い]ったらどうですか。","ko":"열이 있으면 병원에 가 보는 게 어때요?"},{"jp":"疲[つか]れているなら、早[はや]く寝[ね]たらどう？","ko":"피곤하면 일찍 자는 게 어때?"},{"jp":"わからないなら、先生[せんせい]に聞[き]いたらどうですか。","ko":"모르겠으면 선생님께 물어보는 게 어때요?"}],"dr":[{"t":"make","q":"行く → ～たらどうですか","a":"行ったらどうですか","hint":"行く는 예외로 行った, 그 뒤에 ら + どうですか."},{"t":"make","q":"薬を飲む → ～たらどうですか","a":"薬を飲んだらどうですか","hint":"む는 んだ로 바뀌고 ら + どうですか."},{"t":"fill","q":"そんなに眠[ねむ]いなら、少[すこ]し寝[ね]（　）どうですか。","a":"たら","opts":["たら","ても","ながら","たり"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%89%E3%81%A9%E3%81%86","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei15_1.pdf"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_098","t":"～といい","ko":"~하면 좋겠다","cat":"문말표현","conn":[{"w":"동사 사전형·ない형","f":"晴れる / 降らない + といい"},{"w":"い형용사","f":"暖かい + といい"},{"w":"な형용사","f":"元気だ + といい"},{"w":"명사","f":"晴れだ + といい"}],"rule":["1. 동사·い형용사는 보통형(현재) 그대로 뒤에 と를 붙인다(晴れる+と).","2. な형용사·명사는 だ를 붙인 뒤 と(元気だ+と).","3. と 뒤에 いい를 붙이고, 혼잣말이면 な, 상대에게 말하면 ね를 더한다(晴れるといいな, 晴れるといいね)."],"why":"조건의 と(~하면) + いい(좋다)로 '~하면 좋다', 곧 바람을 나타낸다.","nu":"말하는 사람이 어쩔 수 없는 일에 대한 바람에 쓴다(날씨, 시험 결과, 남의 건강). といいですね는 상대를 위한 바람(합격하면 좋겠네요). 자기 의지로 할 수 있는 일에는 잘 안 쓴다. 상대에게 권할 때 쓰는 '~하면 좋아요(조언)' 용법도 있다(薬を飲むといいですよ). 과거형에는 붙이지 않는다.","cmp":[{"g":"～たらいい","d":"거의 같은 바람. 회화에서 たらいいな도 많이 쓴다. 조언으로는 '어떻게 하면 좋을까' 질문(どうしたらいい)에 たら를 쓴다."},{"g":"～ばいい","d":"바람에도 쓰지만 '~하면 된다'는 해결책 제시 뜻이 강하다."}],"ex":[{"jp":"明日[あした]、晴[は]れるといいね。","ko":"내일 맑으면 좋겠네."},{"jp":"テストがやさしいといいな。","ko":"시험이 쉬우면 좋겠다."},{"jp":"おばあちゃんが元気[げんき]だといいんだけど。","ko":"할머니가 건강하시면 좋겠는데."}],"dr":[{"t":"make","q":"合格する → ～といい","a":"合格するといい","hint":"동사 사전형 뒤에 と + いい."},{"t":"make","q":"静かだ → ～といい","a":"静かだといい","hint":"な형용사는 だ를 붙인 뒤 と + いい."},{"t":"fill","q":"明日[あした]の旅行[りょこう]、雨[あめ]が降[ふ]らない（　）ね。","a":"といい","opts":["といい","ために","ように","ばかり"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%84","https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%89%E3%81%84%E3%81%84-%E3%81%A8%E3%81%84%E3%81%84"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_101","t":"～と思う","ko":"~라고 생각하다","cat":"문말표현","conn":[{"w":"동사 보통형","f":"降る / 降らない + と思う"},{"w":"い형용사","f":"おもしろい + と思う"},{"w":"な형용사(だ 필요)","f":"親切だ + と思う"},{"w":"명사(だ 필요)","f":"学生だ + と思う"}],"rule":["1. 동사·い형용사는 보통형 그대로 뒤에 と思う를 붙인다(降る+と思う, おもしろい+と思う).","2. な형용사·명사는 だ를 붙인 뒤 と思う(親切→親切だ+と思う). 편한 회화에서는 だ가 빠지기도 하지만 기본은 だ를 넣는다.","3. と는 인용 조사이고, 정중하게는 と思います."],"why":"인용 조사 と(~라고) + 思う(생각하다)로, 생각한 내용을 と로 묶어 나타낸다.","nu":"자기 의견·추측을 부드럽게 말한다. 주어가 3인칭이면 と思っている를 쓴다(彼は…と思っている). 한국어 화자는 명사·な형용사에 だ를 빠뜨리는(親切と思う: 반말 회화에서만 들림) 실수, 또는 정중형을 넣는(×いいですと思います) 실수를 조심. 의지형+と思う(行こうと思う)는 '~하려고 한다'.","cmp":[{"g":"～でしょう / ～だろう","d":"예측·추측. と思う는 말하는 사람의 개인적 의견임을 드러낸다."},{"g":"～と考える","d":"논리적으로 따진 생각. 문어·격식에서 쓴다."}],"ex":[{"jp":"明日[あした]は晴[は]れると思います。","ko":"내일은 맑을 거라고 생각합니다."},{"jp":"この本[ほん]はおもしろいと思う。","ko":"이 책은 재미있다고 생각해."},{"jp":"田中[たなか]さんはとても親切[しんせつ]だと思います。","ko":"다나카 씨는 아주 친절하다고 생각합니다."}],"dr":[{"t":"make","q":"便利 → ～と思う","a":"便利だと思う","hint":"な형용사는 だ를 붙인 뒤 と思う."},{"t":"make","q":"来ない → ～と思う","a":"来ないと思う","hint":"보통형 부정 그대로 と思う."},{"t":"fill","q":"あの人[ひと]は先生[せんせい]だ（　）。","a":"と思います","opts":["と思います","でしょうか","にします","ことがあります"]}],"src":["https://bunpro.jp/grammar_points/94"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_111","t":"～のです（んです）","ko":"~인 것입니다, ~거든요 (사정 설명)","cat":"문말표현","conn":[{"w":"동사 보통형","f":"行く + のです / 行った + んです"},{"w":"い형용사","f":"痛い + のです"},{"w":"な형용사","f":"静か + な + のです"},{"w":"명사","f":"先生 + な + のです"}],"rule":["1. 동사·い형용사는 보통형에 그대로 のです를 붙인다(痛い→痛いのです).","2. 명사·な형용사의 현재 긍정은 だ를 な로 바꾼다(先生だ→先生なのです).","3. 회화에서는 の가 ん으로 줄어 んです가 된다(痛いんです).","4. 반말에서는 のだ/んだ, 의문은 のですか/んですか."],"why":"","nu":"회화에서는 거의 んです로 말한다. 사정을 설명할 때(頭が痛いんです), 상대의 상황을 묻거나 확인할 때(どうしたんですか)에 쓴다. 너무 자주 쓰면 변명·강조처럼 들리고, 단순한 사실 전달(私は学生です)에 붙이면 어색하다. 명사에 ×先生のです로 붙이지 않도록 주의.","cmp":[{"g":"～です（단순 진술）","d":"사실만 전달한다. のです는 '실은 ~라서'라는 배경 설명이 더해진다."},{"g":"～ので","d":"문장을 이어 이유를 말하는 접속 표현. のです는 문장 끝에서 사정을 설명한다."}],"ex":[{"jp":"すみません、頭[あたま]が痛[いた]いんです。","ko":"죄송해요, 머리가 아파서요."},{"jp":"どうしたんですか。","ko":"무슨 일 있어요?"},{"jp":"明日[あした]は休[やす]みなんです。","ko":"내일은 쉬는 날이거든요."}],"dr":[{"t":"make","q":"眠い → ～んです","a":"眠いんです","hint":"い형용사는 그대로 んです."},{"t":"make","q":"暇だ → ～んです","a":"暇なんです","hint":"な형용사는 だ를 な로 바꾸고 んです."},{"t":"fill","q":"A「顔色[かおいろ]が悪[わる]いですね。」B「ちょっと熱[ねつ]がある（　）。」","a":"んです","opts":["んです","ので","のに","ばいい"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201006.html","https://bunpro.jp/ja/grammar_points/-%E3%82%93%E3%81%A7%E3%81%99-%E3%81%AE%E3%81%A7%E3%81%99"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_120","t":"～んです","ko":"~거든요, ~인 거예요 (사정 설명)","cat":"문말표현","conn":[{"w":"동사 보통형","f":"行く + んです / 行った + んです"},{"w":"い형용사","f":"痛い + んです"},{"w":"な형용사","f":"好きな + んです"},{"w":"명사","f":"学生な + んです"}],"rule":["1. 동사·い형용사는 보통형 뒤에 んです를 붙인다(痛いです → 痛いんです).","2. な형용사·명사는 현재 긍정일 때 だ를 な로 바꾸어 붙인다(好きだ → 好きなんです, 学生だ → 学生なんです).","3. 과거·부정은 보통형 그대로 붙인다(雨だった → 雨だったんです).","4. 회화에서 쓰는 형태이며 문장체에서는 のです가 된다."],"why":"","nu":"사정·이유를 설명하거나(頭が痛いんです), 상대에게 사정을 묻거나(どうしたんですか), 자기 사정을 말하며 부탁을 꺼낼 때(～んですが) 쓴다. 단순 사실 전달에 매번 쓰면 강요하는 느낌을 줄 수 있으므로 설명이 필요한 장면에서만 쓴다. ×学生だんです처럼 だ를 남기는 실수에 주의.","cmp":[{"g":"～から","d":"이유를 문법적으로 연결(痛いから休みます). んです는 듣는 사람에게 사정을 설명하는 말투."}],"ex":[{"jp":"すみません、頭[あたま]が痛[いた]いんです。","ko":"죄송해요, 머리가 아프거든요."},{"jp":"どうしたんですか。","ko":"무슨 일 있어요?"},{"jp":"明日[あした]はテストなんです。","ko":"내일은 시험이거든요."}],"dr":[{"t":"make","q":"お腹が痛い → ～んです","a":"お腹が痛いんです","hint":"い형용사 기본형 뒤에 んです를 붙인다."},{"t":"make","q":"好きだ → ～んです","a":"好きなんです","hint":"な형용사는 だ를 な로 바꾸고 んです."},{"t":"fill","q":"A：どうして遅[おく]れたんですか。B：電車[でんしゃ]が止[と]まった（　）。","a":"んです","opts":["んです","までに","ながら","しか"]}],"src":["https://bunpro.jp/grammar_points/17"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_064","t":"～ことがある","ko":"~할 때가 있다, 가끔 ~한다","cat":"명사화·수식","conn":[{"w":"동사 사전형","f":"寝坊する + ことがある"},{"w":"동사 ない형","f":"食べない + ことがある"},{"w":"い형용사","f":"寒い + ことがある"},{"w":"な형용사·명사","f":"暇な + ことがある / 雨の + ことがある"}],"rule":["1. 동사를 사전형(또는 ない형)으로 둔다. 과거형으로 바꾸지 않는다(寝坊する).","2. 그 뒤에 명사 こと(일)를 붙인다.","3. 조사 が와 ある를 붙인다(寝坊することがある). 정중하게는 ことがあります.","4. 'ない'로 끝나면 '~하는 일은 없다'가 되며, 보통 は를 써서 ことはない로 말한다."],"why":"こと(일, 사건)+が+ある(있다)로, 그런 일이 일어나는 경우가 있다는 뜻이다. 동사가 과거형이면 경험(～たことがある)이 되고, 사전형이면 가끔 일어나는 일이 된다.","nu":"'항상은 아니지만 때때로'라는 빈도 표현. ときどき, たまに와 잘 어울린다. 과거형+ことがある(行ったことがある)는 '~한 적이 있다'는 경험이라 의미가 전혀 다르다. 한국어 '~한 적이 있다'와 '~할 때가 있다'를 시제로 구별해야 한다.","cmp":[{"g":"～たことがある","d":"과거형에 붙어 '~한 적이 있다'(경험). 사전형+ことがある는 '가끔 ~한다'."},{"g":"～ことができる","d":"'~할 수 있다'(능력·가능). 빈도를 나타내지 않는다."}],"ex":[{"jp":"朝[あさ]、たまに寝坊[ねぼう]することがあります。","ko":"아침에 가끔 늦잠 잘 때가 있어요."},{"jp":"忙[いそが]しいときは、昼[ひる]ご飯[はん]を食[た]べないことがある。","ko":"바쁠 때는 점심을 안 먹을 때가 있다."},{"jp":"この道[みち]は夜[よる]になると、とても静[しず]かなことがある。","ko":"이 길은 밤이 되면 아주 조용할 때가 있다."}],"dr":[{"t":"make","q":"遅刻する → ～ことがある","a":"遅刻することがある","hint":"사전형 그대로 + こと + が + ある"},{"t":"make","q":"電話に出ない → ～ことがある","a":"電話に出ないことがある","hint":"ない형 그대로 + ことがある"},{"t":"fill","q":"兄[あに]はときどき夜中[よなか]まで勉強[べんきょう]する（　）。","a":"ことがある","opts":["ことがある","ことにした","ようになる","つもりだ"]}],"src":["https://guidetojapanese.org/learn/grammar/genericnouns"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_071","t":"～方（かた）","ko":"~하는 방법, ~하는 법","cat":"명사화·수식","conn":[{"w":"1그룹 동사","f":"使う → 使い + 方"},{"w":"2그룹 동사","f":"食べる → 食べ + 方"},{"w":"する동사","f":"勉強する → 勉強の + 仕方"},{"w":"来る","f":"来る → 来(き) + 方"}],"rule":["1. 동사를 ます형으로 만든다. 1그룹은 어미 う단을 い단으로 바꾼다: 使う → 使い.","2. 2그룹은 る를 뗀다: 食べる → 食べ.","3. 뒤에 方(かた)을 붙인다: 使い方.","4. 전체가 명사가 되므로 목적어의 を는 の로 바꾼다: パソコンを使う → パソコンの使い方.","5. する동사는 명사+の+仕方(しかた)로 쓴다: 勉強の仕方."],"why":"方는 '방향·방법'이라는 뜻의 글자로, 동사 ます형 뒤에서 かた로 읽혀 '~하는 방식'이라는 명사를 만든다.","nu":"회화·문어 모두 쓴다. 결과가 명사이므로 뒤에 を・が・は 등 조사가 바로 온다(使い方を教えて). 목적어 조사를 그대로 두어 ×パソコンを使い方라고 하는 실수가 잦다. 이 方는 ほう로 읽지 않는다.","cmp":[{"g":"～方法","d":"명사 '방법' 자체. 방식보다 수단을 가리키며 문어적: 連絡の方法."}],"ex":[{"jp":"このパソコンの使[つか]い方[かた]を教[おし]えてください。","ko":"이 컴퓨터 쓰는 법을 가르쳐 주세요."},{"jp":"母[はは]にカレーの作[つく]り方[かた]を習[なら]いました。","ko":"엄마에게 카레 만드는 법을 배웠어요."},{"jp":"漢字[かんじ]の勉強[べんきょう]の仕方[しかた]が分[わ]かりません。","ko":"한자 공부하는 방법을 모르겠어요."}],"dr":[{"t":"make","q":"書く → ～方","a":"書き方","hint":"く → き (ます형) + 方"},{"t":"make","q":"駅へ行く → ～方","a":"駅への行き方","hint":"동사는 ます형 + 方, 조사 へ 뒤에 の를 넣어 명사를 꾸민다"},{"t":"fill","q":"この漢字[かんじ]の読[よ]み（　）を教[おし]えてください。","a":"方","opts":["方","ところ","はず","まま"]}],"src":["https://bunpro.jp/grammar_points/かた","https://en.wiktionary.org/wiki/方"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_075","t":"～かどうか","ko":"~인지 아닌지, ~할지 어떨지","cat":"명사화·수식","conn":[{"w":"동사 보통형","f":"来る + かどうか"},{"w":"い형용사","f":"おいしい + かどうか"},{"w":"な형용사","f":"便利 + かどうか (だ 없음)"},{"w":"명사","f":"本当 + かどうか (だ 없음)"}],"rule":["1. 확실하지 않은 내용을 보통형으로 만든다: 彼が来る.","2. 끝에 かどうか를 붙인다: 来るかどうか.","3. 명사·な형용사는 だ를 빼고 바로 붙인다: 本当かどうか, 便利かどうか.","4. 뒤에 分からない・知らない・聞く・確かめる 같은 동사가 온다: 来るかどうか分からない."],"why":"의문의 か + どう(어떤지) + か로, 'A인지 (아니면) 어떤지'라는 예/아니오 의문을 문장 안에 넣는 형태다.","nu":"회화·문어 모두 쓴다. 예/아니오로 답할 내용에만 쓰고, 何・どこ・いつ 같은 의문사가 있으면 かどうか 대신 か만 쓴다(何時に来るか分からない). 명사·な형용사 뒤에 だ를 넣어 ×本当だかどうか라고 하는 실수에 주의.","cmp":[{"g":"의문사 + ～か","d":"의문사(何, どこ, だれ)가 있는 간접의문. ～かどうか는 의문사 없는 예/아니오 의문."}],"ex":[{"jp":"彼[かれ]がパーティーに来[く]るかどうか分[わ]かりません。","ko":"그가 파티에 올지 안 올지 모르겠어요."},{"jp":"このレストランがおいしいかどうか、友達[ともだち]に聞[き]いてみます。","ko":"이 레스토랑이 맛있는지 어떤지 친구에게 물어볼게요."},{"jp":"その話[はなし]が本当[ほんとう]かどうか、調[しら]べてください。","ko":"그 이야기가 사실인지 아닌지 조사해 주세요."}],"dr":[{"t":"make","q":"明日晴れる → ～分からない","a":"明日晴れるかどうか分からない","hint":"보통형 + かどうか + 分からない"},{"t":"make","q":"便利だ → ～かどうか","a":"便利かどうか","hint":"な형용사는 だ를 빼고 + かどうか"},{"t":"fill","q":"この答[こた]えが正[ただ]しい（　）、先生[せんせい]に聞[き]きましょう。","a":"かどうか","opts":["かどうか","かもしれない","ように","から"]}],"src":["https://bunpro.jp/grammar_points/かどうか"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_085","t":"そんな＋명사","ko":"그런 ~","cat":"명사화·수식","conn":[{"w":"명사","f":"そんな + こと"},{"w":"명사","f":"そんな + 話"},{"w":"형식명사","f":"そんな + の"}],"rule":["1. そんな는 형태가 바뀌지 않으며 명사 바로 앞에 놓는다(そんな＋こと→そんなこと).","2. の나 な 같은 연결 말 없이 붙인다(×そんなのこと).","3. 뒤에 조사·술어를 이어 문장을 만든다(そんなことない)."],"why":"こんな·そんな·あんな·どんな로 이어지는 こそあど 지시어 가운데 そ 계열로, 듣는 사람 쪽에 있는 것이나 방금 상대가 말한 내용을 가리킨다.","nu":"상대의 말을 받아 '그런~'이라고 할 때 가장 많이 쓴다. 놀람·부정·불만의 느낌이 실리기 쉽다(そんなこと言わないで). 상대의 겸손이나 자기비하를 부드럽게 부정하는 そんなことない(よ)는 회화 필수 표현. 명사 없이 '그것·그렇게'를 가리킬 때는 それ나 そう를 쓴다. 단독으로 そんな！라고 하면 '말도 안 돼!' 같은 놀람·불만의 감탄이 된다. 정중한 말에서는 そのような.","cmp":[{"g":"その＋명사","d":"특정한 바로 그것을 가리킨다. そんな는 '그런 종류·성질의' 것을 가리킨다."},{"g":"こんな / あんな","d":"こんな는 말하는 사람 쪽이나 지금부터 말할 것, あんな는 둘 다 아는 멀리 있는 것을 가리킨다."}],"ex":[{"jp":"そんなことないよ。上手[じょうず]だよ。","ko":"그렇지 않아. 잘하는걸."},{"jp":"そんな話[はなし]、聞[き]いたことがありません。","ko":"그런 이야기는 들어 본 적이 없어요."},{"jp":"そんな高[たか]い時計[とけい]は買[か]えない。","ko":"그런 비싼 시계는 살 수 없어."}],"dr":[{"t":"make","q":"こと → そんな～","a":"そんなこと","hint":"そんな를 명사 바로 앞에 놓는다."},{"t":"make","q":"人 → そんな～","a":"そんな人","hint":"연결 말 없이 そんな + 명사."},{"t":"fill","q":"A「私[わたし]、歌[うた]が下手[へた]で…」B「（　）ことないよ。」","a":"そんな","opts":["そんな","その","そう","それ"]}],"src":["https://tofugu.com/japanese-grammar/konna-sonna-anna-donna"],"vf":1,"u":5,"g":1,"gp":"gg_N4_03"},{"id":"g4_092","t":"～っていう","ko":"~라는","cat":"명사화·수식","conn":[{"w":"명사","f":"ハチ + っていう + 犬"},{"w":"동사 보통형","f":"会社をやめる + っていう + 話"},{"w":"い형용사","f":"おいしい + っていう + 店"},{"w":"な형용사·명사(だ 붙음)","f":"有名だ + っていう + うわさ"}],"rule":["1. 이름이나 내용을 나타내는 말 바로 뒤에 っていう를 붙이고, 그 뒤에 설명할 명사를 놓는다(ハチ+っていう+犬).","2. 문장이 올 때는 보통형으로 끝낸 뒤 붙인다(やめる+っていう+話).","3. っていう는 という를 회화에서 줄인 꼴이다(と→って)."],"why":"인용 조사 と의 회화형 って에 言う가 이어진 것으로, という의 구어형이다.","nu":"친구·가족 사이의 회화체. 정중한 자리나 글에서는 という를 쓴다. 상대가 모를 것 같은 이름을 소개할 때 자주 쓴다(田中っていう人). 명사 없이 ってのは / っていうのは로 화제를 정의하기도 한다.","cmp":[{"g":"～という","d":"뜻은 같고 중립·문어 형태. 글과 정중한 회화에서 쓴다."},{"g":"～って(문말)","d":"명사를 꾸미지 않고 문장 끝에서 '~래'라는 전문을 나타낸다."}],"ex":[{"jp":"駅[えき]の前[まえ]に「さくら」っていう喫茶店[きっさてん]があるよ。","ko":"역 앞에 '사쿠라'라는 찻집이 있어."},{"jp":"山田[やまだ]さんが会社[かいしゃ]をやめるっていう話[はなし]、聞[き]いた？","ko":"야마다 씨가 회사를 그만둔다는 얘기 들었어?"},{"jp":"これ、何[なん]ていう花[はな]？","ko":"이거 뭐라는 꽃이야?"}],"dr":[{"t":"make","q":"ポチ / 犬 → ～っていう","a":"ポチっていう犬","hint":"이름 + っていう + 명사 순서."},{"t":"make","q":"雨が降る / 予報 → ～っていう","a":"雨が降るっていう予報","hint":"보통형 문장 뒤에 っていう를 붙이고 명사를 놓는다."},{"t":"fill","q":"「ハナ」（　）猫[ねこ]を飼[か]っています。","a":"っていう","opts":["っていう","らしい","みたいな","ような"]}],"src":["https://www.tofugu.com/japanese-grammar/toiu/","https://www.vnjpclub.com/en/n4-grammar/tteiu.html"],"vf":1,"u":6,"g":1,"gp":"gg_N4_03"},{"id":"g4_099","t":"～という＋명사","ko":"~라는 (명사)","cat":"명사화·수식","conn":[{"w":"명사(이름)","f":"富士山 + という + 山"},{"w":"동사 보통형(내용)","f":"雨が降る + という + 予報"},{"w":"い형용사(내용)","f":"おいしい + という + 評判"},{"w":"な형용사·명사(내용)","f":"便利だ + という + 話"}],"rule":["1. 이름을 나타내는 명사 뒤에 という를 붙이고, 그것이 속한 종류의 명사를 놓는다(富士山+という+山).","2. 문장이 내용이 될 때는 보통형으로 끝낸 뒤 という+명사(雨が降る+という+予報).","3. という 자체는 활용하지 않는다."],"why":"인용 조사 と + 言う(말하다)로 '~라고 말하는 → ~라고 불리는'이 되어 이름·내용을 명사에 연결한다. 이 용법에서는 보통 히라가나 いう로 쓴다.","nu":"듣는 사람이 모를 수 있는 고유명사를 소개할 때 쓴다(ABCという会社). 이미 서로 아는 대상에는 잘 쓰지 않는다. 회화에서는 っていう로 준다. 내용 명사로는 話·うわさ·意見·ニュース·こと 등이 자주 온다.","cmp":[{"g":"～っていう","d":"같은 뜻의 회화형."},{"g":"～の(명사+の+명사)","d":"소유·소속. 富士山の写真은 '후지산의 사진', 富士山という山은 '후지산이라는 이름의 산'."}],"ex":[{"jp":"日本[にほん]には富士山[ふじさん]という高[たか]い山[やま]があります。","ko":"일본에는 후지산이라는 높은 산이 있습니다."},{"jp":"「たなか」という店[みせ]を知[し]っていますか。","ko":"'다나카'라는 가게를 알고 있습니까?"},{"jp":"来月[らいげつ]値段[ねだん]が上[あ]がるというニュースを見[み]ました。","ko":"다음 달에 가격이 오른다는 뉴스를 봤습니다."}],"dr":[{"t":"make","q":"さくら / 花 → ～という","a":"さくらという花","hint":"이름 + という + 종류 명사."},{"t":"make","q":"店が閉まる / うわさ → ～という","a":"店が閉まるといううわさ","hint":"보통형 문장 + という + 내용 명사."},{"t":"fill","q":"これは「すし」（　）日本[にほん]の料理[りょうり]です。","a":"という","opts":["という","らしい","ような","ばかりの"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86-called"],"vf":1,"u":6,"g":1,"gp":"gg_N4_03"},{"id":"g4_100","t":"どういう＋명사","ko":"어떤 ~, 어떤 종류의 ~","cat":"명사화·수식","conn":[{"w":"명사","f":"どういう + 映画"},{"w":"명사","f":"どういう + 意味"},{"w":"형식명사","f":"どういう + こと"}],"rule":["1. どういう는 형태가 바뀌지 않으며 명사 바로 앞에 놓는다(どういう+映画).","2. の 같은 연결 말 없이 붙인다(×どういうの映画).","3. 뒤에 ですか·조사·술어를 이어 질문을 만든다(どういう映画ですか)."],"why":"","nu":"대상의 내용·성질·종류를 자세히 묻는다. どんな와 비슷하지만 どういう는 내용·이유를 따지는 느낌이 있어 どういう意味ですか(무슨 뜻이에요?), どういうこと？(어떻게 된 거야?)가 대표적이다. どういうこと？는 말투에 따라 따지는 느낌이 되니 주의. 정중하게는 どのような.","cmp":[{"g":"どんな＋명사","d":"외견·인상 등 넓게 묻는 회화 표현. どういう는 내용·성격·의미 쪽."},{"g":"どの＋명사","d":"여러 개 가운데 '어느 것'을 고르게 한다."}],"ex":[{"jp":"どういう映画[えいが]が好[す]きですか。","ko":"어떤 영화를 좋아하세요?"},{"jp":"この言葉[ことば]はどういう意味[いみ]ですか。","ko":"이 말은 무슨 뜻입니까?"},{"jp":"お父[とう]さんはどういう仕事[しごと]をしていますか。","ko":"아버지는 어떤 일을 하고 계세요?"}],"dr":[{"t":"make","q":"人 → どういう～","a":"どういう人","hint":"どういう를 명사 바로 앞에 놓는다."},{"t":"make","q":"意味 / ですか → どういう～","a":"どういう意味ですか","hint":"どういう + 명사 + ですか."},{"t":"fill","q":"それは（　）ことですか。よくわかりません。","a":"どういう","opts":["どういう","どう","どれ","どこ"]}],"src":["https://bunpro.jp/ja/grammar_points/369"],"vf":1,"u":6,"g":1,"gp":"gg_N4_03"},{"id":"g4_013","t":"名詞をあげる","ko":"(내가/남이 남에게) ~을 주다","cat":"수수·사역·수동","conn":[{"w":"명사(물건) + を","f":"花をあげる"},{"w":"받는 사람 + に","f":"友達に花をあげる"},{"w":"정중형","f":"あげます"},{"w":"과거","f":"あげた / あげました"}],"rule":["주는 물건(명사) 뒤에 を, 받는 사람 뒤에 に를 붙인다: 友達に花をあげる.","あげる는 1그룹이 아닌 2그룹(る) 동사라 어미 る를 떼고 ます・ました를 붙인다: あげる → あげました.","주는 쪽이 나(또는 내 쪽 사람)이고 받는 쪽이 바깥사람일 때 쓴다. 나에게 주는 경우에는 쓰지 않는다."],"why":"","nu":"회화·문장 모두 쓰는 기본형. 손윗사람에게는 さしあげる를 쓰고, 동식물에게는 やる를 쓰기도 한다. 남이 나에게 줄 때 あげる를 쓰는 실수(×友達が私にあげた)가 가장 많다. 이때는 くれる를 쓴다.","cmp":[{"g":"名詞をくれる","d":"くれる는 남이 나(내 쪽)에게 줄 때. あげる는 내가(또는 남이) 바깥사람에게 줄 때."},{"g":"名詞をさしあげる","d":"さしあげる는 손윗사람에게 주는 겸양 표현."}],"ex":[{"jp":"妹[いもうと]に誕生日[たんじょうび]のプレゼントをあげた。","ko":"여동생에게 생일 선물을 줬다."},{"jp":"田中[たなか]さんは山田[やまだ]さんに花[はな]をあげました。","ko":"다나카 씨는 야마다 씨에게 꽃을 줬어요."},{"jp":"このお菓子[かし]、一[ひと]つあげるよ。","ko":"이 과자 하나 줄게."}],"dr":[{"t":"make","q":"友達に本をあげる → 정중 과거","a":"友達に本をあげました","hint":"あげる의 る를 떼고 ました."},{"t":"make","q":"弟 / ゲーム → '남동생에게 게임을 준다'","a":"弟にゲームをあげる","hint":"받는 사람 + に, 물건 + を + あげる."},{"t":"fill","q":"私[わたし]は友達[ともだち]にお土産[みやげ]を（　）。","a":"あげました","opts":["あげました","くれました","もらいました","くださいました"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201409.html","https://guidetojapanese.org/learn/?p=249"],"vf":1,"u":6,"g":1,"gp":"gg_N4_04"},{"id":"g4_016","t":"名詞をくれる","ko":"(남이 나에게) ~을 주다","cat":"수수·사역·수동","conn":[{"w":"명사(물건) + を","f":"花をくれる"},{"w":"주는 사람 + が, 받는 사람(나·내 쪽) + に","f":"友達が私にくれる"},{"w":"정중 과거","f":"くれました"},{"w":"받는 사람 생략","f":"母がケーキをくれた"}],"rule":["주는 사람 뒤에 が, 받는 사람(나 또는 내 가족 등) 뒤에 に, 물건 뒤에 を를 붙인다.","くれる는 2그룹(る) 동사라 어미 る를 떼고 ます・ました를 붙인다: くれる → くれました.","받는 쪽이 나일 때는 私に를 자주 생략한다."],"why":"","nu":"회화·문장 모두 쓰는 기본형. 받는 쪽이 반드시 나 또는 내 쪽(가족·동료 등) 사람이다. 내가 남에게 줄 때는 쓸 수 없다(×私が友達にくれた). 한국어 '주다'는 방향을 가리지 않아서 あげる와 혼동하기 쉽다. 윗사람이 주면 くださる.","cmp":[{"g":"名詞をあげる","d":"あげる는 나(내 쪽)에서 바깥으로. くれる는 바깥에서 나(내 쪽)로."},{"g":"名詞をもらう","d":"もらう는 받는 사람이 주어(私が友達にもらう). くれる는 주는 사람이 주어(友達が私にくれる)."}],"ex":[{"jp":"友達[ともだち]が誕生日[たんじょうび]にケーキをくれた。","ko":"친구가 생일에 케이크를 줬다."},{"jp":"祖母[そぼ]が妹[いもうと]に人形[にんぎょう]をくれました。","ko":"할머니가 여동생에게 인형을 주셨어요."},{"jp":"隣[となり]の人[ひと]がりんごをくれました。","ko":"옆집 사람이 사과를 줬어요."}],"dr":[{"t":"make","q":"兄が私に時計をくれる → 정중 과거","a":"兄が私に時計をくれました","hint":"くれる의 る를 떼고 ました."},{"t":"make","q":"友達 / 傘 → '친구가 (나에게) 우산을 줬다(보통 과거)'","a":"友達が傘をくれた","hint":"주는 사람 + が, 물건 + を + くれた."},{"t":"fill","q":"山田[やまだ]さんが私[わたし]にチョコレートを（　）。","a":"くれました","opts":["くれました","あげました","さしあげました","いただきました"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201409.html","https://guidetojapanese.org/learn/?p=249"],"vf":1,"u":6,"g":1,"gp":"gg_N4_04"},{"id":"g4_018","t":"名詞をもらう","ko":"~을 받다","cat":"수수·사역·수동","conn":[{"w":"명사(물건) + を","f":"花をもらう"},{"w":"주는 사람 + に","f":"友達に花をもらう"},{"w":"주는 사람 + から","f":"友達から花をもらう"},{"w":"정중 과거","f":"もらいました"}],"rule":["받는 사람(주어) 뒤에 が・は, 주는 사람 뒤에 に 또는 から, 물건 뒤에 を를 붙인다.","もらう는 1그룹 동사라 어미 う를 い로 바꾸고 ます・ました를 붙인다: もらう → もらいました.","주는 쪽이 회사·학교 같은 단체이면 から를 쓴다(会社から)."],"why":"","nu":"회화·문장 모두 쓰는 기본형. 받는 사람의 입장에서 말한다. 윗사람에게서 받을 때는 いただく. 한국어 '~에게 받다'에 끌려 주는 사람에 に를 쓰는 것이 이상하게 느껴질 수 있지만, に와 から 모두 맞다.","cmp":[{"g":"名詞をくれる","d":"같은 사건을 くれる는 주는 사람을 주어로(友達が私にくれた), もらう는 받는 사람을 주어로(私は友達にもらった) 말한다."},{"g":"名詞をいただく","d":"いただく는 윗사람에게서 받을 때의 겸양 표현."}],"ex":[{"jp":"友達[ともだち]に誕生日[たんじょうび]のプレゼントをもらった。","ko":"친구에게 생일 선물을 받았다."},{"jp":"父[ちち]からお小遣[こづか]いをもらいました。","ko":"아버지에게 용돈을 받았어요."},{"jp":"会社[かいしゃ]から手紙[てがみ]をもらった。","ko":"회사로부터 편지를 받았다."}],"dr":[{"t":"make","q":"姉に本をもらう → 정중 과거","a":"姉に本をもらいました","hint":"もらう의 う를 い로 바꾸고 ました."},{"t":"make","q":"母 / 手紙 → '엄마에게서 편지를 받았다(から 사용, 보통 과거)'","a":"母から手紙をもらった","hint":"주는 사람 + から, 물건 + を + もらった."},{"t":"fill","q":"私[わたし]は友達[ともだち]にチョコレートを（　）。","a":"もらいました","opts":["もらいました","くれました","さしあげました","くださいました"]}],"src":["https://guidetojapanese.org/learn/?p=249","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201409.html"],"vf":1,"u":6,"g":1,"gp":"gg_N4_04"},{"id":"g4_020","t":"～させられる（使役受身）","ko":"(억지로) ~하게 되다, 시킴을 당하다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"書く → 書かせられる(書かされる)"},{"w":"1그룹 す동사","f":"話す → 話させられる(축약 없음)"},{"w":"2그룹 동사","f":"食べる → 食べさせられる"},{"w":"する","f":"する → させられる"},{"w":"来る","f":"来る → 来(こ)させられる"}],"rule":["1그룹 동사는 어미 う단을 あ단으로 바꾼다(書く → 書か, う는 わ: 買う → 買わ).","거기에 せられる를 붙인다: 書か + せられる → 書かせられる. 회화에서는 せら를 줄여 書かされる로도 쓴다(す로 끝나는 동사는 축약하지 않는다).","2그룹 동사는 る를 떼고 させられる를 붙인다(食べる → 食べさせられる).","불규칙: する → させられる, 来る → 来(こ)させられる."],"why":"사역형 させる(시키다)를 다시 수동형 られる로 바꾼 형태다. 그래서 '시킴을 당하다', 즉 원하지 않는데 억지로 하게 되었다는 뜻이 된다.","nu":"시킴을 당한 사람의 입장에서 말하며 대개 '하기 싫었는데 억지로'라는 불만의 뉘앙스가 있다. 당한 사람은 が(は), 시킨 사람은 に로 나타낸다(私は母に部屋を掃除させられた). 수동의 れる로 바꿔 書かせれる라고 하는 것은 틀림. 회화체에서는 書かされる・飲まされる 같은 축약형이 더 흔하다.","cmp":[{"g":"～させる（使役）","d":"시키는 사람이 주어. させられる는 시킴을 당한 사람이 주어."},{"g":"～られる（受身）","d":"남의 행위를 받음. させられる는 '하게 시킴'을 받아 결국 자기가 그 행동을 함."}],"ex":[{"jp":"子[こ]どものころ、母[はは]に野菜[やさい]を食[た]べさせられました。","ko":"어릴 때 엄마가 억지로 채소를 먹게 했어요."},{"jp":"先生[せんせい]に作文[さくぶん]を書[か]かせられた。","ko":"선생님이 시켜서 작문을 (억지로) 썼다."},{"jp":"部長[ぶちょう]にお酒[さけ]を飲[の]まされて、大変[たいへん]でした。","ko":"부장님이 술을 먹여서 힘들었어요."}],"dr":[{"t":"make","q":"待つ → 사역수동(긴 형태)","a":"待たせられる","hint":"つ를 あ단 た로 바꾸고 せられる."},{"t":"make","q":"掃除する → 사역수동","a":"掃除させられる","hint":"する는 させられる로."},{"t":"fill","q":"私[わたし]は泣[な]きながら、母[はは]に嫌[きら]いな野菜[やさい]を（　）。","a":"食べさせられた","opts":["食べさせられた","食べさせた","食べたがった","食べるそうだ"]}],"src":["https://bunpro.jp/ja/grammar_points/causative-passive","https://laits.utexas.edu/japanese/joshu/grammar/glist/y2/ch6/gl_y2_ch6_causativepassive.php"],"vf":1,"u":6,"g":1,"gp":"gg_N4_04"},{"id":"g4_021","t":"～させる（使役）","ko":"~하게 하다, ~시키다, ~하게 해 주다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"飲む → 飲ませる"},{"w":"1그룹 う동사","f":"買う → 買わせる"},{"w":"2그룹 동사","f":"食べる → 食べさせる"},{"w":"する","f":"する → させる"},{"w":"来る","f":"来る → 来(こ)させる"}],"rule":["1그룹 동사는 어미 う단을 あ단으로 바꾼다(飲む → 飲ま). 끝이 う이면 わ로 바꾼다(買う → 買わ).","あ단 뒤에 せる를 붙인다: 飲ま + せる → 飲ませる.","2그룹 동사는 る를 떼고 させる를 붙인다(食べる → 食べさせる).","불규칙: する → させる, 来る → 来(こ)させる. 만든 させる는 2그룹 동사처럼 활용한다(飲ませた, 飲ませて)."],"why":"","nu":"강제(억지로 시키다)와 허용(하게 해 주다) 두 뜻이 있고 문맥으로 구별한다. 자동사는 행위자를 を나 に로 표시하며, を는 강제 느낌이, に는 본인 의지를 허용하는 느낌이 강하다(子どもを走らせる). 타동사는 목적어에 を가 이미 있으므로 행위자는 に로 쓴다(子どもに薬を飲ませる). 윗사람을 주어로 '시키다'라고 하면 실례이므로 윗사람에게는 쓰지 않는다. 허락을 구할 때는 '～させてください'를 쓴다.","cmp":[{"g":"～させられる","d":"시킴을 당한 사람이 주어(억지로 하게 됨)."},{"g":"～てもらう","d":"남에게 부탁해 해 받음. させる는 윗사람이 아랫사람에게 시키는 느낌."}],"ex":[{"jp":"母[はは]は子[こ]どもに薬[くすり]を飲[の]ませた。","ko":"엄마는 아이에게 약을 먹였다."},{"jp":"先生[せんせい]は学生[がくせい]に教科書[きょうかしょ]を読[よ]ませました。","ko":"선생님은 학생에게 교과서를 읽게 했습니다."},{"jp":"すみません、少[すこ]し考[かんが]えさせてください。","ko":"죄송해요, 조금 생각하게 해 주세요."}],"dr":[{"t":"make","q":"書く → 사역형","a":"書かせる","hint":"く를 あ단 か로 바꾸고 せる."},{"t":"make","q":"来る → 사역형","a":"来させる","hint":"来る는 불규칙: こさせる."},{"t":"fill","q":"父[ちち]は弟[おとうと]に部屋[へや]を掃除[そうじ]（　）。","a":"させた","opts":["させた","できた","したがった","しそうだ"]}],"src":["https://bunpro.jp/ja/grammar_points/causative","https://langoal.com/jlpt/explain-grammar-saseru-force.html"],"vf":1,"u":6,"g":1,"gp":"gg_N4_04"},{"id":"g4_028","t":"～てあげる","ko":"~해 주다 (내가 남에게)","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"持つ → 持ってあげる"},{"w":"2그룹 동사","f":"見せる → 見せてあげる"},{"w":"する","f":"する → してあげる"},{"w":"来る","f":"来る → 来(き)てあげる"},{"w":"예외 行く","f":"行く → 行ってあげる"}],"rule":["동사를 て형으로 바꾼다. つ・う・る로 끝나는 1그룹 동사는 어미가 って가 된다(持つ → 持って).","て형 뒤에 あげる를 붙인다: 持って + あげる.","받는 사람은 に로 나타낸다(友だちに本を貸してあげる). 단, 직접 그 사람을 대상으로 하는 동사는 원래 조사를 유지한다(友だちを手伝ってあげる, 母の荷物を持ってあげる)."],"why":"あげる(주다)를 보조동사로 써서 '동작을 남에게 준다', 즉 내(또는 나 쪽 사람)가 남을 위해 그 행동을 한다는 뜻이 된다.","nu":"주는 쪽이 나(나 쪽)이고 받는 쪽이 남이다. 상대에게 직접 '~てあげます'라고 하면 생색내는 느낌이 들어 실례가 될 수 있으므로 윗사람에게는 쓰지 말고 'お持ちしましょうか'처럼 겸양 표현을 쓴다. 윗사람이 받을 때의 겸양형은 ～てさしあげる, 동물·식물이나 아주 친한 아랫사람에게는 ～てやる.","cmp":[{"g":"～てくれる","d":"남이 나(나 쪽)에게 해 줌. てあげる는 내가 남에게 해 줌."},{"g":"～てもらう","d":"내가 남에게 해 받음(받는 사람이 주어)."}],"ex":[{"jp":"おばあさんの荷物[にもつ]を持[も]ってあげました。","ko":"할머니의 짐을 들어 드렸어요."},{"jp":"妹[いもうと]に絵本[えほん]を読[よ]んであげた。","ko":"여동생에게 그림책을 읽어 줬다."},{"jp":"友[とも]だちに駅[えき]までの道[みち]を教[おし]えてあげた。","ko":"친구에게 역까지 가는 길을 가르쳐 줬다."}],"dr":[{"t":"make","q":"貸す → '빌려 주다(내가 남에게)'","a":"貸してあげる","hint":"す는 して로 바꾸고 + あげる."},{"t":"make","q":"手伝う → '도와줬다'","a":"手伝ってあげた","hint":"う는 って로 바꾸고 + あげた."},{"t":"fill","q":"弟[おとうと]が困[こま]っていたので、私[わたし]が宿題[しゅくだい]を手伝[てつだ]って（　）。","a":"あげた","opts":["あげた","くれた","もらった","ほしい"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%81%82%E3%81%92%E3%82%8B"],"vf":1,"u":6,"g":1,"gp":"gg_N4_04"},{"id":"g4_031","t":"～ていただきたい","ko":"~해 주셨으면 한다, ~해 주시기 바란다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"書く → 書いて + いただきたい"},{"w":"2그룹 동사","f":"見る → 見て + いただきたい"},{"w":"する","f":"説明する → 説明して + いただきたい"},{"w":"来る","f":"来る → 来て + いただきたい"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 く는 いて(書く→書いて), 2그룹은 る를 떼고 て(見る→見て), する→して, 来る→来て.","2. て형 뒤에 いただく(もらう의 겸양어)의 ます형 어간 いただき를 붙인다.","3. 희망의 たい를 붙여 ～ていただきたい로 만든다. 문말에는 보통 です나 のですが를 덧붙인다."],"why":"て형 + いただく(もらう '받다'의 겸양어) + たい(희망). 직역하면 '(윗사람에게) ~해 받고 싶다'로, 상대가 해 주기를 바라는 마음을 정중하게 나타낸다.","nu":"격식체. 윗사람·손님에게 바람을 정중하게 전하며, 사실상 부탁으로 쓰인다. 해 주는 사람은 に로 나타낸다(先生に見ていただきたい). 'のですが'로 말끝을 흐리면 더 부드러운 부탁이 된다. 자기 자신의 행동에는 쓰지 않는다(자기 희망은 그냥 ～たい).","cmp":[{"g":"～てほしい","d":"같은 '해 주길 바란다'지만 보통체로 친한 사이에 쓴다. 윗사람에게는 ～ていただきたい."},{"g":"～ていただけませんか","d":"상대에게 묻는 의뢰 형식이라 바람을 말하는 ～ていただきたい보다 더 부드럽다."}],"ex":[{"jp":"先生[せんせい]に作文[さくぶん]を見[み]ていただきたいです。","ko":"선생님께서 작문을 봐 주셨으면 해요."},{"jp":"ここにお名前[なまえ]を書[か]いていただきたいのですが。","ko":"여기에 성함을 써 주셨으면 하는데요."},{"jp":"明日[あした]の会議[かいぎ]には部長[ぶちょう]にも来[き]ていただきたいです。","ko":"내일 회의에는 부장님께서도 와 주셨으면 합니다."}],"dr":[{"t":"make","q":"待つ → ～ていただきたい","a":"待っていただきたい","hint":"つ → って (촉음편) + いただきたい"},{"t":"make","q":"説明する → ～ていただきたい","a":"説明していただきたい","hint":"する → して + いただきたい"},{"t":"fill","q":"先生[せんせい]、この漢字[かんじ]の読[よ]み方[かた]を教[おし]えて（　）のですが。","a":"いただきたい","opts":["いただきたい","あげたい","しまいたい","おきたい"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201507.html","https://bunpro.jp/grammar_points/134"],"vf":1,"u":7,"g":1,"gp":"gg_N4_04"},{"id":"g4_032","t":"～ていただく","ko":"(윗사람이) ~해 주시다 (내가 ~해 받다)","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"送る → 送って + いただく"},{"w":"2그룹 동사","f":"教える → 教えて + いただく"},{"w":"する","f":"案内する → 案内して + いただく"},{"w":"来る","f":"来る → 来て + いただく"}],"rule":["1. 동사를 て형으로 바꾼다. 2그룹은 る를 떼고 て(教える→教えて), 1그룹은 음편(送る→送って).","2. て형 뒤에 いただく를 붙인다. 해 준 사람은 に로 나타낸다(先生に教えていただく).","3. いただく는 1그룹 동사로 활용한다: いただきます, いただいた, いただいて(く→いて)."],"why":"いただく는 もらう(받다)의 겸양어여서, ～てもらう를 정중하게 말할 때 ～ていただく가 된다. 문법상 주어는 혜택을 받는 '나'다.","nu":"정중체·겸양. 윗사람에게 받은 도움을 말하거나 감사할 때 많이 쓴다(～ていただいて、ありがとうございます). 한국어로는 '~해 주시다'로 옮기지만 주어는 받는 쪽(나)이고 해 준 사람은 に로 나온다. が로 쓰는 실수에 주의. 친구 사이에는 ～てもらう.","cmp":[{"g":"～てくださる","d":"해 주는 사람이 주어(先生が教えてくださる). ～ていただく는 받는 사람이 주어이고 해 준 사람은 に."},{"g":"～てもらう","d":"뜻은 같고 보통체. 친구·가족에게 쓴다."}],"ex":[{"jp":"先生[せんせい]に日本語[にほんご]を教[おし]えていただきました。","ko":"선생님께서 일본어를 가르쳐 주셨습니다."},{"jp":"駅[えき]まで送[おく]っていただいて、ありがとうございました。","ko":"역까지 바래다주셔서 감사했습니다."},{"jp":"この書類[しょるい]は部長[ぶちょう]にチェックしていただきます。","ko":"이 서류는 부장님께 확인을 받겠습니다."}],"dr":[{"t":"make","q":"教える → ～ていただきました","a":"教えていただきました","hint":"る를 떼고 て + いただきました"},{"t":"make","q":"手伝う → ～ていただく","a":"手伝っていただく","hint":"う → って (촉음편) + いただく"},{"t":"fill","q":"先生[せんせい]に作文[さくぶん]を直[なお]して（　）、ありがとうございました。","a":"いただいて","opts":["いただいて","くださって","くれて","あげて"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201507.html","https://bunpro.jp/grammar_points/134"],"vf":1,"u":7,"g":1,"gp":"gg_N4_04"},{"id":"g4_033","t":"～ていただけませんか","ko":"~해 주실 수 없을까요?","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"待つ → 待って + いただけませんか"},{"w":"2그룹 동사","f":"見せる → 見せて + いただけませんか"},{"w":"する","f":"説明する → 説明して + いただけませんか"},{"w":"来る","f":"来る → 来て + いただけませんか"}],"rule":["1. 동사를 て형으로 바꾼다(待つ→待って, 見せる→見せて).","2. いただく를 가능형 いただける로 바꾼다: 어미 く를 け로 바꾸고 る를 붙인다.","3. いただける의 ます형 부정은 る를 떼고 ません: いただけません. 끝에 의문의 か를 붙인다."],"why":"いただく(もらう의 겸양어)의 가능형 いただける를 부정 의문으로 만든 것. '~해 받을 수 없겠습니까?'라고 물어 상대가 거절할 여지를 남기므로 정중한 부탁이 된다(～てもらえませんか의 겸양판).","nu":"정중체. 손님·상사·처음 보는 사람에게 부탁할 때. ～てください보다 훨씬 부드럽고 공손하다. 긍정 ～ていただけますか보다 부정 의문 쪽이 더 조심스러운 느낌. 친구에게는 ～てくれない?","cmp":[{"g":"～てくださいませんか","d":"상대가 주어인 존경 표현. 정중도는 비슷하다."},{"g":"～てください","d":"보통의 정중한 의뢰. 지시처럼 들릴 수 있어 윗사람에게는 ～ていただけませんか가 낫다."}],"ex":[{"jp":"すみません、ちょっと待[ま]っていただけませんか。","ko":"죄송한데 잠깐 기다려 주실 수 없을까요?"},{"jp":"その写真[しゃしん]を見[み]せていただけませんか。","ko":"그 사진을 보여 주실 수 없을까요?"},{"jp":"もう少[すこ]しゆっくり説明[せつめい]していただけませんか。","ko":"조금 더 천천히 설명해 주실 수 없을까요?"}],"dr":[{"t":"make","q":"貸す → ～ていただけませんか","a":"貸していただけませんか","hint":"す → して + いただけませんか"},{"t":"make","q":"来る → ～ていただけませんか","a":"来ていただけませんか","hint":"来る(くる) → 来て(きて) + いただけませんか"},{"t":"fill","q":"申[もう]し訳[わけ]ありませんが、少[すこ]し静[しず]かにして（　）。","a":"いただけませんか","opts":["いただけませんか","あげませんか","おきませんか","しまいませんか"]}],"src":["https://bunpro.jp/grammar_points/134","https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%81%84%E3%81%9F%E3%81%A0%E3%81%91%E3%81%BE%E3%81%9B%E3%82%93%E3%81%8B"],"vf":1,"u":7,"g":1,"gp":"gg_N4_04"},{"id":"g4_038","t":"～てくださいませんか","ko":"~해 주시지 않겠습니까?","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"待つ → 待って + くださいませんか"},{"w":"2그룹 동사","f":"閉める → 閉めて + くださいませんか"},{"w":"する","f":"説明する → 説明して + くださいませんか"},{"w":"来る","f":"来る → 来て + くださいませんか"}],"rule":["1. 동사를 て형으로 바꾼다(閉める→閉めて).","2. くださる의 ます형은 특수해서 어미 る가 い로 바뀐 くださいます가 된다(くださります가 아님).","3. 부정 くださいません에 의문의 か를 붙여 ～てくださいませんか로 만든다."],"why":"くださる는 くれる(나에게 주다)의 존경어. 그 ます형 부정 의문 '~해 주시지 않겠습니까?'로 물어 상대에게 정중히 부탁한다.","nu":"정중체. 윗사람·처음 보는 사람에게 부탁할 때. ～てください보다 공손하고 부드럽다. 해 주는 사람(상대)을 높이는 존경 표현이다. 친구에게는 ～てくれない?","cmp":[{"g":"～ていただけませんか","d":"정중도는 비슷하다. 받는 '나'를 낮추는 겸양 표현(いただく)이고, ～てくださいませんか는 해 주는 상대를 높이는 존경 표현(くださる)."},{"g":"～てくれませんか","d":"くれる를 쓴 덜 격식 있는 부탁. 친구·동료에게."}],"ex":[{"jp":"すみません、窓[まど]を閉[し]めてくださいませんか。","ko":"죄송한데 창문을 닫아 주시지 않겠어요?"},{"jp":"先生[せんせい]、もう一度[いちど]説明[せつめい]してくださいませんか。","ko":"선생님, 한 번 더 설명해 주시지 않겠어요?"},{"jp":"この本[ほん]をしばらく貸[か]してくださいませんか。","ko":"이 책을 잠시 빌려주시지 않겠어요?"}],"dr":[{"t":"make","q":"待つ → ～てくださいませんか","a":"待ってくださいませんか","hint":"つ → って + くださいませんか"},{"t":"make","q":"見せる → ～てくださいませんか","a":"見せてくださいませんか","hint":"る를 떼고 て + くださいませんか"},{"t":"fill","q":"先生[せんせい]、この作文[さくぶん]を読[よ]んで（　）。","a":"くださいませんか","opts":["くださいませんか","いただきませんか","あげませんか","おきませんか"]}],"src":["https://elon.io/grammar/japanese/verb-reference/kudasaru-paradigm","https://bunpro.jp/grammar_points/103"],"vf":1,"u":7,"g":1,"gp":"gg_N4_04"},{"id":"g4_039","t":"～てくださる","ko":"(윗사람이 나에게) ~해 주시다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"手伝う → 手伝って + くださる"},{"w":"2그룹 동사","f":"教える → 教えて + くださる"},{"w":"する","f":"案内する → 案内して + くださる"},{"w":"来る","f":"来る → 来て + くださる"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 う는 って(手伝う→手伝って).","2. て형 뒤에 くださる를 붙인다. 해 주는 윗사람이 주어(が・は)다.","3. くださる의 ます형은 くださいます(る→い 특수), 과거는 くださった / くださいました."],"why":"くださる는 くれる(남이 나에게 주다)의 존경어. 그래서 ～てくれる를 윗사람에게 쓰면 ～てくださる가 된다.","nu":"존경 표현. 행위자는 윗사람(先生が), 받는 사람은 나 또는 우리 쪽. 감사하는 마음이 담긴다. 보통 ます형(くださいます / くださいました)으로 쓴다. くださります는 틀린 형태.","cmp":[{"g":"～ていただく","d":"받는 사람이 주어이고 해 준 사람은 に(先生に手伝っていただく). ～てくださる는 해 준 사람이 주어(先生が手伝ってくださる)."},{"g":"～てくれる","d":"같은 방향의 보통체. 친구·가족에게."}],"ex":[{"jp":"先生[せんせい]が重[おも]い荷物[にもつ]を運[はこ]ぶのを手伝[てつだ]ってくださいました。","ko":"선생님께서 무거운 짐 나르는 걸 도와주셨습니다."},{"jp":"社長[しゃちょう]が駅[えき]まで車[くるま]で送[おく]ってくださいました。","ko":"사장님께서 역까지 차로 바래다주셨습니다."},{"jp":"先生[せんせい]はいつも丁寧[ていねい]に説明[せつめい]してくださいます。","ko":"선생님은 늘 친절하게 설명해 주십니다."}],"dr":[{"t":"make","q":"教える → ～てくださいました","a":"教えてくださいました","hint":"る를 떼고 て + くださいました"},{"t":"make","q":"来る → ～てくださいました","a":"来てくださいました","hint":"来る(くる) → 来て(きて) + くださいました"},{"t":"fill","q":"先生[せんせい]が手紙[てがみ]を読[よ]んで（　）。","a":"くださいました","opts":["くださいました","いただきました","おりました","もらいました"]}],"src":["https://elon.io/grammar/japanese/verb-reference/kudasaru-paradigm","https://bunpro.jp/grammar_points/103"],"vf":1,"u":7,"g":1,"gp":"gg_N4_04"},{"id":"g4_041","t":"～てくれませんか","ko":"~해 주지 않을래요?, ~해 줄 수 있어요?","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"待つ → 待って + くれませんか"},{"w":"2그룹 동사","f":"開ける → 開けて + くれませんか"},{"w":"する","f":"掃除する → 掃除して + くれませんか"},{"w":"来る","f":"来る → 来て + くれませんか"}],"rule":["1. 동사를 て형으로 바꾼다(開ける→開けて).","2. くれる는 2그룹 동사라 어미 る를 떼고 ません을 붙여 부정 くれません이 된다.","3. 끝에 의문의 か를 붙여 ～てくれませんか로 만든다."],"why":"くれる(남이 나에게 주다)의 부정 의문. '~해 주지 않겠어요?'라고 물어 상대가 거절할 여지를 남긴 부탁이 된다.","nu":"ます를 써서 정중하지만 くれる 자체는 친근한 말이라 동료·친구·아랫사람에게 알맞다. 윗사람·손님에게는 ～てくださいませんか / ～ていただけませんか. 반말은 ～てくれない?","cmp":[{"g":"～ていただけませんか","d":"더 정중한 겸양 표현. 윗사람·손님에게."},{"g":"～てください","d":"정중한 지시·의뢰. 상대에게 묻지 않아 더 직접적이다."}],"ex":[{"jp":"ちょっとドアを開[あ]けてくれませんか。","ko":"잠깐 문 좀 열어 주지 않을래요?"},{"jp":"この漢字[かんじ]の読[よ]み方[かた]を教[おし]えてくれませんか。","ko":"이 한자 읽는 법을 가르쳐 줄래요?"},{"jp":"明日[あした]、駅[えき]まで迎[むか]えに来[き]てくれませんか。","ko":"내일 역까지 마중 나와 주지 않을래요?"}],"dr":[{"t":"make","q":"待つ → ～てくれませんか","a":"待ってくれませんか","hint":"つ → って + くれませんか"},{"t":"make","q":"手伝う → ～てくれませんか","a":"手伝ってくれませんか","hint":"う → って + くれませんか"},{"t":"fill","q":"すみません、写真[しゃしん]を撮[と]って（　）。","a":"くれませんか","opts":["くれませんか","あげませんか","いませんか","しまいませんか"]}],"src":["https://bunpro.jp/grammar_points/103","https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%8F%E3%82%8C%E3%82%8B"],"vf":1,"u":7,"g":1,"gp":"gg_N4_04"},{"id":"g4_042","t":"～てくれる","ko":"(남이 나에게) ~해 주다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"手伝う → 手伝って + くれる"},{"w":"2그룹 동사","f":"答える → 答えて + くれる"},{"w":"する","f":"掃除する → 掃除して + くれる"},{"w":"来る","f":"来る → 来て + くれる"}],"rule":["1. 동사를 て형으로 바꾼다. する는 して(掃除する→掃除して).","2. て형 뒤에 くれる를 붙인다. 해 주는 사람이 주어(が・は), 받는 사람은 나 또는 우리 쪽.","3. くれる는 2그룹 동사라 くれます, くれた, くれない로 활용한다."],"why":"くれる(呉れる)는 남이 말하는 사람 쪽에 무언가를 주는 동사. 행동을 주는 것으로 확장되어 '나를 위해 ~해 주다'가 된다.","nu":"회화·정중체 모두 사용. 받는 쪽은 반드시 나 또는 내 가족·우리 편이다. 내가 남에게 해 주는 것은 ～てあげる. 한국어 '~해 주다'는 방향을 가리지 않아 '私が友だちに手伝ってくれた' 같은 실수가 잦다. 윗사람이 해 준 경우는 ～てくださる. 고마운 마음이 담긴다.","cmp":[{"g":"～てあげる","d":"내가(또는 우리 쪽이) 남에게 해 주다. ～てくれる는 남이 나에게."},{"g":"～てもらう","d":"받는 사람이 주어이고 해 준 사람은 に(友だちに手伝ってもらった)."}],"ex":[{"jp":"友[とも]だちが宿題[しゅくだい]を手伝[てつだ]ってくれました。","ko":"친구가 숙제를 도와줬어요."},{"jp":"弟[おとうと]が部屋[へや]を掃除[そうじ]してくれた。","ko":"남동생이 방을 청소해 줬다."},{"jp":"母[はは]が駅[えき]まで迎[むか]えに来[き]てくれました。","ko":"엄마가 역까지 마중 나와 줬어요."}],"dr":[{"t":"make","q":"教える → ～てくれた","a":"教えてくれた","hint":"る를 떼고 て + くれた"},{"t":"make","q":"貸す → ～てくれました","a":"貸してくれました","hint":"す → して + くれました"},{"t":"fill","q":"田中[たなか]さんが私[わたし]に傘[かさ]を貸[か]して（　）。","a":"くれました","opts":["くれました","あげました","もらいました","いただきました"]}],"src":["https://bunpro.jp/grammar_points/103","https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%8F%E3%82%8C%E3%82%8B"],"vf":1,"u":7,"g":1,"gp":"gg_N4_05"},{"id":"g4_043","t":"～てさしあげる","ko":"~해 드리다 (겸양)","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"持つ → 持って + さしあげる"},{"w":"1그룹 동사(む·ぶ·ぬ)","f":"運ぶ → 運んで + さしあげる"},{"w":"2그룹 동사","f":"見せる → 見せて + さしあげる"},{"w":"する 동사","f":"案内する → 案内して + さしあげる"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 つ·う·る는 って(持つ→持って), む·ぶ·ぬ는 んで(運ぶ→運んで), 2그룹은 る를 떼고 て(見せる→見せて), する→して.","2. て형 뒤에 あげる의 겸양어 さしあげる(差し上げる)를 붙인다: 持って + さしあげる.","3. 정중체는 さしあげます, 과거는 さしあげました. さしあげる는 2그룹 동사처럼 활용한다."],"why":"さしあげる(差し上げる)는 あげる(주다)의 겸양어다. て형 + あげる가 '행동을 주다', 즉 '~해 주다'이므로, 그 겸양 버전인 て형 + さしあげる는 '~해 드리다'가 된다.","nu":"문법적으로 맞는 겸양 표현이지만 실제 회화에서는 드물다. '내가 해 주는' 은혜를 강조하는 말이라 윗사람 본인에게 직접 '持ってさしあげましょうか'라고 하면 생색내는 것처럼 들려 오히려 실례가 될 수 있다. 윗사람에게 도움을 제안할 때는 お持ちしましょうか(お+ます형+する)를 쓴다. 제3자에게 있었던 일을 보고하는 문장에서 주로 쓴다. 한국어 '해 드릴까요?'를 그대로 옮기는 실수에 주의. 자기 가족(내 편)에게는 쓰지 않는다.","cmp":[{"g":"～てあげる","d":"같은 '~해 주다'의 보통 표현. 동등하거나 손아래에게 쓰며, 윗사람에게는 역시 생색으로 들릴 수 있다."},{"g":"お～する","d":"윗사람에게 직접 도움을 제안할 때 자연스러운 겸양 표현(お持ちします, お手伝いします)."}],"ex":[{"jp":"先生[せんせい]の荷物[にもつ]を研究室[けんきゅうしつ]まで運[はこ]んでさしあげました。","ko":"선생님 짐을 연구실까지 옮겨 드렸습니다."},{"jp":"お客様[きゃくさま]に駅[えき]までの道[みち]を案内[あんない]してさしあげました。","ko":"손님께 역까지 가는 길을 안내해 드렸습니다."},{"jp":"お客様[きゃくさま]に新[あたら]しい商品[しょうひん]を見[み]せてさしあげた。","ko":"손님께 새 상품을 보여 드렸다."}],"dr":[{"t":"make","q":"持つ → ～てさしあげる","a":"持ってさしあげる","hint":"つ는 って로 바꾸고 さしあげる를 붙인다."},{"t":"make","q":"見せる → ～てさしあげました","a":"見せてさしあげました","hint":"2그룹: る를 떼고 て, 정중 과거는 さしあげました."},{"t":"fill","q":"私[わたし]は道[みち]に迷[まよ]ったお客様[きゃくさま]に地図[ちず]を書[か]いて（　）。","a":"さしあげました","opts":["さしあげました","くださいました","みませんか","いただけませんか"]}],"src":["https://elon.io/grammar/japanese/verbs/giving-keigo-sashiageru-kudasaru-itadaku","https://www.japanesepod101.com/lesson/intermediate-questions-answered-by-hiroko-8-can-you-use-sashiageru-as-an-auxiliary-verb"],"vf":1,"u":7,"g":1,"gp":"gg_N4_05"},{"id":"g4_047","t":"～てもらいたい","ko":"(남이) ~해 주었으면 한다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"運ぶ → 運んで + もらいたい"},{"w":"2그룹 동사","f":"教える → 教えて + もらいたい"},{"w":"する 동사","f":"説明する → 説明して + もらいたい"},{"w":"来る","f":"来る → 来て(きて) + もらいたい"}],"rule":["1. 동사를 て형으로 바꾼다(教える→教えて).","2. て형 뒤에 もらう를 붙인다: 教えて + もらう.","3. もらう를 ます형 어간으로: 어미 う를 い로 바꿔 もらい.","4. 희망의 たい를 붙인다: 教えてもらいたい. 해 줄 사람은 に로 나타낸다."],"why":"て형 + もらう(받다) + たい(희망). '그 행동을 받고 싶다'는 구조라 남이 해 주기를 바라는 뜻이 된다.","nu":"～てほしい와 뜻이 거의 같지만 '받는다'는 고마움이 담겨 조금 부드럽다. 그래도 아주 높은 윗사람에게는 ～ていただきたい를 쓴다. 정중하게는 ～てもらいたいです, 부탁 투로 ～てもらいたいんですが. 자기 행동의 희망은 그냥 ～たい.","cmp":[{"g":"～てほしい","d":"같은 뜻이지만 더 직접적."},{"g":"～ていただきたい","d":"いただく(もらう의 겸양어)를 쓴 더 높은 표현. 윗사람에게."}],"ex":[{"jp":"友達[ともだち]に日本語[にほんご]を教[おし]えてもらいたい。","ko":"친구가 일본어를 가르쳐 줬으면 좋겠다."},{"jp":"この荷物[にもつ]を二階[にかい]まで運[はこ]んでもらいたいんですが。","ko":"이 짐을 2층까지 옮겨 줬으면 하는데요."},{"jp":"もう一度[いちど]説明[せつめい]してもらいたいです。","ko":"한 번 더 설명해 줬으면 해요."}],"dr":[{"t":"make","q":"書く → ～てもらいたい","a":"書いてもらいたい","hint":"く는 いて, もらう→もらい + たい."},{"t":"make","q":"来る → ～てもらいたい","a":"来てもらいたい","hint":"来る의 て형은 来て(きて)."},{"t":"fill","q":"父[ちち]に駅[えき]まで迎[むか]えに来[き]て（　）。","a":"もらいたい","opts":["もらいたい","あげたい","おきたい","しまいたい"]}],"src":["https://www.tofugu.com/japanese-grammar/tehoshii/","https://laits.utexas.edu/japanese/joshu/grammar/glist/y2/ch6/gl_y2_ch6_tehoshii.php"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_048","t":"～てもらう","ko":"(남이) ~해 주다 (내가 받다)","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"手伝う → 手伝って + もらう"},{"w":"1그룹 동사(む·ぶ·ぬ)","f":"読む → 読んで + もらう"},{"w":"2그룹 동사","f":"見せる → 見せて + もらう"},{"w":"する 동사","f":"掃除する → 掃除して + もらう"}],"rule":["1. 동사를 て형으로 바꾼다(手伝う→手伝って: う는 って).","2. て형 뒤에 もらう를 붙인다: 手伝って + もらう.","3. もらう는 1그룹 동사라 과거는 う를 った로 바꿔 もらった, 정중체는 もらいました.","4. 받는 사람(나)이 주어이고, 해 준 사람은 に로 나타낸다."],"why":"て형 + もらう(받다). '그 행동을 받는다'는 구조라 한국어로는 보통 '(누가) ~해 주었다'로 옮긴다.","nu":"주어는 혜택을 받는 사람이다. 한국어는 '친구가 도와줬다'처럼 말하므로 ～てくれる와 헷갈리기 쉽다: 友達に手伝ってもらった(내가 주어, 친구는 に) / 友達が手伝ってくれた(친구가 주어, が). 가게 등에서 서비스를 받을 때도 쓴다. 윗사람에게 받을 때는 ～ていただく.","cmp":[{"g":"～てくれる","d":"해 주는 사람이 주어(が)이고 나에게 해 줌. ～てもらう는 받는 내가 주어."},{"g":"～ていただく","d":"もらう의 겸양어를 쓴 높은 표현."}],"ex":[{"jp":"友達[ともだち]に引[ひ]っ越[こ]しを手伝[てつだ]ってもらった。","ko":"친구가 이사를 도와줬다."},{"jp":"母[はは]に部屋[へや]を掃除[そうじ]してもらいました。","ko":"엄마가 방을 청소해 줬어요."},{"jp":"姉[あね]に古[ふる]い写真[しゃしん]を見[み]せてもらった。","ko":"언니(누나)가 옛날 사진을 보여 줬다."}],"dr":[{"t":"make","q":"書く → ～てもらった","a":"書いてもらった","hint":"く는 いて, もらう의 과거는 もらった."},{"t":"make","q":"友達が手伝ってくれた → ～てもらった (주어: 私)","a":"友達に手伝ってもらった","hint":"받는 내가 주어, 친구는 が 대신 に."},{"t":"fill","q":"先輩[せんぱい]（　）レポートを見[み]てもらった。","a":"に","opts":["に","が","を","で"]}],"src":["https://bunpro.jp/grammar_points/てもらう"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_049","t":"～てもらえませんか","ko":"~해 주실 수 없을까요?","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"持つ → 持って + もらえませんか"},{"w":"2그룹 동사","f":"見る → 見て + もらえませんか"},{"w":"する 동사","f":"説明する → 説明して + もらえませんか"},{"w":"来る","f":"来る → 来て(きて) + もらえませんか"}],"rule":["1. 동사를 て형으로 바꾼다(見る→見て).","2. て형 뒤에 もらう를 붙인다: 見て + もらう.","3. もらう를 가능형으로: 어미 う를 え로 바꿔 もらえる(받을 수 있다).","4. もらえる의 る를 떼고 ませんか(정중 부정 의문)를 붙인다: 見てもらえませんか."],"why":"て형 + もらえる(もらう의 가능형) + ませんか. 직역하면 '~해 받을 수 없겠습니까?'로, 상대가 해 줄 수 있는지를 부정 의문으로 물어 부탁을 부드럽고 정중하게 만든다.","nu":"정중한 의뢰 표현으로 동료, 점원, 처음 보는 사람에게 무난하다. 긍정 의문 ～てもらえますか보다 부정 의문 ～てもらえませんか가 더 조심스럽다. 윗사람에게는 ～ていただけませんか가 더 알맞다. 친한 사이에는 ～てもらえる？/～てもらえない？. 해 주는 사람(상대)은 보통 생략한다.","cmp":[{"g":"～てくれませんか","d":"상대가 주어인 '~해 주지 않겠어요?'. 뜻은 비슷하고 ～てもらえませんか가 조금 더 공손하게 들린다."},{"g":"～ていただけませんか","d":"もらう의 겸양어 いただく를 쓴 더 높은 표현. 윗사람에게."}],"ex":[{"jp":"すみません、この作文[さくぶん]を見[み]てもらえませんか。","ko":"죄송한데, 이 작문 좀 봐 주실 수 있을까요?"},{"jp":"荷物[にもつ]が重[おも]いので、ちょっと持[も]ってもらえませんか。","ko":"짐이 무거워서 그런데, 좀 들어 주실 수 있을까요?"},{"jp":"もう少[すこ]しゆっくり話[はな]してもらえませんか。","ko":"조금 더 천천히 말해 주실 수 없을까요?"}],"dr":[{"t":"make","q":"待つ → ～てもらえませんか","a":"待ってもらえませんか","hint":"つ는 って, もらう→もらえ + ませんか."},{"t":"make","q":"説明する → ～てもらえませんか","a":"説明してもらえませんか","hint":"する는 して, 뒤에 もらえませんか."},{"t":"fill","q":"すみません、駅[えき]までの道[みち]を教[おし]えて（　）。","a":"もらえませんか","opts":["もらえませんか","あげませんか","しまいませんか","ほしがりませんか"]}],"src":["https://bunpro.jp/grammar_points/てもらう"],"vf":0,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_063","t":"～られる","ko":"~되다·~당하다(수동), ~할 수 있다(가능)","cat":"수수·사역·수동","conn":[{"w":"2그룹 동사","f":"褒める → 褒め + られる"},{"w":"1그룹 동사(수동)","f":"書く → 書か + れる"},{"w":"1그룹 동사(가능)","f":"書く → 書け + る"},{"w":"する","f":"する → される(수동) / できる(가능)"},{"w":"来る","f":"来る → 来[こ]られる"}],"rule":["1. 2그룹 동사는 끝의 る를 떼고 られる를 붙인다(褒める→褒められる). 이 형태는 수동과 가능 둘 다 된다.","2. 1그룹 동사의 수동형은 어미 う단을 あ단으로 바꾸고 れる를 붙인다(書く→書かれる). 어미가 う이면 わ가 된다(言う→言われる).","3. 1그룹 동사의 가능형은 られる가 아니라 어미를 え단으로 바꾸고 る를 붙인다(書く→書ける).","4. 불규칙: する→される(수동)·できる(가능), 来る→来(こ)られる(수동·가능 동일)."],"why":"수동·가능의 조동사 られる(1그룹은 れる)가 동사에 붙은 것이다. 만들어진 동사는 모두 2그룹 동사처럼 활용한다(褒められた, 褒められない).","nu":"수동: 행위를 한 사람은 に로 나타낸다(先生に褒められた). 남의 행동으로 피해를 입었다는 '피해 수동'(雨に降られた)도 있다. 가능: 2그룹 가능형에서 ら를 빼는 ら抜き(食べれる)는 회화에서 흔하지만 비표준이라 시험·글에서는 られる를 쓴다. 문맥으로 수동인지 가능인지 판단해야 한다. 1그룹 가능형을 ×書かれる로 만드는 실수 주의.","cmp":[{"g":"～ことができる","d":"가능의 의미만 있고 더 딱딱하다. 동사를 바꾸지 않고 사전형에 붙인다."},{"g":"～させる(사역)","d":"남에게 ~하게 시키다. ～られる는 남에게 ~당하다."}],"ex":[{"jp":"テストで百点[ひゃくてん]を取[と]って、先生[せんせい]に褒[ほ]められた。","ko":"시험에서 100점을 받아서 선생님께 칭찬받았다."},{"jp":"電車[でんしゃ]で隣[となり]の人[ひと]に足[あし]を踏[ふ]まれました。","ko":"전철에서 옆 사람에게 발을 밟혔어요."},{"jp":"この店[みせ]では朝[あさ]七時[しちじ]から朝[あさ]ご飯[はん]が食[た]べられる。","ko":"이 가게에서는 아침 7시부터 아침밥을 먹을 수 있다."}],"dr":[{"t":"make","q":"見る → 수동형","a":"見られる","hint":"2그룹: る → られる"},{"t":"make","q":"呼ぶ → 수동형","a":"呼ばれる","hint":"1그룹: ぶ → ば (あ단) + れる"},{"t":"fill","q":"子[こ]どものとき、よく母[はは]に（　）。","a":"しかられた","opts":["しかられた","しからせた","しかってあげた","しかろう"]}],"src":["https://guidetojapanese.org/learn/grammar/causepass","https://guidetojapanese.org/learn/grammar/potential"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_080","t":"～させてください","ko":"~하게 해 주세요 (허락 요청)","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"撮る → 撮らせて + ください"},{"w":"2그룹 동사","f":"考える → 考えさせて + ください"},{"w":"する","f":"する → させて + ください"},{"w":"来る","f":"来る → 来(こ)させて + ください"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 せる를 붙여 사역형을 만든다(撮る→撮らせる). う로 끝나면 わ가 된다(言う→言わせる).","2. 2그룹 동사는 る를 떼고 させる를 붙인다(考える→考えさせる).","3. する는 させる, 来る는 来(こ)させる가 된다.","4. 사역형의 마지막 る를 떼고 て를 붙인 뒤(撮らせて), ください를 붙인다."],"why":"사역형 て형 + ください로, 직역하면 '(나에게) ~하게 시켜 주세요'이다. 즉 상대에게 내가 그 행동을 하도록 허락해 달라고 부탁하는 표현이 된다.","nu":"행동하는 사람은 말하는 나 자신이다(私に撮らせてください). 상대의 허락이 필요한 일에 쓰며 정중한 부탁이다. 더 공손하게는 ～させていただけませんか. 한국어 '~하게 해 주세요'를 직역해 ～してください로 말하면 상대에게 그 행동을 시키는 뜻이 되므로 주의.","cmp":[{"g":"～てください","d":"상대가 그 행동을 하도록 부탁한다. ～させてください는 내가 하는 것을 허락해 달라는 부탁."},{"g":"～てもいいですか","d":"허락 여부를 묻는 의문문. ～させてください는 허락을 청하는 부탁문이라 의지가 더 강하다."}],"ex":[{"jp":"すみません、写真[しゃしん]を撮[と]らせてください。","ko":"실례합니다, 사진을 찍게 해 주세요."},{"jp":"その仕事[しごと]、私[わたし]にやらせてください。","ko":"그 일, 제가 하게 해 주세요."},{"jp":"少[すこ]し考[かんが]えさせてください。","ko":"조금 생각하게 해 주세요."}],"dr":[{"t":"make","q":"帰る → ～させてください","a":"帰らせてください","hint":"1그룹: る(う단)를 ら(あ단)로 바꾸고 せて+ください."},{"t":"make","q":"休む → ～させてください","a":"休ませてください","hint":"1그룹: む를 ま로 바꾸고 せて+ください."},{"t":"fill","q":"熱[ねつ]があるので、今日[きょう]は早[はや]く帰[かえ]ら（　）。","a":"せてください","opts":["せてください","れてください","ないでください","なくてもいい"]}],"src":["https://cotoacademy.com/sasete-kusasai-jlpt-grammar-explanation-meaning-example/"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_065","t":"～ことができる","ko":"~할 수 있다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"泳ぐ + ことができる"},{"w":"する동사","f":"予約する + ことができる"},{"w":"명사","f":"日本語 + ができる"}],"rule":["1. 동사는 사전형 그대로 둔다(泳ぐ). 활용 어미는 바뀌지 않는다.","2. 그 뒤에 명사 こと를 붙여 동작을 명사로 만든다.","3. 조사 が와 できる를 붙인다(泳ぐことができる). 정중하게는 ことができます, 부정은 ことができない.","4. 명사는 こと 없이 바로 ができる를 붙인다(日本語ができる)."],"why":"こと로 동사구를 명사처럼 만들고, できる(할 수 있다)의 대상으로 삼은 형태다. 그래서 '~하는 것을 할 수 있다'가 된다.","nu":"가능형(泳げる)과 뜻은 같지만 더 딱딱하고 글이나 안내문에 많이 쓴다(ここでたばこを吸うことはできません). 능력뿐 아니라 규칙·상황상 가능함도 나타낸다. 가능형과 겹쳐 ×泳げることができる로 쓰지 않는다. 조사는 が(강조·대비는 は, も).","cmp":[{"g":"가능형(～える／～られる)","d":"泳げる, 食べられる처럼 짧고 회화적. ～ことができる는 더 격식 있고 설명적."},{"g":"～ことがある","d":"'~할 때가 있다'(빈도). 능력이 아니다."}],"ex":[{"jp":"私[わたし]は百[ひゃく]メートル泳[およ]ぐことができます。","ko":"저는 100미터 헤엄칠 수 있어요."},{"jp":"このホテルはネットで予約[よやく]することができる。","ko":"이 호텔은 인터넷으로 예약할 수 있다."},{"jp":"図書館[としょかん]では、本[ほん]を二週間[にしゅうかん]借[か]りることができます。","ko":"도서관에서는 책을 2주 동안 빌릴 수 있습니다."}],"dr":[{"t":"make","q":"弾く → ～ことができる","a":"弾くことができる","hint":"사전형 그대로 + こと + が + できる"},{"t":"make","q":"来る → ～ことができない","a":"来ることができない","hint":"사전형 来る + ことができない"},{"t":"fill","q":"この部屋[へや]では写真[しゃしん]を撮[と]る（　）できません。","a":"ことは","opts":["ことは","ためには","のには","ながら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%93%E3%81%A8%E3%81%8C%E3%81%A7%E3%81%8D%E3%82%8B","https://guidetojapanese.org/learn/grammar/potential"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_095","t":"～てはいけない","ko":"~해서는 안 된다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"撮る → 撮って + はいけない"},{"w":"2그룹 동사","f":"食べる → 食べて + はいけない"},{"w":"する / 来る","f":"して / 来て + はいけない"},{"w":"い형용사","f":"小さい → 小さくて + はいけない"},{"w":"な형용사·명사","f":"子ども + では + いけない"}],"rule":["1. 동사를 て형으로 바꾼다: 1그룹 る·う·つ→って, む·ぶ·ぬ→んで, く→いて, ぐ→いで, す→して(撮る→撮って).","2. 2그룹은 る를 て로(食べる→食べて), する→して, 来る→来て.","3. て형 뒤에 は와 いけない를 붙인다(撮って+は+いけない).","4. で로 끝나는 て형은 では가 된다(飲んで→飲んではいけない)."],"why":"'~해서는(ては) 좋지 않다/안 된다(いけない)'라는 짜임이다. いけない는 行く의 가능 부정형 行けない에서 나온 말로 '안 된다'는 뜻으로 굳어졌다.","nu":"규칙·금지를 분명히 말하는 강한 표현이라 윗사람에게 직접 쓰면 실례다. 정중형은 てはいけません. 회화에서는 ちゃいけない / じゃいけない(飲んじゃいけない)로 준다. 같은 뜻으로 てはだめ / てはならない(문어)도 있다.","cmp":[{"g":"～てもいい","d":"반대로 허가. 질문 てもいいですか에 대한 거절로 てはいけません을 쓴다."},{"g":"～ないでください","d":"상대에게 하지 말라고 부탁하는 표현으로 규칙을 말하는 てはいけない보다 부드럽다."}],"ex":[{"jp":"ここで写真[しゃしん]を撮[と]ってはいけません。","ko":"여기서 사진을 찍으면 안 됩니다."},{"jp":"図書館[としょかん]で大[おお]きい声[こえ]で話[はな]してはいけない。","ko":"도서관에서 큰 소리로 말해서는 안 된다."},{"jp":"お酒[さけ]を飲[の]んで運転[うんてん]してはいけない。","ko":"술을 마시고 운전해서는 안 된다."}],"dr":[{"t":"make","q":"入る → ～てはいけない","a":"入ってはいけない","hint":"1그룹 る → って, 그 뒤에 はいけない."},{"t":"make","q":"泳ぐ → ～てはいけない","a":"泳いではいけない","hint":"ぐ → いで, 그 뒤에 はいけない."},{"t":"fill","q":"この池[いけ]で泳[およ]いで（　）。危[あぶ]ないですよ。","a":"はいけません","opts":["はいけません","もいいです","みます","おきます"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%81%AF%E3%81%84%E3%81%91%E3%81%AA%E3%81%84"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_096","t":"～てもいい","ko":"~해도 된다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"座る → 座って + もいい"},{"w":"2그룹 동사","f":"食べる → 食べて + もいい"},{"w":"する / 来る","f":"して / 来て + もいい"},{"w":"い형용사","f":"高い → 高くて + もいい"},{"w":"な형용사·명사","f":"明日 + でも + いい"}],"rule":["1. 동사를 て형으로 바꾼다(食べる→食べて, 撮る→撮って, 書く→書いて).","2. て형 뒤에 も와 いい를 붙인다(食べて+も+いい).","3. で로 끝나는 て형은 でも가 된다(読んで→読んでもいい). 명사·な형용사는 でもいい, い형용사는 くてもいい."],"why":"'~해도(ても) 좋다(いい)'라는 짜임으로, 역접 ても에 いい가 이어진 것이다.","nu":"허가를 구할 때 てもいいですか, 더 공손히 てもよろしいですか / てもかまいませんか. 대답은 はい、どうぞ나 すみません、ちょっと…가 자연스럽고, はい、てもいいです는 윗사람에게 거만하게 들린다. 회화에서는 食べていい처럼 も를 빼기도 한다.","cmp":[{"g":"～てはいけない","d":"반대 뜻인 금지."},{"g":"～なくてもいい","d":"'~하지 않아도 된다'로 필요 없음을 나타낸다."}],"ex":[{"jp":"このケーキ、食[た]べてもいい？","ko":"이 케이크 먹어도 돼?"},{"jp":"ここに座[すわ]ってもいいですか。","ko":"여기 앉아도 될까요?"},{"jp":"少[すこ]し高[たか]くてもいいから、いい靴[くつ]がほしい。","ko":"좀 비싸도 괜찮으니까 좋은 신발을 갖고 싶다."}],"dr":[{"t":"make","q":"帰る → ～てもいい","a":"帰ってもいい","hint":"1그룹 る → って, 그 뒤에 もいい."},{"t":"make","q":"読む → ～てもいい","a":"読んでもいい","hint":"む → んで, で 뒤에는 もいい."},{"t":"fill","q":"テストが終[お]わった人[ひと]は帰[かえ]って（　）。","a":"もいいです","opts":["もいいです","はいけません","しまいます","あります"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%82%82%E3%81%84%E3%81%84"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_103","t":"～ないといけない","ko":"~해야 한다, ~하지 않으면 안 된다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"行く → 行かない + といけない"},{"w":"2그룹 동사","f":"起きる → 起きない + といけない"},{"w":"する / 来る","f":"しない / 来[こ]ない + といけない"},{"w":"い형용사","f":"安い → 安くない + といけない"},{"w":"な형용사·명사","f":"静かで / 学生で + ないといけない"}],"rule":["1. 1그룹 동사는 사전형 어미 う단을 あ단으로 바꾸고 ない를 붙인다(行く→行かない). 단 う로 끝나면 わ로 바꾼다(買う→買わない).","2. 2그룹 동사는 る를 떼고 ない를 붙인다(起きる→起きない). する→しない, 来る→来ない.","3. ない형 뒤에 조건 조사 と와 いけない(안 된다)를 붙인다(行かない＋と＋いけない).","4. 정중하게는 ないといけません."],"why":"'~하지 않으면(ないと) 안 된다(いけない)'는 이중 부정으로 '반드시 해야 한다'는 의무를 나타낸다. と는 '~하면'의 조건 조사, いけない는 行ける(갈 수 있다)의 부정에서 '좋지 않다, 안 된다'의 뜻으로 굳은 말이다.","nu":"회화에서 아주 많이 쓰는 구어적인 의무 표현이다. 다만 말투가 가볍다고 의무가 약한 것은 아니며, 법·관습·상식처럼 꼭 지켜야 하는 일에도 자주 쓴다. 친한 사이에서는 いけない를 생략해 「もう行かないと。」(이제 가야지)처럼 끝내기도 한다. 한국어 '~해야 한다'를 그대로 옮겨 ×行くといけない로 쓰지 않도록 주의(이것은 '가면 안 된다'는 반대 뜻).","cmp":[{"g":"～なければならない","d":"문어적·격식적이고 규칙이나 공식 문서에 잘 어울린다. ないといけない는 회화체."},{"g":"～なくてもいい","d":"반대로 '~하지 않아도 된다'(의무 없음)."}],"ex":[{"jp":"明日[あした]テストがあるから、今夜[こんや]勉強[べんきょう]しないといけない。","ko":"내일 시험이 있어서 오늘 밤 공부해야 해."},{"jp":"もう9時[くじ]だ。学校[がっこう]に行[い]かないといけない。","ko":"벌써 9시다. 학교에 가야 해."},{"jp":"この部屋[へや]はもっと広[ひろ]くないといけません。","ko":"이 방은 더 넓어야 합니다."}],"dr":[{"t":"make","q":"書く → ～ないといけない","a":"書かないといけない","hint":"く를 か로 바꿔 ない형을 만든 뒤 といけない."},{"t":"make","q":"寝る → ～ないといけない","a":"寝ないといけない","hint":"2그룹은 る를 떼고 ない + といけない."},{"t":"fill","q":"薬[くすり]を飲[の]ま（　）いけない。","a":"ないと","opts":["ないと","ないで","なくても","ないのに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%84%E3%81%A8"],"vf":1,"u":8,"g":1,"gp":"gg_N4_05"},{"id":"g4_104","t":"～なきゃいけない","ko":"~해야 해 (회화 축약)","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"帰る → 帰らない → 帰らなきゃいけない"},{"w":"2그룹 동사","f":"食べる → 食べなきゃいけない"},{"w":"する / 来る","f":"しなきゃ / 来[こ]なきゃ + いけない"},{"w":"い형용사","f":"安い → 安くなきゃいけない"},{"w":"な형용사·명사","f":"静かじゃ / 学生じゃ + なきゃいけない"}],"rule":["1. 먼저 ない형을 만든다(帰る→帰らない, 食べる→食べない).","2. ない의 가정형 なければ를 만든다(帰らなければ).","3. 회화에서는 なければ를 なきゃ로 줄여 말한다(帰らなきゃ).","4. 뒤에 いけない를 붙인다(帰らなきゃいけない). ならない를 붙여도 된다."],"why":"なきゃ는 なければ의 축약형이다. 따라서 なきゃいけない는 なければいけない(~하지 않으면 안 된다)를 줄인 회화체 표현이다.","nu":"친구·가족 사이의 회화체. 글이나 윗사람 앞의 정중한 자리에서는 なければなりません/なければいけません을 쓴다. 뒤를 생략한 「もう帰らなきゃ。」(이제 가야지)도 아주 흔하다. ×帰るなきゃ처럼 사전형에 붙이는 실수에 주의.","cmp":[{"g":"～なくちゃいけない","d":"なくては의 축약. 뜻은 거의 같고 둘 다 회화체이며, 쓰는 사람의 습관 차이 정도이다."},{"g":"～なければならない","d":"줄이지 않은 형태로 문어적·격식적."}],"ex":[{"jp":"もう遅[おそ]いから、帰[かえ]らなきゃいけない。","ko":"벌써 늦었으니까 집에 가야 해."},{"jp":"明日[あした]までに宿題[しゅくだい]をしなきゃ。","ko":"내일까지 숙제를 해야 해."},{"jp":"野菜[やさい]も食[た]べなきゃいけないよ。","ko":"채소도 먹어야 해."}],"dr":[{"t":"make","q":"待つ → ～なきゃいけない","a":"待たなきゃいけない","hint":"つ를 た로 바꾼 ない형 → なければ → なきゃ."},{"t":"make","q":"来る → ～なきゃいけない","a":"来なきゃいけない","hint":"来る의 ない형은 来[こ]ない."},{"t":"fill","q":"電車[でんしゃ]に遅[おく]れるから、急[いそ]が（　）いけない。","a":"なきゃ","opts":["なきゃ","なくても","ないで","なかった"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%8F%E3%81%A1%E3%82%83-%E3%81%AA%E3%81%8D%E3%82%83?deck_id=2","https://jlptsensei.com/learn-japanese-grammar/なければいけない-nakereba-ikenai-meaning"],"vf":1,"u":9,"g":1,"gp":"gg_N4_05"},{"id":"g4_105","t":"～なくちゃいけない","ko":"~해야 해 (회화 축약)","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"行く → 行かなくちゃいけない"},{"w":"2그룹 동사","f":"起きる → 起きなくちゃいけない"},{"w":"する / 来る","f":"しなくちゃ / 来[こ]なくちゃ + いけない"},{"w":"い형용사","f":"安い → 安くなくちゃいけない"},{"w":"な형용사·명사","f":"静かじゃ / 学生じゃ + なくちゃいけない"}],"rule":["1. ない형을 만든다(起きる→起きない, 行く→行かない).","2. ない의 い를 く로 바꾸고 て를 붙여 なくて, 이어서 は를 붙인다(起きなくては).","3. 회화에서는 ては를 ちゃ로 줄여 なくちゃ가 된다(起きなくちゃ).","4. 뒤에 いけない를 붙인다(起きなくちゃいけない)."],"why":"ては가 회화에서 ちゃ로 줄어드는 현상(食べては→食べちゃ)과 같은 원리로, なくては가 なくちゃ로 바뀐 것이다. 따라서 なくちゃいけない = なくてはいけない의 회화체.","nu":"친한 사이의 회화체. 「起きなくちゃ。」처럼 뒤를 생략하는 일이 많다. 정중한 자리나 글에서는 なくてはいけません/なければなりません을 쓴다. なきゃ와 의미 차이는 거의 없다.","cmp":[{"g":"～なきゃいけない","d":"なければ의 축약. 뜻은 같고 둘 다 회화체."},{"g":"～なくてはいけない","d":"줄이지 않은 형태로 조금 더 단정한 말투."}],"ex":[{"jp":"7時[しちじ]だ。起[お]きなくちゃいけない。","ko":"7시다. 일어나야 해."},{"jp":"今日[きょう]は早[はや]く帰[かえ]らなくちゃ。","ko":"오늘은 일찍 집에 가야 해."},{"jp":"部屋[へや]をきれいにしなくちゃいけない。","ko":"방을 깨끗하게 해야 해."}],"dr":[{"t":"make","q":"洗う → ～なくちゃいけない","a":"洗わなくちゃいけない","hint":"う로 끝나는 1그룹은 わ로: 洗わない → なくては → なくちゃ."},{"t":"make","q":"見る → ～なくちゃいけない","a":"見なくちゃいけない","hint":"2그룹은 る를 떼고 なくちゃ."},{"t":"fill","q":"明日[あした]は試験[しけん]だから、勉強[べんきょう]し（　）いけない。","a":"なくちゃ","opts":["なくちゃ","なくても","ないで","たら"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%8F%E3%81%A1%E3%82%83-%E3%81%AA%E3%81%8D%E3%82%83?deck_id=2","https://jlptsensei.com/learn-japanese-grammar/なくちゃ-ダメ-nakucha-dame-meaning/"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_106","t":"～なくてはいけない","ko":"~하지 않으면 안 된다, ~해야 한다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"出す → 出さなくてはいけない"},{"w":"2그룹 동사","f":"食べる → 食べなくてはいけない"},{"w":"する / 来る","f":"しなくては / 来[こ]なくては + いけない"},{"w":"い형용사","f":"安い → 安くなくてはいけない"},{"w":"な형용사·명사","f":"静かで / 学生で + なくてはいけない"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 ない를 붙인다(出す→出さない). 2그룹은 る를 떼고 ない.","2. ない의 い를 く로 바꾸고 て를 붙인다(出さない→出さなくて).","3. 조사 は와 いけない를 붙인다(出さなくてはいけない).","4. 정중하게는 なくてはいけません. いけない 대신 ならない도 쓸 수 있다."],"why":"なくて(~하지 않고)＋は(~하면, 조건)＋いけない(안 된다)로, '~하지 않으면 안 된다'는 이중 부정이 의무를 나타낸다.","nu":"일상 회화와 글 모두에 쓸 수 있는 중립적인 말투. 회화에서는 なくちゃ로 줄이기도 한다. 〈ては＋いけない〉(~해서는 안 된다, 금지)와 헷갈리기 쉬우니 앞이 なくて(부정)인지 꼭 확인할 것.","cmp":[{"g":"～てはいけない","d":"금지(~해서는 안 된다). なくてはいけない는 의무(~해야 한다)."},{"g":"～なければならない","d":"뜻은 같지만 더 딱딱하고 문어적."}],"ex":[{"jp":"この手紙[てがみ]を今日[きょう]出[だ]さなくてはいけない。","ko":"이 편지를 오늘 부쳐야 한다."},{"jp":"図書館[としょかん]では静[しず]かでなくてはいけません。","ko":"도서관에서는 조용히 해야 합니다."},{"jp":"毎朝[まいあさ]犬[いぬ]の散歩[さんぽ]をしなくてはいけない。","ko":"매일 아침 개 산책을 시켜야 한다."}],"dr":[{"t":"make","q":"払う → ～なくてはいけない","a":"払わなくてはいけない","hint":"う→わ로 ない형, い→く+て, は+いけない."},{"t":"make","q":"覚える → ～なくてはいけない","a":"覚えなくてはいけない","hint":"2그룹: る를 떼고 なくてはいけない."},{"t":"fill","q":"パスポートを持[も]って行[い]か（　）いけない。","a":"なくては","opts":["なくては","ては","なくても","ないで"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%8F%E3%81%A6%E3%81%AF%E3%81%84%E3%81%91%E3%81%AA%E3%81%84"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_107","t":"～なくてもいい","ko":"~하지 않아도 된다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"急ぐ → 急がなくてもいい"},{"w":"2그룹 동사","f":"食べる → 食べなくてもいい"},{"w":"する / 来る","f":"しなくても / 来[こ]なくても + いい"},{"w":"い형용사","f":"高い → 高くなくてもいい"},{"w":"な형용사·명사","f":"上手で / 新品で + なくてもいい"}],"rule":["1. ない형을 만든다(急ぐ→急がない, 食べる→食べない).","2. ない의 い를 く로 바꾸고 て를 붙인다(急がなくて).","3. も와 いい를 붙인다(急がなくてもいい).","4. 정중하게는 なくてもいいです. いい 대신 かまわない도 쓴다."],"why":"てもいい(~해도 된다, 허가)를 부정형 なくて에 붙인 것으로, '~하지 않아도 괜찮다' 즉 의무가 없음을 나타낸다.","nu":"なければならない/なくてはいけない의 반대 개념(불필요). 회화에서는 なくていい(も 생략)도 흔하다. '~하면 안 된다(금지)'가 아니라 '안 해도 된다(선택)'라는 점에 주의. 정중한 자리에서는 なくてもかまいません.","cmp":[{"g":"～てもいい","d":"긍정형에 붙어 '~해도 된다'(허가)."},{"g":"～ないでください","d":"'~하지 마세요'(금지 요청). なくてもいい는 하지 않아도 괜찮다는 뜻일 뿐 하지 말라는 것이 아니다."}],"ex":[{"jp":"時間[じかん]はあるから、急[いそ]がなくてもいいよ。","ko":"시간 있으니까 서두르지 않아도 돼."},{"jp":"明日[あした]は来[こ]なくてもいいです。","ko":"내일은 오지 않아도 됩니다."},{"jp":"部屋[へや]はあまり広[ひろ]くなくてもいい。","ko":"방은 그다지 넓지 않아도 돼."}],"dr":[{"t":"make","q":"書く → ～なくてもいい","a":"書かなくてもいい","hint":"書かない → い를 く로 + て + もいい."},{"t":"make","q":"する → ～なくてもいい","a":"しなくてもいい","hint":"する의 ない형은 しない."},{"t":"fill","q":"お金[かね]は払[はら]わ（　）いいですよ。","a":"なくても","opts":["なくても","なくては","ないと","なければ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%8F%E3%81%A6%E3%82%82%E3%81%84%E3%81%84","https://www.jpf.go.jp/j/urawa/j_rsorcs/textbook/setsumei_pdf/setsumei14_3.pdf"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_108","t":"～なければならない","ko":"~하지 않으면 안 된다, ~해야 한다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"飲む → 飲まなければならない"},{"w":"2그룹 동사","f":"起きる → 起きなければならない"},{"w":"する / 来る","f":"しなければ / 来[こ]なければ + ならない"},{"w":"い형용사","f":"安い → 安くなければならない"},{"w":"な형용사·명사","f":"静かで / 学生で + なければならない"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 ない를 붙인다(飲む→飲まない). 2그룹은 る를 떼고 ない.","2. ない의 い를 けれ로 바꾸고 ば를 붙여 가정형 なければ를 만든다(飲まなければ).","3. 뒤에 ならない를 붙인다(飲まなければならない).","4. 정중하게는 なければなりません."],"why":"なければ(~하지 않으면)는 ない의 가정형(い형용사와 같은 활용: ない→なければ), ならない는 なる의 부정으로 '안 된다, 허용되지 않는다'는 뜻이다. 이중 부정으로 의무를 나타낸다.","nu":"가장 격식적이고 문어적인 의무 표현으로 규칙·법·사회적 의무에 잘 어울린다. 회화에서는 なきゃ(いけない)·ないと(いけない)로 줄이는 일이 많다. ×飲むなければ처럼 사전형에 붙이는 실수에 주의.","cmp":[{"g":"～なくてはいけない","d":"뜻은 같지만 조금 덜 딱딱하고 개인적 사정에 자주 쓴다."},{"g":"～なきゃ","d":"なければ의 회화 축약형."}],"ex":[{"jp":"毎日[まいにち]この薬[くすり]を飲[の]まなければならない。","ko":"매일 이 약을 먹어야 한다."},{"jp":"会議[かいぎ]には社長[しゃちょう]も来[こ]なければなりません。","ko":"회의에는 사장님도 오셔야 합니다."},{"jp":"運転手[うんてんしゅ]は目[め]がよくなければならない。","ko":"운전기사는 눈이 좋아야 한다."}],"dr":[{"t":"make","q":"読む → ～なければならない","a":"読まなければならない","hint":"む를 ま로 바꿔 ない형 → い를 けれ로 + ば + ならない."},{"t":"make","q":"勉強する → ～なければならない","a":"勉強しなければならない","hint":"する → しない → しなければ."},{"t":"fill","q":"レポートは金曜日[きんようび]までに出[だ]さ（　）ならない。","a":"なければ","opts":["なければ","なくても","ないで","なかったら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%91%E3%82%8C%E3%81%B0%E3%81%AA%E3%82%89%E3%81%AA%E3%81%84"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_011","t":"名詞の間に","ko":"~하는 동안에, ~사이에","cat":"시간·순서","conn":[{"w":"명사","f":"夏休みの間に"},{"w":"동사 (ている형이 많음)","f":"寝ている間に"},{"w":"い형용사","f":"若い間に"},{"w":"な형용사","f":"静かな間に"}],"rule":["기간을 나타내는 명사 뒤에 の를 붙인다: 夏休み + の.","그 뒤에 間(あいだ)를 붙이고, 시점을 나타내는 に를 더한다: 夏休みの間に.","뒤에는 그 기간 안의 어느 한 때에 일어나는 일(한 번의 행동이나 변화)을 놓는다."],"why":"間(あいだ)는 '시간·공간의 사이'를 뜻하는 명사이고, 여기에 때를 가리키는 조사 に가 붙어 '그 기간 안의 한 시점에'가 된다.","nu":"회화·문장 모두 쓴다. 뒤의 일이 기간 내내 계속되면 に 없는 間를 쓴다(夏休みの間、ずっと国にいた). 한국어 '동안에'는 두 경우 모두 쓰기 때문에 間과 間に를 섞어 쓰는 실수가 많다.","cmp":[{"g":"名詞の間","d":"間(に 없음)는 그 기간 내내 계속되는 일. 間に는 기간 안에서 한 번 일어나는 일."},{"g":"名詞中に","d":"中(ちゅう)에는 명사에만 바로 붙는다(授業中に). 間に는 の를 거쳐 붙고 동사·형용사에도 쓴다."}],"ex":[{"jp":"夏休[なつやす]みの間[あいだ]に、運転免許[うんてんめんきょ]を取[と]りたい。","ko":"여름방학 동안에 운전면허를 따고 싶다."},{"jp":"留守[るす]の間[あいだ]に、荷物[にもつ]が届[とど]いていた。","ko":"집을 비운 사이에 짐이 와 있었다."},{"jp":"赤[あか]ちゃんが寝[ね]ている間[あいだ]に、洗濯[せんたく]をした。","ko":"아기가 자는 동안에 빨래를 했다."}],"dr":[{"t":"make","q":"昼休み → '점심시간 동안에 은행에 간다'","a":"昼休みの間に銀行に行く","hint":"명사 + の + 間に + 한 번의 행동."},{"t":"make","q":"冬休み → '겨울방학 동안에'","a":"冬休みの間に","hint":"명사 + の + 間 + に."},{"t":"fill","q":"旅行[りょこう]の（　）、家[いえ]に泥棒[どろぼう]が入[はい]った。","a":"間に","opts":["間に","ために","までに","ばかり"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AE%E9%96%93%E3%81%AB"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_019","t":"名詞＋中（ちゅう）","ko":"~하는 중, ~하고 있는 동안","cat":"시간·순서","conn":[{"w":"동작성 명사(する동사 명사)","f":"会議 + 中 → 会議中"},{"w":"동작성 명사","f":"食事 + 中 → 食事中"},{"w":"기간 명사","f":"夏休み + 中 → 夏休み中"},{"w":"영업·상태 표시","f":"営業 + 中 → 営業中"}],"rule":["동사가 아니라 명사 바로 뒤에 中(ちゅう)를 붙인다. 글자 변화는 없다.","会議(명사) + 中 → 会議中. 문장 끝에서는 です/だ를 붙여 会議中です로 쓴다.","동사에는 붙이지 않는다(勉強する中 ×). 동사로 말할 때는 勉強している間・勉強しているとき처럼 바꾼다."],"why":"中은 '안·가운데'를 뜻하는 한자로, 활동 명사 뒤에서 그 활동이 진행되고 있는 시간 안에 있음을 나타낸다.","nu":"회화·문어 모두 쓰며 간판·표지(営業中, 準備中, 工事中)에 아주 흔하다. 앞말은 명사여야 한다. 같은 中이라도 一日中・世界中처럼 じゅう로 읽으면 '~내내, 온 ~'라는 다른 뜻이 된다. 夜中는 よなか로 읽고, 午後中라고는 하지 않는다(午前中는 가능). 한국어 '~중'과 비슷해 쓰기 쉽지만 동사 뒤에 붙이는 실수에 주의.","cmp":[{"g":"～中（じゅう）","d":"一日中・世界中처럼 시간·공간 전체 '내내, 온 ~'. ちゅう는 '진행 중'."},{"g":"～ている間","d":"동사에 붙는 '~하는 동안'. 中은 명사에만 붙는다."}],"ex":[{"jp":"父[ちち]は今[いま]、電話[でんわ]中[ちゅう]です。","ko":"아버지는 지금 통화 중이에요."},{"jp":"授業[じゅぎょう]中[ちゅう]に携帯[けいたい]を見[み]てはいけません。","ko":"수업 중에 휴대폰을 보면 안 됩니다."},{"jp":"夏休[なつやす]み中[ちゅう]に、一度[いちど]国[くに]へ帰[かえ]ります。","ko":"여름방학 중에 한 번 고국에 돌아갑니다."}],"dr":[{"t":"make","q":"食事 → '식사 중입니다'","a":"食事中です","hint":"명사 뒤에 中(ちゅう) + です."},{"t":"make","q":"会議 → '회의 중에'","a":"会議中に","hint":"명사 + 中 뒤에 시간 조사 に."},{"t":"fill","q":"父[ちち]は今[いま]、会議[かいぎ]（　）なので、電話[でんわ]に出[で]られません。","a":"中","opts":["中","後","前","間"]}],"src":["https://www.tofugu.com/japanese-grammar/chuu/","https://bunpro.jp/grammar_points/%E4%B8%AD"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_023","t":"～たときに","ko":"~했을 때(에)","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"会う → 会ったときに"},{"w":"2그룹 동사","f":"見る → 見たときに"},{"w":"する","f":"する → したときに"},{"w":"来る","f":"来る → 来(き)たときに"}],"rule":["동사를 た형으로 바꾼다(見る → 見た: 2그룹은 る를 떼고 た).","た형 뒤에 とき를 붙이고, 뒤에 다른 동작이 이어지면 に를 붙인다: 見た + とき + に.","た형 + とき는 그 동작이 끝난 뒤의 일을, 사전형 + とき는 그 동작을 하기 전·하는 도중의 일을 말한다(日本へ行くとき=가기 전에 / 行ったとき=가서)."],"why":"とき(時)는 '때'를 뜻하는 명사라서 앞에 동사의 보통형이 수식어로 붙는다. 앞 동사의 시제(た/る)가 뒷문장과의 앞뒤 순서를 정한다.","nu":"회화·문어 모두 쓴다. 뒷문장이 과거가 아니어도 앞 동작이 먼저 끝나면 た형을 쓴다(家に帰ったとき、手を洗います). 한국어 '갈 때/갔을 때'와 비슷하지만 '日本に行くときカメラを買った'는 가기 전에 산 것, '行ったとき'는 가서 산 것이 되어 뜻이 달라진다. に는 생략할 수 있다.","cmp":[{"g":"～るときに","d":"앞 동작이 아직 끝나기 전(전·도중)에 뒷일이 일어남."},{"g":"～たら","d":"조건·계기 '~하면/~했더니'. とき는 단순히 그 시점."}],"ex":[{"jp":"その映画[えいが]を見[み]たときに、泣[な]いてしまいました。","ko":"그 영화를 봤을 때 울어 버렸어요."},{"jp":"日本[にほん]へ行[い]ったとき、お土産[みやげ]を買[か]いました。","ko":"일본에 갔을 때 기념품을 샀어요."},{"jp":"家[いえ]に帰[かえ]ったときは、まず手[て]を洗[あら]います。","ko":"집에 돌아왔을 때는 먼저 손을 씻어요."}],"dr":[{"t":"make","q":"着く → '도착했을 때에'","a":"着いたときに","hint":"く는 いた로 바꾸고 + ときに."},{"t":"make","q":"起きる → '일어났을 때'","a":"起きたとき","hint":"2그룹: る를 떼고 た + とき."},{"t":"fill","q":"駅[えき]に着[つ]いた（　）、雨[あめ]が降[ふ]り始[はじ]めた。","a":"とき","opts":["とき","ながら","ために","まま"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%8D","https://mangolanguages.com/resources/learn/grammar/japanese/how-to-use-toki-in-japanese-"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_024","t":"～たところだ","ko":"막 ~한 참이다, 방금 ~했다","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"着く → 着いたところだ"},{"w":"2그룹 동사","f":"食べる → 食べたところだ"},{"w":"する","f":"する → したところだ"},{"w":"来る","f":"来る → 来(き)たところだ"}],"rule":["동사를 た형으로 바꾼다. 着く처럼 く로 끝나면 く가 いた가 된다(着く → 着いた).","た형 뒤에 ところ + だ(です)를 붙인다: 着いた + ところだ.","같은 ところ라도 사전형 + ところだ는 '막 ~하려는 참', ている + ところだ는 '~하고 있는 중'이 된다."],"why":"ところ(所)는 본래 '곳'이지만 동사에 붙어 시간상의 '시점·단계'를 가리킨다. 그래서 た형 + ところ는 '동작을 막 끝낸 시점'이 된다.","nu":"회화에서는 ところ를 とこ로 줄여 着いたとこ라고도 한다. 동작이 끝난 직후의 '시점'만 말하므로, 시간이 좀 지났어도 화자가 최근이라고 느끼면 쓸 수 있는 たばかり와 다르다. 'ちょうど・今' 같은 말과 잘 어울린다. 문장 중간의 '～たところ、…' 는 '~했더니 (결과) …였다'라는 다른 용법이다(医者に行ったところ、風邪だった).","cmp":[{"g":"～たばかり","d":"심리적으로 최근이면 며칠·몇 달 전에도 씀. たところ는 정말 직후의 시점."},{"g":"～るところだ","d":"사전형: 이제 막 ~하려는 참(아직 안 함)."}],"ex":[{"jp":"今[いま]、駅[えき]に着[つ]いたところです。","ko":"지금 막 역에 도착했어요."},{"jp":"ちょうど晩[ばん]ご飯[はん]を食[た]べたところだ。","ko":"막 저녁을 먹은 참이야."},{"jp":"さっき部屋[へや]の掃除[そうじ]をしたところなので、きれいですよ。","ko":"방금 방 청소를 해서 깨끗해요."}],"dr":[{"t":"make","q":"起きる → '막 일어난 참이다'","a":"起きたところだ","hint":"る를 떼고 た + ところだ."},{"t":"make","q":"帰る → '막 돌아온 참입니다'","a":"帰ったところです","hint":"1그룹 る는 った로 + ところです."},{"t":"fill","q":"今[いま]、宿題[しゅくだい]が終[お]わった（　）です。","a":"ところ","opts":["ところ","ながら","ほど","しか"]}],"src":["https://bunpro.jp/ja/grammar_points/146","https://aiueo.cc/pages/ja/grammar/web/165.php"],"vf":1,"u":9,"g":1,"gp":"gg_N4_06"},{"id":"g4_035","t":"～ているところ","ko":"지금 한창 ~하고 있는 중","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"書く → 書いている + ところ"},{"w":"2그룹 동사","f":"食べる → 食べている + ところ"},{"w":"する","f":"準備する → 準備している + ところ"},{"w":"과거","f":"見ている + ところだった"}],"rule":["1. 동사를 て형으로 바꾼다(食べる→食べて).","2. いる를 붙여 진행형 ～ている를 만든다.","3. 명사 ところ를 붙이고 문말에 です・だ(과거는 でした・だった)를 붙인다."],"why":"ところ는 동작의 흐름 가운데 '어느 시점인가'를 가리킨다. 사전형+ところ(막 하려는 참), ている+ところ(한창 하는 중), た형+ところ(막 끝낸 참)가 한 세트다.","nu":"회화·정중체 모두 사용. '바로 지금 그 단계'임을 강조해 전화나 질문에 자기 상황을 설명할 때 많이 쓴다. ある・いる・分かる 같은 상태 동사에는 붙이지 않는다. 과거 ているところだった는 어떤 일이 일어났을 때 한창 ~하던 중이었음을 나타낸다.","cmp":[{"g":"～ている","d":"단순한 진행·상태. ～ているところ는 그 순간 한창임을 특히 강조한다."},{"g":"～たところ","d":"동작을 막 끝낸 직후. ～ているところ는 아직 진행 중."}],"ex":[{"jp":"今[いま]、晩[ばん]ご飯[はん]を食[た]べているところです。","ko":"지금 한창 저녁을 먹고 있는 중이에요."},{"jp":"ごめん、今[いま]運転[うんてん]しているところなんだ。","ko":"미안, 지금 운전하는 중이야."},{"jp":"母[はは]から電話[でんわ]が来[き]たとき、ちょうど宿題[しゅくだい]をしているところだった。","ko":"엄마한테서 전화가 왔을 때 마침 숙제를 하던 중이었다."}],"dr":[{"t":"make","q":"探す → ～ているところです","a":"探しているところです","hint":"す → して + いる + ところです"},{"t":"make","q":"書く → ～ているところです","a":"書いているところです","hint":"く → いて + いる + ところです"},{"t":"fill","q":"A：レポートはできた？　B：今[いま]、書[か]いている（　）です。","a":"ところ","opts":["ところ","ばかり","ため","まま"]}],"src":["https://langoal.com/jlpt/explain-grammar-tokoroda.html"],"vf":1,"u":10,"g":1,"gp":"gg_N4_06"},{"id":"g4_036","t":"～ている間に","ko":"~하고 있는 동안에 (그 사이에)","cat":"시간·순서","conn":[{"w":"동사 ている형","f":"寝る → 寝ている + 間に"},{"w":"동사(する)","f":"買い物する → 買い物している + 間に"},{"w":"명사","f":"夏休み + の + 間に"}],"rule":["1. 동사를 て형으로 바꾼다(寝る→寝て).","2. いる를 붙여 ～ている로 만든다.","3. 명사 間(あいだ)와 조사 に를 붙인다. 뒤 문장에는 그 기간 안에 일어난 일을 쓴다."],"why":"間(あいだ)는 '사이, 구간'이라는 뜻의 명사이고, に는 그 구간 안의 한 시점을 가리킨다. 그래서 'A가 계속되는 동안 그 사이 어느 때에 B'가 된다.","nu":"회화·문어 모두 사용. 앞뒤 주어가 달라도 된다. 뒤에는 한 번 일어나는 일이 온다. た형 + 間に는 쓰지 않는다(寝た間に X). に가 없는 ～ている間는 '그 기간 내내'라는 뜻이라 뒤에 계속되는 동작이 온다(寝ている間、ずっと雨が降っていた).","cmp":[{"g":"～ている間","d":"に 없이 쓰면 기간 내내 계속. ～ている間に는 그 기간 중 한때 일어난 일."},{"g":"～ながら","d":"한 사람이 두 동작을 동시에 할 때. ～ている間に는 주어가 달라도 된다."}],"ex":[{"jp":"寝[ね]ている間[あいだ]に、雪[ゆき]が降[ふ]りました。","ko":"자고 있는 동안에 눈이 내렸어요."},{"jp":"子[こ]どもが遊[あそ]んでいる間[あいだ]に、晩[ばん]ご飯[はん]を作[つく]ります。","ko":"아이가 노는 동안에 저녁을 만들어요."},{"jp":"夏休[なつやす]みの間[あいだ]に、ひらがなを全部[ぜんぶ]覚[おぼ]えました。","ko":"여름 방학 동안에 히라가나를 전부 외웠어요."}],"dr":[{"t":"make","q":"待つ → ～ている間に","a":"待っている間に","hint":"つ → って + いる + 間に"},{"t":"make","q":"出かける → ～ている間に","a":"出かけている間に","hint":"る를 떼고 て + いる + 間に"},{"t":"fill","q":"母[はは]が買[か]い物[もの]をしている（　）、部屋[へや]を掃除[そうじ]した。","a":"間に","opts":["間に","ながら","まで","ほど"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%81%84%E3%82%8B%E3%81%82%E3%81%84%E3%81%A0%E3%81%AB"],"vf":1,"u":10,"g":1,"gp":"gg_N4_06"},{"id":"g4_037","t":"～ておく","ko":"~해 두다, 미리 ~해 놓다","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"買う → 買って + おく"},{"w":"2그룹 동사","f":"調べる → 調べて + おく"},{"w":"する","f":"予約する → 予約して + おく"},{"w":"회화 축약","f":"買っておく → 買っとく / 読んでおく → 読んどく"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 う・つ・る는 って(買う→買って).","2. て형 뒤에 おく를 붙인다. おく는 1그룹 동사라 おきます, おいた, おかない로 활용한다.","3. 회화에서는 ておく가 とく로, でおく가 どく로 줄어든다(買っとく, 読んどく)."],"why":"おく는 置く(놓다, 그대로 두다)에서 온 말. '~하고 그 상태로 두다'라는 뜻에서 나중을 위해 미리 해 둔다는 의미가 된다.","nu":"회화·정중체 모두 사용(축약형 とく・どく는 비격식). 나중을 위한 준비, 그대로 둠(窓を開けておく), 문제를 막기 위한 조치 등에 쓴다. 의지로 하는 행동에 쓴다. 한국어 '~해 두다'와 거의 같지만 일본어는 더 자주 쓴다.","cmp":[{"g":"～てある","d":"누군가 해 둔 결과 상태를 묘사(ビールが買ってある). ～ておく는 해 두는 행위 자체."}],"ex":[{"jp":"パーティーの前[まえ]に飲[の]み物[もの]を買[か]っておきます。","ko":"파티 전에 음료를 사 둘게요."},{"jp":"旅行[りょこう]の前[まえ]にホテルを予約[よやく]しておいた。","ko":"여행 전에 호텔을 예약해 두었다."},{"jp":"暑[あつ]いから、窓[まど]を開[あ]けておいてください。","ko":"더우니까 창문을 열어 두세요."}],"dr":[{"t":"make","q":"調べる → ～ておく","a":"調べておく","hint":"る를 떼고 て + おく"},{"t":"make","q":"予約する → ～ておきます","a":"予約しておきます","hint":"する → して + おきます"},{"t":"fill","q":"明日[あした]テストがあるので、今日[きょう]復習[ふくしゅう]して（　）。","a":"おきます","opts":["おきます","あります","くれます","あげます"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%8A%E3%81%8F"],"vf":1,"u":10,"g":1,"gp":"gg_N4_06"},{"id":"g4_040","t":"～てくる","ko":"~해 오다, ~하기 시작하다, ~하고 오다","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"降る → 降って + くる"},{"w":"2그룹 동사","f":"増える → 増えて + くる"},{"w":"い형용사","f":"寒い → 寒くなって + くる"},{"w":"する","f":"勉強する → 勉強して + くる"},{"w":"이동(하고 오다)","f":"買う → 買って + くる"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 る는 って(降る→降って).","2. て형 뒤에 くる를 붙인다.","3. くる는 불규칙 동사라 과거는 きた, ます형은 きます가 된다. 지금까지 진행된 변화는 보통 ～てきた / ～てきました로 말한다."],"why":"くる(오다)는 말하는 사람 쪽으로 다가오는 움직임. 그래서 공간에서는 '이쪽으로 ~해 오다', 시간에서는 과거에서 지금(말하는 시점)까지 변화가 다가오거나 이어져 온 것을 나타낸다.","nu":"회화·문어 모두 사용. 뜻이 여럿이다: (1) 변화가 시작·진행됨(雨が降ってきた, 寒くなってきた), (2) 과거부터 지금까지 계속(10年働いてきた), (3) 말하는 사람 쪽으로 이동(走ってくる), (4) 하고 돌아오다(買ってくる). 반대 방향·앞으로의 변화는 ～ていく.","cmp":[{"g":"～ていく","d":"지금부터 앞으로, 또는 말하는 사람에게서 멀어지는 방향. ～てくる는 과거에서 지금, 또는 말하는 사람 쪽으로."}],"ex":[{"jp":"あ、雨[あめ]が降[ふ]ってきました。","ko":"아, 비가 내리기 시작했어요."},{"jp":"だんだん寒[さむ]くなってきましたね。","ko":"점점 추워졌네요."},{"jp":"ちょっとコンビニでパンを買[か]ってきます。","ko":"잠깐 편의점에서 빵 사 올게요."}],"dr":[{"t":"make","q":"増える → ～てきた","a":"増えてきた","hint":"る를 떼고 て + くる의 과거 きた"},{"t":"make","q":"寒くなる → ～てきました","a":"寒くなってきました","hint":"る → って + きました"},{"t":"fill","q":"最近[さいきん]、日本語[にほんご]が少[すこ]しずつ分[わ]かって（　）。","a":"きました","opts":["きました","おきました","あげました","くれました"]}],"src":["https://www.tofugu.com/japanese-grammar/teiku-tekuru/","https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%81%8F%E3%82%8B"],"vf":1,"u":10,"g":1,"gp":"gg_N4_06"},{"id":"g4_054","t":"～ながら","ko":"~하면서","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"聞く → 聞き + ながら"},{"w":"1그룹 동사","f":"歩く → 歩き + ながら"},{"w":"2그룹 동사","f":"見る → 見 + ながら"},{"w":"する 동사","f":"運転する → 運転し + ながら"}],"rule":["1. 동사를 ます형 어간으로 바꾼다. 1그룹은 어미 う단을 い단으로(聞く→聞き), 2그룹은 る를 뗀다(見る→見), する→し.","2. ます형 어간 뒤에 ながら를 붙인다: 聞き + ながら.","3. 뒤 문장이 주된 동작이고, ながら 앞은 함께 하는 부수적인 동작이다. 시제와 정중체는 뒤 문장에서 나타낸다."],"why":"","nu":"두 동작의 주어는 같아야 한다(내가 음악을 들으면서 내가 요리한다). 주어가 다르면 ～間(あいだ) 등을 쓴다. 주된 동작을 뒤에 둔다. 같은 형태로 '~이면서도'라는 역접 용법(残念ながら, 知りながら)도 있지만 N4에서는 동시 동작의 뜻이 중심이다.","cmp":[{"g":"～間(あいだ)","d":"어떤 기간 동안 다른 일이 일어남. 두 문장의 주어가 달라도 된다."}],"ex":[{"jp":"音楽[おんがく]を聞[き]きながら料理[りょうり]をしました。","ko":"음악을 들으면서 요리를 했어요."},{"jp":"テレビを見[み]ながらご飯[はん]を食[た]べないでください。","ko":"텔레비전을 보면서 밥을 먹지 마세요."},{"jp":"歩[ある]きながらスマホを使[つか]うのは危[あぶ]ないです。","ko":"걸으면서 스마트폰을 쓰는 것은 위험해요."}],"dr":[{"t":"make","q":"飲む → ～ながら","a":"飲みながら","hint":"む를 み로(ます형 어간) 바꾸고 ながら."},{"t":"make","q":"運転する → ～ながら","a":"運転しながら","hint":"する의 ます형 어간은 し."},{"t":"fill","q":"コーヒーを飲[の]み（　）、新聞[しんぶん]を読[よ]みます。","a":"ながら","opts":["ながら","たり","て","ために"]}],"src":["https://bunpro.jp/grammar_points/ながら","https://www.tofugu.com/japanese-grammar/nagara/"],"vf":1,"u":10,"g":1,"gp":"gg_N4_07"},{"id":"g4_068","t":"～るときに","ko":"~할 때(에)","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"寝る + とき(に)"},{"w":"동사 た형","f":"寝た + とき(に)"},{"w":"い형용사","f":"寒い + とき"},{"w":"な형용사","f":"暇な + とき"},{"w":"명사","f":"子どもの + とき"}],"rule":["1. 동사는 사전형 그대로 둔다: 寝る.","2. 뒤에 명사 とき(때)를 붙인다: 寝るとき.","3. 뒤 문장의 동작이 일어나는 시점을 콕 집을 때 に를 붙인다: 寝るときに.","4. 사전형 とき는 그 동작이 아직 끝나지 않은 시점(하기 전·하려는 때)이고, た형 とき(寝たとき)는 끝난 뒤의 시점이다."],"why":"とき(時)는 '때'라는 명사라서 명사를 꾸미는 형태(동사 보통형, な형용사+な, 명사+の)가 앞에 온다. に는 시간을 나타내는 조사.","nu":"회화·문어 모두 쓴다. 한국어 '~할 때'는 시제를 구별하지 않지만 일본어는 사전형/た형으로 앞뒤 순서를 나타낸다: 日本へ行くとき、かばんを買った(가기 전에 샀다) / 日本へ行ったとき、かばんを買った(가서 샀다). に는 생략할 수 있으며, 붙이면 그 시점이 더 강조된다.","cmp":[{"g":"～たときに","d":"동작이 끝난 뒤의 시점. ～るときに는 동작 전(또는 도중)의 시점."},{"g":"～と","d":"앞 일이 일어나면 자연스럽게 뒤 일이 따라오는 조건. とき는 단순히 시점을 가리킨다."}],"ex":[{"jp":"寝[ね]るときに、部屋[へや]の電気[でんき]を消[け]します。","ko":"잘 때 방 불을 끕니다."},{"jp":"家[いえ]を出[で]るときに、「行[い]ってきます」と言[い]います。","ko":"집을 나설 때 '다녀오겠습니다'라고 말합니다."},{"jp":"暇[ひま]なときに、この本[ほん]を読[よ]んでください。","ko":"한가할 때 이 책을 읽어 주세요."}],"dr":[{"t":"make","q":"寝る → ～ときに (자기 전에)","a":"寝るときに","hint":"아직 자기 전이므로 사전형 그대로 + ときに"},{"t":"make","q":"日本へ行く → ～とき、空港でかばんを買った (가기 전에 샀다)","a":"日本へ行くとき","hint":"가기 전 시점이므로 た형이 아니라 사전형 + とき"},{"t":"fill","q":"寝[ね]る（　）、歯[は]を磨[みが]きます。","a":"ときに","opts":["ときに","ために","ように","ところに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%8D"],"vf":1,"u":10,"g":1,"gp":"gg_N4_07"},{"id":"g4_069","t":"～るところだ","ko":"막 ~하려는 참이다","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"出かける + ところだ"},{"w":"(비교) 동사 ている형","f":"出かけている + ところだ"},{"w":"(비교) 동사 た형","f":"出かけた + ところだ"}],"rule":["1. 동사는 사전형 그대로 둔다: 出かける.","2. 뒤에 ところ(시점·장면)를 붙인다: 出かけるところ.","3. 끝에 だ / です를 붙인다: 出かけるところです.","4. 같은 ところ라도 앞 동사가 사전형이면 '직전', ている형이면 '한창 도중', た형이면 '막 끝난 직후'가 된다."],"why":"ところ(所)는 원래 '곳'이지만 시간 위의 '지점·국면'으로도 쓰여, 동작 직전의 지점을 가리키게 된다.","nu":"회화에서 많이 쓴다. '지금 막 하려던 참'이라 今から・ちょうど・これから와 잘 어울린다. 과거형 ～るところだった는 '하마터면 ~할 뻔했다'(実際にはしなかった)는 뜻도 된다: 遅れるところだった. 한국어 '~하는 중'은 ているところ이지 るところ가 아니다.","cmp":[{"g":"～ているところだ","d":"동작이 한창 진행 중인 장면."},{"g":"～たところだ","d":"동작이 막 끝난 직후."}],"ex":[{"jp":"今[いま]から出[で]かけるところです。","ko":"지금부터 막 나가려던 참이에요."},{"jp":"ちょうど晩[ばん]ご飯[はん]を食[た]べるところだから、一緒[いっしょ]にどう？","ko":"마침 저녁을 먹으려던 참이니까, 같이 어때?"},{"jp":"寝坊[ねぼう]して、電車[でんしゃ]に遅[おく]れるところだった。","ko":"늦잠을 자서 전철을 놓칠 뻔했다."}],"dr":[{"t":"make","q":"始める → ～ところです (막 시작하려는 참)","a":"始めるところです","hint":"사전형 그대로 + ところです"},{"t":"make","q":"帰る → ～ところでした (막 돌아가려던 참)","a":"帰るところでした","hint":"사전형 + ところ + でした"},{"t":"fill","q":"これから家[いえ]を出[で]る（　）です。","a":"ところ","opts":["ところ","ばかり","はず","つもり"]}],"src":["https://en.wiktionary.org/wiki/所"],"vf":1,"u":10,"g":1,"gp":"gg_N4_07"},{"id":"g4_090","t":"～たり～たりする","ko":"~하거나 ~하거나 하다 (예시 나열)","cat":"시간·순서","conn":[{"w":"동사","f":"見る → 見たり, 読む → 読んだり"},{"w":"い형용사","f":"暑い → 暑かったり"},{"w":"な형용사","f":"静かだ → 静かだったり"},{"w":"명사","f":"雨だ → 雨だったり"}],"rule":["1. 동사를 た형으로 바꾸고 り를 붙인다(見る→見た→見たり, 読む→読んだ→読んだり).","2. い형용사는 い를 かった로 바꾸고 り를 붙인다(暑い→暑かったり).","3. な형용사·명사는 だった에 り를 붙인다(静かだったり, 雨だったり).","4. 마지막에 する를 붙여 문장을 끝낸다(見たり読んだりする). 시제는 する에서 나타낸다(見たり読んだりした)."],"why":"","nu":"여러 행동 가운데 몇 가지를 예로 든다(그 밖에도 있다는 느낌). 하나만 쓸 수도 있다(映画を見たりする). 반대되는 말을 늘어놓으면 '~했다 ~했다 한다'는 반복이 된다(行ったり来たりする, 暑かったり寒かったり). 두 번째 たり 뒤의 する를 빠뜨리거나, 첫 번째에만 たり를 쓰는 실수(×見たり、読む)에 주의. 순서대로 한 일은 ～て를 쓴다.","cmp":[{"g":"～て","d":"행동을 일어난 순서대로 모두 나열한다. ～たり는 순서와 상관없이 일부를 예로 든다."},{"g":"～し","d":"이유·특징을 쌓아 올린다. ～たり는 행동·상태의 예시나 반복."}],"ex":[{"jp":"週末[しゅうまつ]は映画[えいが]を見[み]たり、本[ほん]を読[よ]んだりします。","ko":"주말에는 영화를 보거나 책을 읽거나 합니다."},{"jp":"この季節[きせつ]は暑[あつ]かったり寒[さむ]かったりします。","ko":"이 계절은 더웠다 추웠다 해요."},{"jp":"休[やす]みの日[ひ]は、掃除[そうじ]したり、買[か]い物[もの]に行[い]ったりした。","ko":"쉬는 날에는 청소하거나 장 보러 가거나 했다."}],"dr":[{"t":"make","q":"歌う / 踊る → ～たり～たりする","a":"歌ったり踊ったりする","hint":"う·る는 った로 바뀌고 り, 마지막에 する."},{"t":"make","q":"泳ぐ / 遊ぶ → ～たり～たりする","a":"泳いだり遊んだりする","hint":"ぐ→いだ, ぶ→んだ에 り를 붙이고 마지막에 する."},{"t":"fill","q":"日曜日[にちようび]は音楽[おんがく]を聞[き]いたり、ゲームをし（　）します。","a":"たり","opts":["たり","ても","たら","ながら"]}],"src":["https://www.tofugu.com/japanese-grammar/tarisuru/"],"vf":1,"u":10,"g":1,"gp":"gg_N4_07"},{"id":"g4_115","t":"～までに","ko":"~까지(는), ~전에 (기한)","cat":"시간·순서","conn":[{"w":"명사(시각·날짜)","f":"5時 + までに"},{"w":"동사 사전형","f":"帰る + までに"}],"rule":["1. までに는 형태가 바뀌지 않으며 시각·날짜 명사 바로 뒤에 붙인다(5時＋までに).","2. 동사는 사전형(기본형) 그대로 붙인다(母が帰る＋までに).","3. 뒤에는 그 기한 전에 한 번 끝나는 동작이 온다(5時までに帰ります)."],"why":"","nu":"한국어로는 まで와 までに 모두 '~까지'라서 한국인이 자주 혼동한다. まで는 그때까지 계속되는 동작(5時まで働く: 5시까지 계속 일함), までに는 그 시점 전에 한 번 이루어지는 동작(5時までに帰る: 5시 전에 돌아옴)에 쓴다. ×5時までに待つ처럼 계속 동작에 쓰면 틀린다.","cmp":[{"g":"～まで","d":"끝나는 시점까지 동작·상태가 계속됨(3時まで寝る). までに는 기한 안에 한 번 끝냄(3時までに起きる)."}],"ex":[{"jp":"金曜日[きんようび]までにレポートを出[だ]してください。","ko":"금요일까지 리포트를 내 주세요."},{"jp":"10時[じゅうじ]までに家[いえ]に帰[かえ]ります。","ko":"10시까지는 집에 돌아갑니다."},{"jp":"母[はは]が帰[かえ]るまでに部屋[へや]を掃除[そうじ]しておきます。","ko":"엄마가 돌아오기 전에 방을 청소해 두겠습니다."}],"dr":[{"t":"make","q":"明日 / 返します → ～までに","a":"明日までに返します","hint":"기한이 되는 명사 뒤에 までに를 붙인다."},{"t":"make","q":"授業が始まる / 来てください → ～までに","a":"授業が始まるまでに来てください","hint":"동사 사전형 뒤에 までに를 그대로 붙인다."},{"t":"fill","q":"この本[ほん]は来週[らいしゅう]の月曜日[げつようび]（　）返[かえ]してください。","a":"までに","opts":["までに","まで","ながら","ほど"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%A7%E3%81%AB","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/200911.html"],"vf":1,"u":10,"g":1,"gp":"gg_N4_07"},{"id":"g4_116","t":"～まま","ko":"~한 채(로), ~그대로","cat":"시간·순서","conn":[{"w":"동사 た형","f":"開けた + まま"},{"w":"동사 ない형","f":"言わない + まま"},{"w":"い형용사","f":"若い + まま"},{"w":"な형용사","f":"きれいな + まま"},{"w":"명사","f":"昔の + まま"}],"rule":["1. 동사는 사전형 어미를 た형으로 바꾼 뒤 まま를 붙인다(開ける → 開けた → 開けたまま).","2. い형용사는 기본형 그대로 붙이고(若いまま), な형용사는 な를 넣어 붙인다(きれいなまま).","3. 명사는 の를 넣어 붙인다(昔のまま).","4. 문장 중간에서는 まま 또는 ままで로 뒤 문장에 이어진다(窓を開けたまま寝た)."],"why":"","nu":"어떤 상태가 바뀌지 않고 그대로인 채 다른 일이 일어날 때 쓴다. 말투 자체는 중립적이며, 좋고 나쁨의 평가는 문맥에 따라 정해진다(電気をつけたまま寝た). 동사는 주로 た형・ない형에 붙고 사전형에는 잘 붙지 않는다. ～ながら(두 동작을 동시에)와 달리 앞부분은 이미 끝난 동작의 결과 상태다.","cmp":[{"g":"～ながら","d":"두 동작을 동시에 함(歩きながら話す). まま는 앞 동작의 결과 상태가 유지된 채 다음 일이 일어남(靴をはいたまま入る)."}],"ex":[{"jp":"窓[まど]を開[あ]けたまま寝[ね]てしまいました。","ko":"창문을 연 채로 자 버렸습니다."},{"jp":"この町[まち]は昔[むかし]のままです。","ko":"이 마을은 옛날 그대로입니다."},{"jp":"靴[くつ]をはいたまま部屋[へや]に入[はい]らないでください。","ko":"신발을 신은 채로 방에 들어오지 마세요."}],"dr":[{"t":"make","q":"電気をつける / 出かけた → ～まま","a":"電気をつけたまま出かけた","hint":"つける를 た형 つけた로 바꾸고 まま를 붙인다."},{"t":"make","q":"昔 → ～まま","a":"昔のまま","hint":"명사 뒤에는 の를 넣고 まま."},{"t":"fill","q":"テレビをつけた（　）寝[ね]てしまった。","a":"まま","opts":["まま","ながら","までに","しか"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%BE"],"vf":1,"u":11,"g":1,"gp":"gg_N4_07"},{"id":"g4_078","t":"～から（이유）","ko":"~니까, ~때문에","cat":"원인·이유","conn":[{"w":"동사 보통형/정중형","f":"降る + から, 降ります + から"},{"w":"い형용사","f":"寒い + から"},{"w":"な형용사","f":"静かだ + から"},{"w":"명사","f":"雨だ + から"}],"rule":["1. 이유가 되는 문장을 보통형(또는 です・ます형)으로 끝낸다: 雨が降る.","2. 뒤에 から를 붙이고 결과·행동을 이어 말한다: 雨が降るから、傘を持っていく.","3. 명사·な형용사는 반드시 だ를 붙인 뒤 から를 붙인다: 雨 → 雨だ → 雨だから.","4. 정중하게는 です에 붙인다: 雨ですから."],"why":"から의 기본 뜻은 '~에서(출발점)'이며, 그것이 '그 일에서 비롯되어', 즉 원인·이유를 나타내는 뜻으로 쓰인다.","nu":"회화에서 매우 많이 쓰며 말하는 사람의 주관적인 이유를 나타낸다. 뒤에 명령·의뢰·권유(～てください, ～ましょう)가 자연스럽게 온다. かもしれない・かどうか와 달리 명사·な형용사 뒤에 だ가 꼭 필요하다(×雨から는 '비로부터'라는 뜻이 됨). 윗사람에게 사정을 설명할 때는 ので가 더 부드럽다.","cmp":[{"g":"～ので","d":"더 객관적이고 정중한 느낌. 명사·な형용사는 なので."}],"ex":[{"jp":"雨[あめ]だから、今日[きょう]は家[いえ]にいます。","ko":"비가 오니까 오늘은 집에 있을게요."},{"jp":"もう遅[おそ]いから、早[はや]く寝[ね]なさい。","ko":"벌써 늦었으니까 빨리 자거라."},{"jp":"この部屋[へや]は静[しず]かだから、よく勉強[べんきょう]できる。","ko":"이 방은 조용하니까 공부가 잘된다."}],"dr":[{"t":"make","q":"休みだ → ～から、遊びに行こう","a":"休みだから","hint":"명사는 だ를 붙인 뒤 + から"},{"t":"make","q":"暑い → ～から、窓を開けて","a":"暑いから","hint":"い형용사는 그대로 + から"},{"t":"fill","q":"危[あぶ]ない（　）、道[みち]で遊[あそ]ばないでください。","a":"から","opts":["から","のに","かどうか","かしら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%8B%E3%82%89-because"],"vf":1,"u":11,"g":1,"gp":"gg_N4_07"},{"id":"g4_110","t":"～ので","ko":"~이므로, ~이기 때문에","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"ある + ので / 行った + ので"},{"w":"い형용사","f":"高い + ので"},{"w":"な형용사","f":"静か + な + ので"},{"w":"명사","f":"雨 + な + ので"},{"w":"정중형(격식)","f":"あります + ので"}],"rule":["1. 동사·い형용사는 보통형 그대로 ので를 붙인다(あるので, 高いので).","2. 명사·な형용사의 현재 긍정에서는 だ를 な로 바꾸고 ので를 붙인다(雨だ→雨なので).","3. 과거형에서는 그대로 붙인다(雨だったので).","4. ので 뒤에 결과·판단 문장을 잇는다(雨なので、出かけません)."],"why":"","nu":"から보다 객관적이고 부드러워서 사정 설명·변명·부탁에 잘 어울린다(遅れたので、すみません). 정중한 자리에서는 ますので·ですので도 쓴다. 뒤 문장에 강한 명령·의지(~해라, ~하자)는 から가 더 자연스럽다. 명사에 ×雨ので로 바로 붙이는 실수에 주의.","cmp":[{"g":"～から","d":"말하는 사람의 주관적 이유를 강하게 내세운다. 명령·권유와 잘 어울리고 회화적. ので는 객관적·정중한 느낌."},{"g":"～のに","d":"형태는 비슷하지만 역접(~인데도)."}],"ex":[{"jp":"明日[あした]テストがあるので、今晩[こんばん]勉強[べんきょう]します。","ko":"내일 시험이 있어서 오늘 밤 공부합니다."},{"jp":"この靴[くつ]は高[たか]いので、買[か]いません。","ko":"이 신발은 비싸서 사지 않겠습니다."},{"jp":"雨[あめ]なので、傘[かさ]を持[も]って行[い]きましょう。","ko":"비가 오니까 우산을 가지고 갑시다."}],"dr":[{"t":"make","q":"病気だ → ～ので","a":"病気なので","hint":"명사 + だ는 だ를 な로 바꾸고 ので."},{"t":"make","q":"暑い → ～ので","a":"暑いので","hint":"い형용사는 그대로 ので."},{"t":"fill","q":"道[みち]が込[こ]んでいた（　）、遅[おく]れてしまいました。","a":"ので","opts":["ので","のに","ように","ために"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AE%E3%81%A7"],"vf":1,"u":11,"g":1,"gp":"gg_N4_07"},{"id":"g4_010","t":"名詞のために","ko":"~을/를 위해서","cat":"목적","conn":[{"w":"명사","f":"家族のために"},{"w":"동사 사전형 (목적)","f":"日本へ行くために"},{"w":"명사 (원인)","f":"台風のために中止になった"}],"rule":["명사 뒤에 の를 붙인다: 家族 + の.","그 뒤에 ために를 붙인다: 家族のために.","뒤에는 그 목적·대상을 위해 하는 행동을 놓는다(家族のために働く).","동사에 붙을 때는 の 없이 사전형 + ために(行くために)."],"why":"ため(為)는 '이익·목적'을 뜻하는 명사이고 단독으로는 잘 안 쓰여서, 명사를 이을 때 の, 목적을 표시하는 조사 に를 붙여 ために가 된다.","nu":"회화·문장 모두 쓴다. '~의 이익을 위해(家族のために)'와 '~라는 목적으로(健康のために)' 두 뜻이 있다. 명사 + ため(に)는 '~때문에'라는 원인으로도 쓰이니(台風のため) 문맥으로 구별한다. 명사에 바로 붙이는 실수(×家族ために)에 주의한다.","cmp":[{"g":"～ように","d":"ように는 가능동사·무의지 동사(見えるように 등)에 붙어 그런 상태가 되기를 바라는 목적. ために는 명사나 의지 동사에 붙는다."}],"ex":[{"jp":"子[こ]どものために、毎日[まいにち]お弁当[べんとう]を作[つく]ります。","ko":"아이를 위해 매일 도시락을 만들어요."},{"jp":"健康[けんこう]のために、毎朝[まいあさ]歩[ある]いています。","ko":"건강을 위해 매일 아침 걷고 있어요."},{"jp":"留学[りゅうがく]のために、お金[かね]をためている。","ko":"유학을 위해 돈을 모으고 있다."}],"dr":[{"t":"make","q":"試験 → '시험을 위해 공부한다'","a":"試験のために勉強する","hint":"명사 + の + ために."},{"t":"make","q":"友だち → '친구를 위해서 케이크를 만들었다'","a":"友だちのためにケーキを作った","hint":"명사 + の + ために + 행동."},{"t":"fill","q":"国[くに]の家族[かぞく]の（　）、一生懸命[いっしょうけんめい]働[はたら]いています。","a":"ために","opts":["ために","ように","あいだ","までに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%81%E3%81%AB"],"vf":1,"u":11,"g":1,"gp":"gg_N4_07"},{"id":"g4_026","t":"～ために（目的）","ko":"~하기 위해(서), ~을 위해","cat":"목적","conn":[{"w":"동사 사전형(의지 동사)","f":"合格する + ために"},{"w":"명사","f":"健康の + ために"},{"w":"(원인 용법) 동사 た형","f":"事故があった + ために"},{"w":"(원인 용법) い형용사 / な형용사","f":"忙しい + ために / 不便な + ために"}],"rule":["목적을 나타낼 때는 동사 사전형 뒤에 ため + に를 바로 붙인다(合格する + ために). 동사 형태는 바뀌지 않는다.","명사는 の를 넣어 잇는다(健康 + の + ために).","같은 ために가 た형·형용사·명사의 に붙은 원인 문장에서는 '~때문에'라는 이유가 된다(台風のために中止になった). 어느 뜻인지는 앞뒤 문맥으로 정해진다."],"why":"ため(為)는 '이익·목적, 또는 원인'을 뜻하는 명사이고, 여기에 목적을 분명히 하는 に가 붙은 형태다. 그래서 명사처럼 앞에 연체형(동사 사전형, 명사+の)이 온다.","nu":"목적의 ために는 앞뒤 주어가 같고, 앞 동사가 자기 의지로 할 수 있는 동작(의지 동사)일 때 쓴다. 見える・分かる・できる 같은 비의지 동사나 가능형(話せる)에는 ために 대신 ように를 쓴다(日本語が話せるように練習する). 원인의 ために는 다소 딱딱한 문어적 표현이다.","cmp":[{"g":"～ように","d":"가능형·비의지 동사·ない형에 붙어 '~할 수 있도록/~하지 않도록'. ために는 의지 동사 사전형."},{"g":"～おかげで / ～せいで","d":"원인 용법끼리 비교: おかげで는 좋은 결과, せいで는 나쁜 결과. ために는 중립."}],"ex":[{"jp":"大学[だいがく]に入[はい]るために、毎日[まいにち]勉強[べんきょう]しています。","ko":"대학에 들어가기 위해 매일 공부하고 있어요."},{"jp":"健康[けんこう]のために、毎朝[まいあさ]走[はし]っています。","ko":"건강을 위해 매일 아침 달리고 있어요."},{"jp":"家[いえ]を買[か]うために、お金[かね]をためています。","ko":"집을 사기 위해 돈을 모으고 있어요."}],"dr":[{"t":"make","q":"留学する → '유학하기 위해'","a":"留学するために","hint":"사전형 그대로 + ために."},{"t":"make","q":"家族 → '가족을 위해'","a":"家族のために","hint":"명사는 の + ために."},{"t":"fill","q":"車[くるま]を買[か]う（　）、アルバイトをしています。","a":"ために","opts":["ために","ように","くせに","ながら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%81%E3%81%AB","https://jplang.tufs.ac.jp/tw/bu/22/22-7.html","https://www.mangolanguages.com/resources/learn/grammar/japanese/yo-ni-and-tame-ni-how-to-say-in-order-to-in-japanese-"],"vf":1,"u":11,"g":1,"gp":"gg_N4_07"},{"id":"g4_059","t":"～ように","ko":"~하도록, ~하게끔 (목적·목표)","cat":"목적","conn":[{"w":"동사 사전형(무의지·가능형)","f":"聞こえる + ように"},{"w":"동사 가능형","f":"話せる + ように"},{"w":"동사 ない형","f":"忘れない + ように"}],"rule":["1. 바라는 결과를 나타내는 동사를 사전형 그대로 두거나 가능형·ない형으로 바꾼다.","2. ない형: 2그룹은 る를 ない로 바꾸고(忘れる→忘れない), 1그룹은 어미 う단을 あ단으로 바꾼 뒤 ない를 붙인다(書く→書かない). する→しない.","3. 그 뒤에 ように를 붙이고, 이어서 그 결과를 위해 하는 행동을 말한다(忘れないように、メモする)."],"why":"よう(様, 모양·상태)에 조사 に가 붙어 '그런 상태가 되게'라는 뜻이 된다. 앞부분은 바라는 상태, 뒷부분은 그것을 위한 노력이다.","nu":"앞에는 의지로 직접 할 수 없는 일(見える, 聞こえる, 治る), 가능형, 부정형이 온다. 의지동사의 목적(~하기 위해)은 ために를 쓴다(×行くように → 行くために). 한국어로 '~하기 위해'로만 외우면 ために와 섞어 쓰는 실수가 많다. 앞뒤 주어가 달라도 된다(子どもにも分かるように、ゆっくり話す). 명사+のように는 '~처럼'이라는 다른 용법.","cmp":[{"g":"～ために","d":"의지동사와 함께 확고한 목적을 나타낸다(大学に入るために勉強する). ～ように는 가능형·무의지동사로 바라는 결과(入れるように勉強する)."},{"g":"～のように(비유)","d":"명사에 붙어 '~처럼'. 鳥のように飛ぶ."}],"ex":[{"jp":"忘[わす]れないように、手帳[てちょう]に書[か]いておきます。","ko":"잊지 않도록 수첩에 적어 둘게요."},{"jp":"後[うし]ろの人[ひと]にも聞[き]こえるように、大[おお]きい声[こえ]で話[はな]してください。","ko":"뒤에 있는 사람에게도 들리도록 큰 소리로 말해 주세요."},{"jp":"日本語[にほんご]が話[はな]せるように、毎日[まいにち]練習[れんしゅう]しています。","ko":"일본어를 말할 수 있도록 매일 연습하고 있어요."}],"dr":[{"t":"make","q":"遅れる → (부정) ～ように","a":"遅れないように","hint":"2그룹: る → ない + ように"},{"t":"make","q":"泳ぐ → (가능형) ～ように","a":"泳げるように","hint":"ぐ → げ (え단) + る + ように"},{"t":"fill","q":"風邪[かぜ]をひかない（　）、暖[あたた]かくして寝[ね]てください。","a":"ように","opts":["ように","ために","のに","ながら"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201310.html","https://nihongokyoshi-net.com/2018/09/25/jlptn4-grammar-yooni/"],"vf":1,"u":11,"g":1,"gp":"gg_N4_07"},{"id":"g4_081","t":"～し、～し","ko":"~하고, ~하고 (이유·특징 나열)","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"降る + し"},{"w":"い형용사","f":"若い + し"},{"w":"な형용사","f":"元気だ + し"},{"w":"명사","f":"休みだ + し"}],"rule":["1. 보통형 끝에 그대로 し를 붙인다(若い→若いし).","2. な형용사와 명사는 だ를 남기고 し를 붙인다(元気だし, 休みだし).","3. 같은 방법으로 두 번째 이유·특징에도 し를 붙여 늘어놓고, 마지막에 결론을 잇는다.","4. 정중하게는 です·ます 뒤에도 붙는다(若いですし)."],"why":"","nu":"비슷한 방향의 이유나 특징을 여러 개 쌓아 '게다가'의 느낌을 준다. 하나만 쓰고 나머지를 암시할 수도 있다(雨だし、今日はやめよう). 이유 나열에서는 뒤 항목에 も를 자주 쓴다(味もいいし). 회화에서 많이 쓴다. 한국어 '-고'처럼 단순한 순서 나열(먹고 잤다)에는 쓰지 않는다.","cmp":[{"g":"～て","d":"단순 연결·순서. ～し는 이유나 평가를 강조해 쌓아 올린다."},{"g":"～から","d":"하나의 이유를 분명히 말한다. ～し는 이유가 여러 개임을 암시한다."}],"ex":[{"jp":"この店[みせ]は安[やす]いし、おいしいし、よく来[き]ます。","ko":"이 가게는 싸고 맛있어서 자주 와요."},{"jp":"今日[きょう]は雨[あめ]だし、寒[さむ]いし、家[いえ]にいよう。","ko":"오늘은 비도 오고 춥고 하니 집에 있자."},{"jp":"彼[かれ]は親切[しんせつ]だし、よく働[はたら]くし、みんなに好[す]かれている。","ko":"그는 친절하고 일도 잘해서 모두에게 사랑받는다."}],"dr":[{"t":"make","q":"静かだ → ～し","a":"静かだし","hint":"な형용사는 だ를 남기고 し를 붙인다."},{"t":"make","q":"駅から近い → ～し","a":"駅から近いし","hint":"い형용사는 그대로 し를 붙인다."},{"t":"fill","q":"この部屋[へや]は広[ひろ]い（　）、明[あか]るいし、気[き]に入[い]った。","a":"し","opts":["し","のに","ても","たら"]}],"src":["https://bunpro.jp/grammar_points/141"],"vf":1,"u":11,"g":1,"gp":"gg_N4_07"},{"id":"g4_113","t":"～ばいい","ko":"~하면 된다, ~하면 좋다 (조언·방법)","cat":"접속·조건","conn":[{"w":"1그룹 동사","f":"聞く → 聞けば + いい"},{"w":"2그룹 동사","f":"食べる → 食べれば + いい"},{"w":"する / 来る","f":"すれば / 来[く]れば + いい"},{"w":"い형용사","f":"安い → 安ければ + いい"},{"w":"な형용사·명사","f":"静かなら / 静かであれば + いい"}],"rule":["1. 1그룹 동사는 어미 う단을 え단으로 바꾸고 ば를 붙인다(聞く→聞けば).","2. 2그룹 동사는 る를 れ로 바꾸고 ば(食べる→食べれば). する→すれば, 来る→来れば.","3. 가정형 뒤에 いい를 붙인다(聞けばいい). 정중하게는 ばいいです.","4. い형용사는 い를 ければ로 바꾼다(安い→安ければいい)."],"why":"ば(~하면)＋いい(좋다)로 '~하면 좋다', 즉 그렇게 하는 것이 해결 방법이라는 뜻이 된다.","nu":"방법을 알려 주거나 조언할 때 쓴다(駅員に聞けばいいですよ). 의문형 どうすればいいですか(어떻게 하면 좋을까요)는 회화 필수 표현. 문장 끝에 ～のに를 붙인 ばいいのに는 '~하면 좋을 텐데'라는 아쉬움·불만, ～ばよかった는 후회. 윗사람에게 ばいい로 지시하면 무례하게 들릴 수 있다.","cmp":[{"g":"～たらいい","d":"뜻이 비슷하지만 ばいい보다 조금 더 강하고 분명하게 권하는 느낌이다(どうしたらいいですか)."},{"g":"～ほうがいい","d":"여러 선택지 중 더 나은 쪽을 강하게 권한다. ばいい는 '그렇게 하면 해결된다'는 방법 제시."}],"ex":[{"jp":"道[みち]がわからなければ、駅員[えきいん]に聞[き]けばいいよ。","ko":"길을 모르면 역무원에게 물어보면 돼."},{"jp":"この漢字[かんじ]はどう読[よ]めばいいですか。","ko":"이 한자는 어떻게 읽으면 됩니까?"},{"jp":"明日[あした]、天気[てんき]がよければいいね。","ko":"내일 날씨가 좋으면 좋겠다."}],"dr":[{"t":"make","q":"待つ → ～ばいい","a":"待てばいい","hint":"つ를 て로(え단) 바꾸고 ば + いい."},{"t":"make","q":"寝る → ～ばいい","a":"寝ればいい","hint":"2그룹은 る를 れ로 + ば + いい."},{"t":"fill","q":"このボタンを押[お]せ（　）いいです。","a":"ば","opts":["ば","て","たら","と"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%B0%E3%81%84%E3%81%84"],"vf":1,"u":11,"g":1,"gp":"gg_N4_08"},{"id":"g4_079","t":"～けれど","ko":"~지만, ~인데","cat":"역접","conn":[{"w":"동사 보통형","f":"行く + けれど"},{"w":"い형용사","f":"高い + けれど"},{"w":"な형용사","f":"静かだ + けれど"},{"w":"명사","f":"学生だ + けれど"},{"w":"정중형","f":"行きます + けれど"}],"rule":["1. 앞 문장의 끝 형태를 그대로 두고 뒤에 けれど를 붙인다(高い→高いけれど).","2. な형용사와 명사는 だ를 남긴 채 붙인다(静かだけれど, 学生だけれど).","3. 과거·부정·정중형 뒤에도 그대로 붙는다(行ったけれど, 高いですけれど).","4. けれど 뒤에 쉼표를 찍고 앞과 반대되거나 예상과 다른 내용을 잇는다."],"why":"","nu":"뜻은 が와 같은 역접이며 정중함은 けれども > けれど > けど 순서로, けど가 가장 회화적이다. 역접 외에 '~는데' 같은 서론(すみませんけれど、…)이나 문장 끝에서 말을 부드럽게 흐리는 용법(行きたいんですけれど…)도 있다. 한국어 '-는데'처럼 だ를 빼고 静かけれど라고 쓰는 실수에 주의.","cmp":[{"g":"～が","d":"같은 역접이지만 글이나 격식 있는 말에 더 어울린다."},{"g":"～のに","d":"예상과 다른 결과에 대한 불만·의외의 감정이 강하고, 뒤에 명령·의뢰를 쓸 수 없다."}],"ex":[{"jp":"この店[みせ]は高[たか]いけれど、料理[りょうり]がおいしい。","ko":"이 가게는 비싸지만 요리가 맛있다."},{"jp":"日本語[にほんご]を毎日[まいにち]勉強[べんきょう]しているけれど、なかなか上手[じょうず]にならない。","ko":"일본어를 매일 공부하고 있지만 좀처럼 늘지 않는다."},{"jp":"今日[きょう]は日曜日[にちようび]だけれど、会社[かいしゃ]に行[い]きます。","ko":"오늘은 일요일이지만 회사에 갑니다."}],"dr":[{"t":"make","q":"寒い → ～けれど","a":"寒いけれど","hint":"い형용사는 그대로 けれど를 붙인다."},{"t":"make","q":"便利だ → ～けれど","a":"便利だけれど","hint":"な형용사는 だ를 남기고 けれど를 붙인다."},{"t":"fill","q":"薬[くすり]を飲[の]んだ（　）、まだ頭[あたま]が痛[いた]い。","a":"けれど","opts":["けれど","から","ので","ために"]}],"src":["https://bunpro.jp/ja/grammar_points/361"],"vf":1,"u":11,"g":1,"gp":"gg_N4_08"},{"id":"g4_097","t":"～ても／～でも","ko":"~해도, ~라도","cat":"역접","conn":[{"w":"1그룹 동사","f":"降る → 降って + も"},{"w":"1그룹 동사(ん음편)","f":"読む → 読んで + も"},{"w":"2그룹·する·来る","f":"見て / して / 来て + も"},{"w":"い형용사","f":"高い → 高く + ても"},{"w":"な형용사·명사","f":"静か / 雨 + でも"}],"rule":["1. 동사를 て형으로 바꾼다(降る→降って, 書く→書いて, 食べる→食べて).","2. て형 뒤에 も를 붙인다(降って+も). で로 끝나는 て형은 でも(読んで→読んでも).","3. い형용사는 い를 くて로 바꾸고 も(高い→高くても). いい는 よくても.","4. な형용사·명사는 だ 대신 でも를 붙인다(静かでも, 雨でも). 부정은 なくても(行かなくても)."],"why":"て형(접속)에 '~도'를 뜻하는 조사 も가 붙어 '그렇게 하더라도'라는 양보가 된다.","nu":"앞 조건이 성립해도 뒤 결과는 바뀌지 않는다는 뜻. 뒤에 과거가 오면 실제 일(いくら呼んでも、来なかった). 의문사와 함께 쓰면 '아무리/무엇을 ~해도'(何を食べても). 한국어 '~라도'에 끌려 동사에 ×降るでも라고 하는 실수에 주의.","cmp":[{"g":"～のに","d":"이미 일어난 사실에 대한 불만·의외. ても는 가정(아직 안 일어난 일)에도 쓴다."},{"g":"～ても いい","d":"ても에 いい가 붙은 허가 표현. 단독 ても는 양보."}],"ex":[{"jp":"雨[あめ]が降[ふ]っても、試合[しあい]はあります。","ko":"비가 와도 시합은 있습니다."},{"jp":"この靴[くつ]は高[たか]くても買[か]いたい。","ko":"이 신발은 비싸도 사고 싶다."},{"jp":"日曜日[にちようび]でも、父[ちち]は仕事[しごと]に行[い]きます。","ko":"일요일이라도 아버지는 일하러 가십니다."}],"dr":[{"t":"make","q":"待つ → ～ても","a":"待っても","hint":"1그룹 つ → って, 그 뒤에 も."},{"t":"make","q":"寒い → ～ても","a":"寒くても","hint":"い형용사 い → くて, 그 뒤에 も."},{"t":"fill","q":"いくら練習[れんしゅう]し（　）、上手[じょうず]にならない。","a":"ても","opts":["ても","たら","ので","から"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%82%82"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_112","t":"～のに","ko":"~는데도, ~인데 (기대와 다른 결과)","cat":"역접","conn":[{"w":"동사 보통형","f":"約束した + のに"},{"w":"い형용사","f":"寒い + のに"},{"w":"な형용사","f":"静か + な + のに"},{"w":"명사","f":"日曜日 + な + のに"}],"rule":["1. 동사·い형용사는 보통형에 그대로 のに를 붙인다(約束する→約束した→約束したのに).","2. 명사·な형용사의 현재 긍정은 だ를 な로 바꾼다(日曜日だ→日曜日なのに).","3. 뒤 문장에는 앞에서 기대한 것과 반대되는 실제 결과가 온다(約束したのに、来なかった)."],"why":"형식명사 の에 조사 に가 결합한 형태로, の 앞에서 だ가 な가 되는 규칙이 그대로 적용된다.","nu":"의외·불만·아쉬움의 감정이 담긴다. 뒤 문장은 이미 일어난 사실이어야 하며 명령·의지·권유는 올 수 없다(×雨なのに、行こう → 雨だけど、行こう). 문장 끝에 쓰면 '~했으면 좋았을 텐데' 같은 아쉬움(言ってくれればよかったのに). 별개 용법으로 동사 사전형＋のに가 '~하는 데(에)'라는 용도를 나타내기도 한다(勉強するのに静かな所が必要だ).","cmp":[{"g":"～けど / ～が","d":"단순 역접으로 감정이 실리지 않고 뒤에 의지·권유도 올 수 있다."},{"g":"～ので","d":"순접 이유(~이므로). のに는 역접."}],"ex":[{"jp":"約束[やくそく]したのに、友達[ともだち]は来[こ]なかった。","ko":"약속했는데 친구는 오지 않았다."},{"jp":"もう4月[しがつ]なのに、まだ寒[さむ]い。","ko":"벌써 4월인데 아직 춥다."},{"jp":"この店[みせ]は安[やす]いのに、とてもおいしい。","ko":"이 가게는 싼데도 아주 맛있다."}],"dr":[{"t":"make","q":"日曜日だ → ～のに","a":"日曜日なのに","hint":"명사 + だ는 だ를 な로 바꾸고 のに."},{"t":"make","q":"たくさん食べた → ～のに","a":"たくさん食べたのに","hint":"동사 보통형(과거)에 그대로 のに."},{"t":"fill","q":"一生懸命[いっしょうけんめい]勉強[べんきょう]した（　）、試験[しけん]に落[お]ちた。","a":"のに","opts":["のに","ので","から","ために"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AE%E3%81%AB"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_002","t":"AはBほど～ありません","ko":"A는 B만큼 ~하지 않습니다","cat":"비교·정도","conn":[{"w":"B 명사 + ほど","f":"昨日ほど"},{"w":"い형용사 (い→く + ありません)","f":"寒くありません"},{"w":"な형용사 (+ではありません)","f":"昨日ほど暇ではありません"},{"w":"동사 (ません형)","f":"兄ほど食べません"},{"w":"いい → よく","f":"前ほどよくありません"}],"rule":["い형용사는 어미 い를 く로 바꾸고 ありません을 붙인다(寒い → 寒くありません).","な형용사·명사는 ではありません(じゃありません)을 붙이고, 동사는 ます를 ません으로 바꾼다.","비교 대상 B 뒤에 ほど를 두고 그 부정 표현 앞에 놓는다: A は B ほど 寒くありません.","いい는 よくありません으로 바뀐다."],"why":"ほど(程)는 '정도'라는 뜻의 명사에서 온 말이라 'B 정도로는 ~하지 않다', 즉 B의 수준에 미치지 못한다는 뜻이 된다.","nu":"정중체(です・ます) 문장으로, 같은 뜻의 くないです보다 조금 더 격식 있게 들린다. 반드시 부정 술어와 함께 쓰며, 'AはBほど寒いです'처럼 긍정으로는 쓰지 않는다. 기준이 되는 쪽(정도가 더 큰 쪽)이 ほど 앞에 온다. 한국어 '만큼'을 직역해 긍정문에 ほど를 넣는 실수가 많다.","cmp":[{"g":"AはBより～","d":"긍정 비교 'A가 B보다 더 ~'. ほど～ない는 'A가 B에 못 미친다'는 부정 비교."},{"g":"AはBほど～ない","d":"같은 뜻의 보통체. ありません은 정중체."}],"ex":[{"jp":"今日[きょう]は昨日[きのう]ほど寒[さむ]くありません。","ko":"오늘은 어제만큼 춥지 않습니다."},{"jp":"この町[まち]は東京[とうきょう]ほどにぎやかではありません。","ko":"이 동네는 도쿄만큼 번화하지 않습니다."},{"jp":"わたしは兄[あに]ほどたくさん食[た]べません。","ko":"저는 형만큼 많이 먹지 않습니다."}],"dr":[{"t":"make","q":"高い → 정중 부정형","a":"高くありません","hint":"어미 い를 く로 바꾸고 ありません을 붙인다."},{"t":"make","q":"この店 / あの店 / 安い → '이 가게는 저 가게만큼 싸지 않습니다'","a":"この店はあの店ほど安くありません","hint":"A は B ほど + 安くありません."},{"t":"fill","q":"今年[ことし]の夏[なつ]は去年[きょねん]（　）暑[あつ]くありません。","a":"ほど","opts":["ほど","より","まで","しか"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BB%E3%81%A9%EF%BD%9E%E3%81%AA%E3%81%84"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_003","t":"AはBほど～ない","ko":"A는 B만큼 ~하지 않다","cat":"비교·정도","conn":[{"w":"B 명사 + ほど","f":"兄ほど"},{"w":"い형용사 (い→くない)","f":"高くない"},{"w":"な형용사 (+じゃない/ではない)","f":"兄ほど上手じゃない"},{"w":"동사 (ない형)","f":"兄ほど食べない"},{"w":"いい → よくない","f":"前ほどよくない"}],"rule":["い형용사는 어미 い를 く로 바꾸고 ない를 붙인다(高い → 高くない).","な형용사는 じゃない(ではない)를, 동사는 ない형을 쓴다.","기준 B 뒤에 ほど를 붙여 부정 술어 앞에 둔다: わたしは 兄ほど 背が高くない.","いい는 よくない가 된다."],"why":"ほど(程)는 '정도'를 뜻하는 명사라서 'B의 정도까지는 ~하지 않다'는 뜻이 된다.","nu":"보통체(반말) 문장. 정중하게는 くないです 또는 くありません으로 끝낸다. 부정 술어와만 쓰고, 기준이 되는 더 큰 쪽이 ほど 앞에 온다. '彼は私ほど背が高い'처럼 긍정으로 쓰면 틀린다. 동사도 '彼ほど走れない'처럼 가능 부정형이 흔하다.","cmp":[{"g":"AよりBのほうが～","d":"B가 더 ~하다고 긍정으로 비교. ほど～ない는 A가 못 미친다고 부정으로 말한다."},{"g":"あまり～ない","d":"비교 대상 없이 '그다지 ~않다'. ほど～ない는 B라는 기준이 있다."}],"ex":[{"jp":"わたしは兄[あに]ほど背[せ]が高[たか]くない。","ko":"나는 형만큼 키가 크지 않아."},{"jp":"このりんごはあのりんごほど甘[あま]くない。","ko":"이 사과는 저 사과만큼 달지 않아."},{"jp":"わたしは田中[たなか]さんほど速[はや]く走[はし]れない。","ko":"나는 다나카 씨만큼 빨리 못 달려."}],"dr":[{"t":"make","q":"甘い → 보통체 부정형","a":"甘くない","hint":"어미 い를 く로 바꾸고 ない."},{"t":"make","q":"きれいだ → '저 방만큼 깨끗하지 않다' (この部屋 / あの部屋)","a":"この部屋はあの部屋ほどきれいじゃない","hint":"な형용사는 じゃない, B 뒤에 ほど."},{"t":"fill","q":"弟[おとうと]は兄[あに]（　）勉強[べんきょう]ができない。","a":"ほど","opts":["ほど","より","とか","だけ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BB%E3%81%A9%EF%BD%9E%E3%81%AA%E3%81%84"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_004","t":"AよりBのほうが～","ko":"A보다 B 쪽이 (더) ~","cat":"비교·정도","conn":[{"w":"명사 (B + のほうが)","f":"冬より夏のほうが暑い"},{"w":"동사 사전형 (の 없이 + ほうが)","f":"バスで行くより歩くほうが早い"},{"w":"い형용사 (+ ほうが)","f":"大きいより小さいほうがいい"},{"w":"な형용사 (な + ほうが)","f":"にぎやかなより静かなほうがいい"}],"rule":["덜한 쪽 A 뒤에 より(보다)를 붙인다.","더한 쪽 B가 명사면 のほうが, 동사·형용사면 の 없이 ほうが(な형용사는 な + ほうが)를 붙인다.","끝에 형용사 등 술어를 둔다: 冬より夏のほうが暑い."],"why":"ほう(方)는 '쪽, 편'이라는 뜻이고 より는 비교의 기준을 나타내는 조사라서 'A보다 B 쪽이 ~하다'가 된다.","nu":"회화·문장 모두 쓰는 기본 비교 표현. 'AとBとどちらが～ですか'의 답으로 자주 쓴다. 어순을 바꿔 'BのほうがAより～'도 가능하다. 동사 앞에 の를 넣는 실수(歩くのほうが)가 많다. 한국어 '더'를 직역해 もっと를 꼭 넣을 필요는 없다.","cmp":[{"g":"AはBより～","d":"A가 주제. 'A는 B보다 ~하다'. のほうが는 둘 중 한쪽을 골라 강조한다."},{"g":"AはBほど～ない","d":"A가 B에 못 미친다는 부정 비교."}],"ex":[{"jp":"冬[ふゆ]より夏[なつ]のほうが暑[あつ]いです。","ko":"겨울보다 여름이 더 더워요."},{"jp":"バスより電車[でんしゃ]のほうが速[はや]いですよ。","ko":"버스보다 전철이 더 빨라요."},{"jp":"一人[ひとり]で行[い]くより、みんなで行[い]くほうが楽[たの]しいです。","ko":"혼자 가는 것보다 다 같이 가는 게 더 즐거워요."}],"dr":[{"t":"make","q":"りんご / バナナ / 甘い → '사과보다 바나나가 더 달아요'","a":"りんごよりバナナのほうが甘いです","hint":"A + より, 명사 B + のほうが."},{"t":"make","q":"タクシーで行く / 歩く / 早い → '택시로 가는 것보다 걷는 게 빨라요'","a":"タクシーで行くより歩くほうが早いです","hint":"동사는 사전형 + ほうが (の 없음)."},{"t":"fill","q":"肉[にく]より魚[さかな]の（　）が好[す]きです。","a":"ほう","opts":["ほう","ほど","とか","まで"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%88%E3%82%8A-%E3%81%AE%E3%81%BB%E3%81%86%E3%81%8C"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_082","t":"～すぎる","ko":"너무 ~하다, 지나치게 ~하다","cat":"비교·정도","conn":[{"w":"동사 ます형","f":"食べ(ます) + すぎる"},{"w":"い형용사","f":"高(い) + すぎる"},{"w":"な형용사","f":"静か + すぎる"},{"w":"예외","f":"いい → よすぎる, ない → なさすぎる"}],"rule":["1. 동사는 ます형에서 ます를 떼고 すぎる를 붙인다(食べる→食べ→食べすぎる, 飲む→飲み→飲みすぎる).","2. い형용사는 끝의 い를 떼고 붙인다(高い→高すぎる).","3. な형용사는 어간에 바로 붙인다(静か→静かすぎる).","4. いい는 よすぎる, ない는 なさすぎる가 된다.","5. すぎる 자체는 2그룹 동사로 활용한다(食べすぎた, 高すぎて)."],"why":"過ぎる(지나가다·넘다)가 다른 말 뒤에 붙어 '정도를 넘다'라는 뜻이 된 것이다.","nu":"대개 정도가 지나쳐 곤란하다는 부정적 평가다. 회화에서는 칭찬에도 쓰지만(かわいすぎる) 기본은 문제가 있다는 느낌. 명사형 すぎ도 많이 쓴다(食べすぎ, 飲みすぎ). 한국어 '너무'를 직역해 とても로 바꾸는 실수 주의: とても는 단순한 강조로 부정 뉘앙스가 없다.","cmp":[{"g":"とても～","d":"정도가 높다는 강조일 뿐. ～すぎる는 적정선을 넘어 문제가 된다는 뜻."}],"ex":[{"jp":"昨日[きのう]、ケーキを食[た]べすぎて、おなかが痛[いた]い。","ko":"어제 케이크를 너무 많이 먹어서 배가 아프다."},{"jp":"この靴[くつ]は高[たか]すぎて、買[か]えません。","ko":"이 신발은 너무 비싸서 살 수 없어요."},{"jp":"この町[まち]は静[しず]かすぎて、ちょっとさびしい。","ko":"이 마을은 너무 조용해서 좀 쓸쓸하다."}],"dr":[{"t":"make","q":"飲む → ～すぎる","a":"飲みすぎる","hint":"ます형 飲み에서 ます를 떼고 すぎる를 붙인다."},{"t":"make","q":"難しい → ～すぎる","a":"難しすぎる","hint":"い형용사는 끝의 い를 떼고 すぎる를 붙인다."},{"t":"fill","q":"この荷物[にもつ]は重[おも]（　）、一人[ひとり]で持[も]てない。","a":"すぎて","opts":["すぎて","らしくて","ながら","たがって"]}],"src":["https://nihongokyoshi-net.com/?p=7291","https://www.tofugu.com/japanese-grammar/sugiru/"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_077","t":"～かもしれない","ko":"~일지도 모른다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降る + かもしれない"},{"w":"い형용사","f":"寒い + かもしれない"},{"w":"な형용사","f":"暇 + かもしれない (だ 없음)"},{"w":"명사","f":"雨 + かもしれない (だ 없음)"}],"rule":["1. 추측하는 내용을 보통형으로 만든다: 雨が降る.","2. 끝에 かもしれない를 붙인다: 降るかもしれない.","3. 명사·な형용사는 だ를 떼고 바로 붙인다: 雨だ → 雨かもしれない.","4. 정중체는 ない를 ません으로 바꾼 かもしれません, 회화에서는 줄여서 かも."],"why":"か(~인지) + も(~도) + しれない(알 수 없다)로 '그럴지도 알 수 없다', 즉 가능성이 있다는 뜻이 된다.","nu":"확신도는 낮다(반반 정도). だろう / でしょう보다 확신이 약하다. 명사·な형용사 뒤에 だ를 넣어 ×雨だかもしれない라고 하는 실수가 많다. かも는 친한 사이의 회화체, かもしれません은 정중체.","cmp":[{"g":"～でしょう / ～だろう","d":"'아마 ~일 것이다'로 확신이 더 높다."}],"ex":[{"jp":"午後[ごご]は雨[あめ]かもしれないから、傘[かさ]を持[も]って行[い]こう。","ko":"오후에는 비가 올지도 모르니까 우산을 가져가자."},{"jp":"あの店[みせ]は今日[きょう]休[やす]みかもしれません。","ko":"그 가게는 오늘 쉬는 날일지도 몰라요."},{"jp":"この服[ふく]、ちょっと高[たか]いかもしれない。","ko":"이 옷, 좀 비쌀지도 모른다."}],"dr":[{"t":"make","q":"彼は病気だ → ～かもしれない","a":"彼は病気かもしれない","hint":"명사 뒤 だ를 떼고 + かもしれない"},{"t":"make","q":"間に合わない → ～かもしれません","a":"間に合わないかもしれません","hint":"보통형 그대로 + かもしれません"},{"t":"fill","q":"空[そら]が暗[くら]いから、雨[あめ]が降[ふ]る（　）。","a":"かもしれない","opts":["かもしれない","ことにする","ところだった","ばかりだ"]}],"src":["https://bunpro.jp/grammar_points/かもしれない"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_084","t":"～そうだ","ko":"~해 보인다, ~할 것 같다 (양태)","cat":"추량·전문","conn":[{"w":"동사 ます형","f":"降り(ます) + そうだ"},{"w":"い형용사","f":"おいし(い) + そうだ"},{"w":"な형용사","f":"元気 + そうだ"},{"w":"예외","f":"いい → よさそうだ, ない → なさそうだ"}],"rule":["1. 동사는 ます를 떼고 そうだ를 붙인다(降る→降り→降りそうだ).","2. い형용사는 끝의 い를 떼고 붙인다(おいしい→おいしそうだ).","3. な형용사는 어간에 바로 붙인다(元気→元気そうだ).","4. いい는 よさそうだ, ない는 なさそうだ가 된다(형용사 부정: おいしくない→おいしくなさそうだ).","5. 명사 앞에서는 そうな, 동사 앞에서는 そうに로 바뀐다(おいしそうなケーキ, おいしそうに食べる)."],"why":"","nu":"눈으로 보고 받은 인상(형용사)이나 곧 일어날 것 같은 조짐(동사)을 말한다. 동사에 붙으면 '곧 ~할 것 같다'(雨が降りそうだ). 보면 바로 아는 성질(きれい, 赤い 등)에는 보통 쓰지 않는다. 보통형 + そうだ(降るそうだ)는 '~라고 한다'는 전문(전해 들음)으로 뜻이 전혀 다르니 접속을 꼭 구별할 것. 명사에는 직접 붙지 않는다.","cmp":[{"g":"～そうだ(전문)","d":"보통형에 붙어 '~라고 한다'. 양태 そうだ는 ます형·형용사 어간에 붙어 '~해 보인다'."},{"g":"～ようだ","d":"여러 정황으로 판단한 추측. 양태 そうだ는 겉모습에서 받은 직접적인 인상."}],"ex":[{"jp":"このケーキ、おいしそうですね。","ko":"이 케이크 맛있어 보이네요."},{"jp":"空[そら]が暗[くら]いですね。雨[あめ]が降[ふ]りそうです。","ko":"하늘이 어둡네요. 비가 올 것 같아요."},{"jp":"田中[たなか]さんは元気[げんき]そうでした。","ko":"다나카 씨는 건강해 보였어요."}],"dr":[{"t":"make","q":"高い → ～そうだ","a":"高そうだ","hint":"い형용사는 い를 떼고 そうだ를 붙인다."},{"t":"make","q":"いい → ～そうだ","a":"よさそうだ","hint":"いい는 예외로 よさ + そうだ."},{"t":"fill","q":"あの子[こ]はとても楽[たの]し（　）に遊[あそ]んでいる。","a":"そう","opts":["そう","らしい","よう","みたい"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201012.html"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_091","t":"～だろう","ko":"~겠지, ~일 것이다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降る / 降った + だろう"},{"w":"い형용사","f":"忙しい + だろう"},{"w":"な형용사(だ 탈락)","f":"静か + だろう"},{"w":"명사(だ 탈락)","f":"雨 + だろう"}],"rule":["1. 동사·い형용사는 보통형 그대로 뒤에 だろう를 붙인다(降る→降るだろう, 忙しい→忙しいだろう). い는 떼지 않는다.","2. 명사·な형용사는 단정의 だ를 だろう로 바꾼다(雨だ→雨だろう, 静かだ→静かだろう).","3. 과거·부정도 보통형으로 만든 뒤 붙인다(降った+だろう, 来ない+だろう)."],"why":"だろう는 단정의 だ가 활용한 추측 형태이다. 그래서 명사·な형용사 뒤에서는 だ 자리에 그대로 들어간다.","nu":"でしょう의 보통체로 혼잣말·남성적 회화·문장체(신문, 논문)에 쓴다. 여성 회화에서는 でしょう나 かな를 더 많이 쓴다. 끝을 올려 だろう?라고 하면 '~지?' 하는 확인이 된다. 한국어 화자는 い형용사의 い를 떼는(×忙しだろう) 실수를 조심.","cmp":[{"g":"～でしょう","d":"뜻은 같고 정중체다. 윗사람이나 일기 예보 등에는 でしょう."},{"g":"～かもしれない","d":"가능성이 반반 정도로 더 낮다. だろう는 말하는 사람이 꽤 그렇다고 믿는 추측."}],"ex":[{"jp":"明日[あした]はたぶん雨[あめ]だろう。","ko":"내일은 아마 비가 오겠지."},{"jp":"あの店[みせ]は今日[きょう]も忙[いそが]しいだろう。","ko":"저 가게는 오늘도 바쁘겠지."},{"jp":"彼[かれ]はもう家[いえ]に着[つ]いただろう。","ko":"그는 이미 집에 도착했겠지."}],"dr":[{"t":"make","q":"寒い → ～だろう","a":"寒いだろう","hint":"い형용사는 い를 그대로 두고 だろう를 붙인다."},{"t":"make","q":"学生だ → ～だろう","a":"学生だろう","hint":"명사 뒤의 だ를 だろう로 바꾼다."},{"t":"fill","q":"空[そら]が暗[くら]いから、もうすぐ雨[あめ]が降[ふ]る（　）。","a":"だろう","opts":["だろう","らしい","ようだ","そうだ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A0%E3%82%8D%E3%81%86"],"vf":1,"u":12,"g":1,"gp":"gg_N4_08"},{"id":"g4_094","t":"～でしょう","ko":"~겠지요, ~일 것입니다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降る / 降った + でしょう"},{"w":"い형용사","f":"寒い + でしょう"},{"w":"な형용사(だ 탈락)","f":"元気 + でしょう"},{"w":"명사(だ 탈락)","f":"晴れ + でしょう"}],"rule":["1. 동사·い형용사는 보통형 뒤에 でしょう를 붙인다(降る→降るでしょう, 寒い→寒いでしょう). ます형이 아니다.","2. 명사·な형용사는 だ를 빼고 でしょう를 붙인다(晴れだ→晴れでしょう).","3. 과거·부정도 보통형으로 만든 뒤 붙인다(行かない+でしょう)."],"why":"でしょう는 정중한 です가 활용한 추측 형태이다. だろう를 정중하게 한 형태라서 접속이 だろう와 같다.","nu":"정중체 추측으로 일기 예보에서 늘 쓴다(晴れるでしょう). 끝을 올리면 '~죠?' 하는 확인이 된다(これ、おいしいでしょう？). 회화에서는 でしょ로 줄기도 한다. ×降りますでしょう처럼 ます형에 붙이는 실수가 많다.","cmp":[{"g":"～だろう","d":"같은 뜻의 보통체. 혼잣말이나 글에 쓴다."},{"g":"～と思います","d":"자기 생각을 말하는 표현. でしょう는 화자 의견보다 예측·추측의 느낌."}],"ex":[{"jp":"明日[あした]は全国[ぜんこく]で晴[は]れるでしょう。","ko":"내일은 전국적으로 맑겠습니다."},{"jp":"山[やま]の上[うえ]は寒[さむ]いでしょう。","ko":"산 위는 춥겠지요."},{"jp":"田中[たなか]さんは今日[きょう]休[やす]みでしょう。","ko":"다나카 씨는 오늘 쉬는 날이겠지요."}],"dr":[{"t":"make","q":"降る → ～でしょう","a":"降るでしょう","hint":"동사 보통형 뒤에 でしょう."},{"t":"make","q":"静かだ → ～でしょう","a":"静かでしょう","hint":"な형용사는 だ를 빼고 でしょう."},{"t":"fill","q":"明日[あした]は雨[あめ]が降[ふ]る（　）。傘[かさ]を持[も]って行[い]ってください。","a":"でしょう","opts":["でしょう","ましょう","ください","なさい"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A7%E3%81%97%E3%82%87%E3%81%86"],"vf":1,"u":13,"g":1,"gp":"gg_N4_08"},{"id":"g4_102","t":"～という","ko":"~라고 한다, ~라는","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"雨が降る + という"},{"w":"い형용사","f":"おもしろい + という"},{"w":"な형용사(だ)","f":"有名だ + という"},{"w":"명사(だ)","f":"病気だ + という"},{"w":"인용문","f":"「好きだ」 + と言った"}],"rule":["1. 들은 내용을 보통형으로 끝낸다(雨が降る).","2. 그 뒤에 という를 붙이면 '~라고 한다'는 전문이 된다(雨が降る+という).","3. 명사를 이어 붙이면 '~라는 (소문·평판)'이 된다(おもしろい+という+評判).","4. 누가 말했는지 밝히는 직접·간접 인용은 と言う(言った)로 쓴다(「好きだ」と言った)."],"why":"인용 조사 と + 言う(말하다)에서 나왔다.","nu":"문장 끝의 전문 という는 신문·이야기 등의 문어체다(昔、ここに城があったという). 회화에서는 そうだ·らしい·って를 쓴다. 특정 인물의 발언은 と言っていた / と言った로 표현한다.","cmp":[{"g":"～そうだ(전문)","d":"회화·글 모두에 쓰는 일반적인 전문. 문말 という는 더 문어적이고 오래된 이야기에 잘 쓴다."},{"g":"～って","d":"회화의 전문(雨が降るって)."}],"ex":[{"jp":"この町[まち]には昔[むかし]、大[おお]きいお寺[てら]があったという。","ko":"이 마을에는 옛날에 큰 절이 있었다고 한다."},{"jp":"あの店[みせ]のラーメンはおいしいという評判[ひょうばん]です。","ko":"저 가게 라멘은 맛있다는 평판입니다."},{"jp":"先生[せんせい]は「明日[あした]テストをする」と言[い]いました。","ko":"선생님은 '내일 시험을 본다'고 말씀하셨습니다."}],"dr":[{"t":"make","q":"雪が降った → ～という","a":"雪が降ったという","hint":"보통형 과거 그대로 という를 붙인다."},{"t":"make","q":"有名だ / 話 → ～という","a":"有名だという話","hint":"보통형(だ) + という + 명사."},{"t":"fill","q":"この池[いけ]には大[おお]きな魚[さかな]がいる（　）。","a":"という","opts":["という","ように","ために","ながら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86-called","https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86%E3%81%93%E3%81%A8%E3%81%A0"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_117","t":"～みたいだ","ko":"~인 것 같다; ~같다(비유)","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降る + みたいだ"},{"w":"い형용사","f":"高い + みたいだ"},{"w":"な형용사","f":"暇 + みたいだ"},{"w":"명사","f":"雨 + みたいだ"}],"rule":["1. 동사·い형용사는 보통형에 그대로 붙인다(降るみたいだ, 高いみたいだ).","2. 명사·な형용사는 だ를 빼고 바로 붙인다(雨だ → 雨みたいだ, 暇だ → 暇みたいだ). の나 な는 넣지 않는다.","3. みたいだ 자체는 な형용사처럼 활용한다(みたいな＋명사, みたいに＋동사, 정중형 みたいです)."],"why":"","nu":"보거나 들은 것을 근거로 한 추측(雨みたいだ: 비가 오는 것 같다)과 비유(子どもみたいだ: 아이 같다) 두 가지로 쓴다. ようだ와 뜻이 거의 같지만 みたいだ는 회화체, ようだ는 문장체·격식에 가깝다. ×雨のみたいだ, ×暇なみたいだ처럼 の・な를 넣는 것은 흔한 실수다.","cmp":[{"g":"～ようだ","d":"뜻은 같지만 문장체・격식. 명사는 の, な형용사는 な를 넣는다(雨のようだ, 暇なようだ)."},{"g":"～そうだ(양태)","d":"겉모습을 보고 바로 판단(おいしそうだ). みたいだ는 여러 근거로 추측."}],"ex":[{"jp":"外[そと]は雨[あめ]みたいだね。","ko":"밖에 비가 오는 것 같네."},{"jp":"田中[たなか]さんは今日[きょう]忙[いそが]しいみたいです。","ko":"다나카 씨는 오늘 바쁜 것 같아요."},{"jp":"この部屋[へや]、ホテルみたいにきれいだね。","ko":"이 방, 호텔처럼 깨끗하네."}],"dr":[{"t":"make","q":"暇だ → ～みたいだ","a":"暇みたいだ","hint":"な형용사는 だ를 빼고 みたいだ를 붙인다."},{"t":"make","q":"もう帰った → ～みたいだ","a":"もう帰ったみたいだ","hint":"동사 보통형(과거) 뒤에 그대로 붙인다."},{"t":"fill","q":"電気[でんき]が消[き]えている。田中[たなか]さんはもう帰[かえ]った（　）。","a":"みたいだ","opts":["みたいだ","までに","ながら","ために"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BF%E3%81%9F%E3%81%84"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_119","t":"～ようだ","ko":"~인 것 같다, ~인 듯하다; ~같다(비유)","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降る + ようだ"},{"w":"い형용사","f":"おいしい + ようだ"},{"w":"な형용사","f":"元気な + ようだ"},{"w":"명사","f":"病気の + ようだ"}],"rule":["1. 동사·い형용사는 보통형에 그대로 붙인다(降るようだ, おいしいようだ).","2. な형용사는 だ를 な로 바꾸어 붙인다(元気だ → 元気なようだ).","3. 명사는 だ를 빼고 の를 넣어 붙인다(病気だ → 病気のようだ).","4. ようだ 자체는 な형용사처럼 활용한다(ような＋명사, ように＋동사, 정중형 ようです)."],"why":"","nu":"보거나 듣거나 느낀 것을 근거로 한 말하는 사람의 추측, 또는 비유(夢のようだ: 꿈만 같다)에 쓴다. みたいだ보다 딱딱하고 문장체·격식 표현에 가깝다. 명사에 の를 빠뜨리는 실수(×病気ようだ)에 주의.","cmp":[{"g":"～みたいだ","d":"뜻은 같지만 회화체. 명사・な형용사에 직접 붙는다(病気みたいだ)."},{"g":"～らしい","d":"주로 남에게서 들은 정보에 근거한 추측・전문."}],"ex":[{"jp":"彼[かれ]は元気[げんき]がないようだ。","ko":"그는 기운이 없는 것 같다."},{"jp":"山田[やまだ]さんは風邪[かぜ]のようです。","ko":"야마다 씨는 감기인 것 같습니다."},{"jp":"この店[みせ]は日曜日[にちようび]は静[しず]かなようです。","ko":"이 가게는 일요일에는 조용한 것 같습니다."}],"dr":[{"t":"make","q":"病気だ → ～ようだ","a":"病気のようだ","hint":"명사는 だ를 빼고 の를 넣어 ようだ."},{"t":"make","q":"静かだ → ～ようだ","a":"静かなようだ","hint":"な형용사는 だ를 な로 바꾸고 ようだ."},{"t":"fill","q":"顔[かお]が赤[あか]い。熱[ねつ]がある（　）。","a":"ようだ","opts":["ようだ","までに","ながら","しか"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%88%E3%81%86%E3%81%A0"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_007","t":"～しか～ない","ko":"~밖에 ~않다, ~뿐이다","cat":"강조·한정","conn":[{"w":"명사","f":"リンゴしか食べない"},{"w":"수량사","f":"100円しかない"},{"w":"명사+조사(に・で・と 등)","f":"日曜日にしか会えない"},{"w":"동사 사전형 (관용형 しかない)","f":"行くしかない"}],"rule":["명사 바로 뒤에 しか를 붙인다.","が・を는 しか로 바뀌어 사라진다(リンゴを → リンゴしか). に・で・と・から 등은 남기고 그 뒤에 しか를 붙인다(東京にしか).","뒤의 술어는 반드시 부정형으로 끝낸다: 食べる → 食べない(어미 る를 빼고 ない).","동사 사전형 + しかない는 '~할 수밖에 없다'는 별도 관용 표현이다."],"why":"しか 자체가 '그것 이외에는'이라는 뜻을 담고 있어서, 뒤를 부정형으로 닫아야 '그것 말고는 없다 = 그것뿐'이라는 의미가 완성된다.","nu":"회화·문장 모두 쓴다. '적다·부족하다'는 아쉬운 느낌이 강하다. 한국어 '~밖에'와 같은 구조라 이해는 쉽지만, 긍정문(×リンゴしか食べる)으로 쓰는 실수가 많다. 반드시 부정형으로 끝낸다.","cmp":[{"g":"～だけ","d":"だけ는 긍정문·부정문 모두 가능하고 단순히 범위를 한정한다. しか～ない는 부정문 전용이고 '그것밖에 없다'는 부족감을 강조한다."}],"ex":[{"jp":"財布[さいふ]に500円[ごひゃくえん]しかありません。","ko":"지갑에 500엔밖에 없어요."},{"jp":"朝[あさ]はコーヒーしか飲[の]みません。","ko":"아침에는 커피밖에 안 마셔요."},{"jp":"この店[みせ]は日曜日[にちようび]にしか開[あ]いていない。","ko":"이 가게는 일요일에만 열려 있다."}],"dr":[{"t":"make","q":"パンを食べる → '빵밖에 안 먹는다'","a":"パンしか食べない","hint":"を를 しか로 바꾸고, 食べる의 る를 빼고 ない."},{"t":"make","q":"一人来た → '한 명밖에 안 왔다'","a":"一人しか来なかった","hint":"수량 뒤에 しか, 来た를 과거 부정 来なかった로."},{"t":"fill","q":"教室[きょうしつ]には学生[がくせい]が三人[さんにん]（　）いなかった。","a":"しか","opts":["しか","だけ","ばかり","まで"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%97%E3%81%8B-%E3%81%AA%E3%81%84"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_012","t":"名詞ばかり","ko":"~만, ~뿐 (그것만 잔뜩)","cat":"강조·한정","conn":[{"w":"명사","f":"ゲームばかりする"},{"w":"명사 (보통 だ로 끝냄)","f":"高い物ばかりだ"},{"w":"동사 て형 + ばかりいる","f":"寝てばかりいる"}],"rule":["명사 바로 뒤에 ばかり를 붙인다.","が・を는 보통 ばかり로 바뀌어 사라진다(ゲームをする → ゲームばかりする).","계속되는 습관은 동사를 ている형으로 한다: する → し + ている(ゲームばかりしている).","동사 자체를 반복할 때는 て형 + ばかりいる(寝てばかりいる)."],"why":"","nu":"회화체에서 많이 쓴다. '그것만 너무 많이/계속'이라는 뜻이라 불만·비판·걱정이 섞이는 일이 많다(文句ばかり言う). 단순히 '하나만'이라는 뜻으로 だけ를 쓸 자리에 ばかり를 쓰면 불평처럼 들린다.","cmp":[{"g":"～だけ","d":"だけ는 범위를 '그것 하나'로 한정할 뿐 중립적. ばかり는 같은 것이 많거나 반복된다는 뜻이고 부정적 느낌이 있다."},{"g":"～しか～ない","d":"しか는 부정문 전용으로 '그것밖에 없다(부족)'. ばかり는 긍정문으로 '그것만 잔뜩(과다)'."}],"ex":[{"jp":"弟[おとうと]は毎日[まいにち]ゲームばかりしている。","ko":"남동생은 매일 게임만 하고 있다."},{"jp":"この店[みせ]は高[たか]い物[もの]ばかりだ。","ko":"이 가게는 비싼 물건뿐이다."},{"jp":"休[やす]みの日[ひ]は寝[ね]てばかりいます。","ko":"쉬는 날에는 잠만 자요."}],"dr":[{"t":"make","q":"お菓子を食べる → '과자만 먹고 있다'","a":"お菓子ばかり食べている","hint":"を를 ばかり로 바꾸고, 食べる를 食べている로."},{"t":"make","q":"テレビを見る → '텔레비전만 본다'","a":"テレビばかり見る","hint":"명사 + ばかり, を는 빠진다."},{"t":"fill","q":"彼[かれ]は文句[もんく]（　）言[い]って、全然[ぜんぜん]手伝[てつだ]わない。","a":"ばかり","opts":["ばかり","しか","ために","までに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%B0%E3%81%8B%E3%82%8A"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_086","t":"そんなに～ない","ko":"그렇게(그다지) ~하지 않다","cat":"부사·접속사","conn":[{"w":"い형용사 부정","f":"そんなに + 重くない"},{"w":"な형용사 부정","f":"そんなに + 好きじゃない"},{"w":"동사 부정","f":"そんなに + 食べない"},{"w":"긍정·의문","f":"そんなに + 急がなくても / 高いの?"}],"rule":["1. 부사 そんなに는 형태가 바뀌지 않고 술어 앞에 놓인다.","2. い형용사는 끝의 い를 く로 바꾸고 ない를 붙인다(重い→重くない).","3. な형용사·명사는 じゃない(ではない)를 붙인다(好き→好きじゃない).","4. 동사는 ない형으로 바꾼다(食べる→食べない, 行く→行かない)."],"why":"そんな에 に가 붙은 부사형으로 '그 정도로'라는 뜻이며, 부정과 함께 쓰여 '생각하는 만큼은 아니다'가 된다.","nu":"부정문에서는 '그다지 ~않다'로 あまり～ない와 비슷하다. 긍정문·의문문에서는 '그렇게나'의 놀람이 된다(そんなに食べたの?). 상대를 진정시키는 そんなに～なくてもいい(그렇게 ~하지 않아도 돼)도 자주 쓴다. 회화체.","cmp":[{"g":"あまり～ない","d":"일반적인 '별로 ~않다'. そんなに～ない는 상대의 말이나 예상을 기준으로 '그 정도는 아니다'라는 느낌."},{"g":"こんなに","d":"눈앞의 것이나 말하는 사람 쪽 정도를 가리켜 '이렇게나'."}],"ex":[{"jp":"この箱[はこ]はそんなに重[おも]くないですよ。","ko":"이 상자는 그렇게 무겁지 않아요."},{"jp":"肉[にく]はそんなに好[す]きじゃありません。","ko":"고기는 그다지 좋아하지 않아요."},{"jp":"時間[じかん]はあるから、そんなに急[いそ]がなくてもいいよ。","ko":"시간은 있으니까 그렇게 서두르지 않아도 돼."}],"dr":[{"t":"make","q":"難しい → そんなに～ない","a":"そんなに難しくない","hint":"い를 く로 바꾸고 ない를 붙인다."},{"t":"make","q":"遠い → そんなに～ない","a":"そんなに遠くない","hint":"い형용사: い→く + ない."},{"t":"fill","q":"このテストは（　）難[むずか]しくなかった。","a":"そんなに","opts":["そんなに","とても","かなり","もっと"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%82%93%E3%81%AA%E3%81%AB"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_121","t":"文A。そのうえ 文B。","ko":"게다가, 더구나","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"安い。そのうえ、おいしい。"},{"w":"문장(て형/ し) + そのうえ","f":"安くて、そのうえ おいしい"}],"rule":["1. そのうえ는 형태가 바뀌지 않으며 문장 A가 끝난 뒤, 문장 B의 맨 앞에 둔다(安い。そのうえ、おいしい。).","2. 문장 B에는 문장 A와 같은 방향(좋은 점에 좋은 점, 나쁜 점에 나쁜 점)의 내용을 덧붙인다.","3. 문장 B에는 흔히 も를 써서 '~도'를 나타낸다(そのうえ、値段も安い)."],"why":"その(그) + うえ(上, 위)로 이루어진 말로, 앞에서 말한 것 '위에' 더한다는 뜻이다.","nu":"それに보다 조금 딱딱한 말로, 글이나 정중한 말에서도 자연스럽다. 앞과 반대 방향의 내용(좋은 점 뒤에 나쁜 점)에는 쓰지 않는다. 문장 B에 명령・의뢰・권유는 잘 오지 않는다.","cmp":[{"g":"それに","d":"뜻은 거의 같지만 회화적이고, 이유를 하나 더 늘어놓을 때도 많이 쓴다."}],"ex":[{"jp":"この店[みせ]は安[やす]い。そのうえ、料理[りょうり]もおいしい。","ko":"이 가게는 싸다. 게다가 요리도 맛있다."},{"jp":"道[みち]に迷[まよ]った。そのうえ、雨[あめ]も降[ふ]ってきた。","ko":"길을 잃었다. 게다가 비까지 내리기 시작했다."},{"jp":"彼女[かのじょ]は親切[しんせつ]で、そのうえ、仕事[しごと]も速[はや]い。","ko":"그녀는 친절하고 게다가 일도 빠르다."}],"dr":[{"t":"make","q":"この部屋は広い。/ 駅にも近い。 → そのうえ","a":"この部屋は広い。そのうえ、駅にも近い。","hint":"문장 A 뒤, 문장 B 맨 앞에 そのうえ를 둔다."},{"t":"make","q":"財布をなくした。/ 電車にも遅れた。 → そのうえ","a":"財布をなくした。そのうえ、電車にも遅れた。","hint":"나쁜 일에 나쁜 일을 덧붙일 때도 쓴다."},{"t":"fill","q":"このパソコンは軽[かる]い。（　）、値段[ねだん]も安[やす]い。","a":"そのうえ","opts":["そのうえ","しかし","でも","それなら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%81%AE%E4%B8%8A"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_122","t":"文A。それで 文B。","ko":"그래서","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"寝坊した。それで、遅れた。"}],"rule":["1. それで는 형태가 바뀌지 않으며 문장 A가 끝난 뒤, 문장 B의 맨 앞에 둔다.","2. 문장 A는 원인・이유, 문장 B는 그 결과로 일어난 일이다(寝坊した。それで、遅れた。).","3. 문장 B에는 명령・의뢰・권유・의지(~해라, ~하자)가 오지 않는다."],"why":"それ(그것, 앞 문장 전체) + で(조사)로 이루어져 '그것으로, 그것 때문에'라는 뜻이다.","nu":"이미 일어난 사실의 인과를 설명할 때 많이 쓰는 회화적인 말이다. 이유를 근거로 명령・권유를 할 때는 それで가 아니라 だから를 쓴다(×雨だ。それで、傘を持って行け). 상대의 말을 받아 'それで？(그래서?)'라고 이야기를 재촉할 때도 쓴다.","cmp":[{"g":"だから","d":"말하는 사람의 판단・주장・명령까지 이어질 수 있다. それで는 결과로 일어난 사실을 말한다."}],"ex":[{"jp":"今朝[けさ]寝坊[ねぼう]しました。それで、会社[かいしゃ]に遅[おく]れました。","ko":"오늘 아침 늦잠을 잤습니다. 그래서 회사에 늦었습니다."},{"jp":"昨日[きのう]は熱[ねつ]がありました。それで、学校[がっこう]を休[やす]みました。","ko":"어제는 열이 있었습니다. 그래서 학교를 쉬었습니다."},{"jp":"雨[あめ]が強[つよ]かった。それで、試合[しあい]は中止[ちゅうし]になった。","ko":"비가 심했다. 그래서 시합은 중지되었다."}],"dr":[{"t":"make","q":"バスが来なかった。/ タクシーで行った。 → それで","a":"バスが来なかった。それで、タクシーで行った。","hint":"원인 문장 뒤, 결과 문장 맨 앞에 それで."},{"t":"make","q":"お腹がすいた。/ パンを食べた。 → それで","a":"お腹がすいた。それで、パンを食べた。","hint":"문장 B는 실제로 일어난 결과."},{"t":"fill","q":"電車[でんしゃ]が止[と]まりました。（　）、授業[じゅぎょう]に遅[おく]れました。","a":"それで","opts":["それで","しかし","それとも","ところが"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%82%8C%E3%81%A7","https://www.seirei.ac.jp/media/20201224_4setsuzokugo.pdf"],"vf":1,"u":13,"g":1,"gp":"gg_N4_09"},{"id":"g4_123","t":"文A。それに 文B。","ko":"게다가, 그리고 또","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"近い。それに、安い。"},{"w":"명사 + それに + 명사","f":"パン、それに 牛乳"}],"rule":["1. それに는 형태가 바뀌지 않으며 문장 A가 끝난 뒤, 문장 B의 맨 앞에 둔다(近い。それに、安い。).","2. 문장 B에는 문장 A와 같은 방향의 내용을 하나 더 덧붙인다.","3. 이유를 늘어놓을 때 자주 쓰고, 문장 B에 も가 잘 붙는다(それに、値段も安い)."],"why":"","nu":"회화에서 많이 쓰는 첨가의 접속사다. そのうえ보다 가볍고, 이유를 덧붙이는 데 특히 자연스럽다(行きたくない。それに、お金もない). 반대되는 내용을 잇는 데에는 쓰지 않는다.","cmp":[{"g":"そのうえ","d":"뜻은 같지만 조금 딱딱하고 글에서도 쓴다."},{"g":"それで","d":"앞 내용의 결과를 이어 준다. それに는 내용을 하나 더 더한다."}],"ex":[{"jp":"このアパートは駅[えき]から近[ちか]い。それに、家賃[やちん]も安[やす]い。","ko":"이 아파트는 역에서 가깝다. 게다가 집세도 싸다."},{"jp":"今日[きょう]は行[い]きたくないです。それに、時間[じかん]もありません。","ko":"오늘은 가고 싶지 않아요. 게다가 시간도 없어요."},{"jp":"彼[かれ]は親切[しんせつ]です。それに、おもしろいです。","ko":"그는 친절합니다. 게다가 재미있습니다."}],"dr":[{"t":"make","q":"この店はきれいだ。/ 店員も親切だ。 → それに","a":"この店はきれいだ。それに、店員も親切だ。","hint":"문장 A 뒤, 문장 B 맨 앞에 それに."},{"t":"make","q":"眠い。/ 頭も痛い。 → それに","a":"眠い。それに、頭も痛い。","hint":"같은 방향의 이유를 하나 더 붙인다."},{"t":"fill","q":"この靴[くつ]は軽[かる]いです。（　）、とても丈夫[じょうぶ]です。","a":"それに","opts":["それに","でも","それとも","ところが"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%82%8C%E3%81%AB"],"vf":1,"u":14,"g":1,"gp":"gg_N4_09"},{"id":"g4_124","t":"文A。だから 文B。","ko":"그러니까, 그래서","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"明日はテストだ。だから、勉強する。"},{"w":"정중형","f":"明日はテストです。ですから、勉強します。"}],"rule":["1. だから는 형태가 바뀌지 않으며 문장 A가 끝난 뒤, 문장 B의 맨 앞에 둔다.","2. 문장 A는 이유, 문장 B는 그로부터 나오는 결과・판단・행동이다.","3. 정중하게 말할 때는 ですから를 쓴다.","4. 문장 B에 명령・권유・의지도 올 수 있다(寒い。だから、コートを着て行きなさい)."],"why":"","nu":"말하는 사람의 판단이나 주장을 강하게 이끄는 말이다. 'だから？(그래서 뭐?)', 'だから言ったでしょう(그러니까 말했잖아)'처럼 쓰면 짜증・불만이 섞인 말투가 되므로 손윗사람에게는 ですから가 무난하다.","cmp":[{"g":"それで","d":"결과로 일어난 사실을 말함. 명령・권유가 뒤에 오면 だから를 쓴다."}],"ex":[{"jp":"明日[あした]はテストだ。だから、今日[きょう]は勉強[べんきょう]する。","ko":"내일은 시험이다. 그러니까 오늘은 공부한다."},{"jp":"外[そと]は寒[さむ]いです。ですから、コートを着[き]て行[い]ってください。","ko":"밖은 추워요. 그러니까 코트를 입고 가세요."},{"jp":"この料理[りょうり]は簡単[かんたん]だ。だから、子[こ]どもでも作[つく]れる。","ko":"이 요리는 간단하다. 그래서 아이라도 만들 수 있다."}],"dr":[{"t":"make","q":"雨が降っている。/ 傘を持って行こう。 → だから","a":"雨が降っている。だから、傘を持って行こう。","hint":"이유 문장 뒤, 판단・권유 문장 맨 앞에 だから."},{"t":"make","q":"もう遅いです。/ 帰ります。 → 정중형","a":"もう遅いです。ですから、帰ります。","hint":"정중한 문장에서는 ですから."},{"t":"fill","q":"道[みち]が込[こ]んでいる。（　）、早[はや]く出[で]かけよう。","a":"だから","opts":["だから","それとも","しかし","ところで"]}],"src":["https://www.seirei.ac.jp/media/20201224_4setsuzokugo.pdf"],"vf":1,"u":14,"g":1,"gp":"gg_N4_09"},{"id":"g4_014","t":"名詞をいただく","ko":"(윗사람에게서) ~을 받다 (겸양)","cat":"경어","conn":[{"w":"명사(물건) + を","f":"本をいただく"},{"w":"주는 사람 + に / から","f":"先生に(から)いただく"},{"w":"정중 과거","f":"いただきました"},{"w":"음식 (먹다·마시다의 겸양)","f":"いただきます"}],"rule":["もらう를 겸양어 いただく로 바꾼다. 조사는 그대로: 先生に本をもらう → 先生に本をいただく.","주는 사람 뒤에는 に 또는 から, 물건 뒤에는 を를 붙인다.","いただく는 1그룹 동사라 어미 く를 き로 바꾸고 ます・ました를 붙인다: いただく → いただきました."],"why":"いただく(頂く・戴く)에는 '머리 위에 얹다·받들다'라는 뜻도 있으며, 여기서는 그 여러 뜻 중 '받다'의 겸양어 뜻으로 쓰인 것이다.","nu":"격식체·경어. 주어는 받는 사람(나 또는 내 쪽)이고, 주는 사람(윗사람)을 높인다. 먹을 때의 'いただきます'도 같은 동사다. 주어를 윗사람으로 착각해 '先生がいただいた'라고 하면 선생님을 낮추게 되니 주의한다.","cmp":[{"g":"名詞をもらう","d":"もらう는 대등·아랫사람에게서 받을 때의 보통 표현. いただく는 윗사람에게서 받을 때의 겸양 표현."},{"g":"名詞をくださる","d":"くださる는 주는 윗사람이 주어(先生がくださる). いただく는 받는 내가 주어(私が先生にいただく). 같은 사실을 보는 쪽이 다르다."}],"ex":[{"jp":"先生[せんせい]に辞書[じしょ]をいただきました。","ko":"선생님께 사전을 받았습니다."},{"jp":"部長[ぶちょう]からお土産[みやげ]をいただいた。","ko":"부장님께 기념품을 받았다."},{"jp":"このお菓子[かし]、一[ひと]ついただいてもいいですか。","ko":"이 과자 하나 먹어도 될까요?"}],"dr":[{"t":"make","q":"先生に手紙をもらった → 겸양 정중 과거","a":"先生に手紙をいただきました","hint":"もらう를 いただく로, く를 き로 바꾸고 ました."},{"t":"make","q":"社長 / 本 → '사장님께 책을 받았습니다'","a":"社長に本をいただきました","hint":"주는 사람 + に, 물건 + を + いただきました."},{"t":"fill","q":"私[わたし]は先生[せんせい]から本[ほん]を（　）。","a":"いただきました","opts":["いただきました","くださいました","さしあげました","あげました"]}],"src":["https://ja.wiktionary.org/wiki/%E3%81%84%E3%81%9F%E3%81%A0%E3%81%8F","https://guidetojapanese.org/learn/?p=249"],"vf":1,"u":14,"g":1,"gp":"gg_N4_09"},{"id":"g4_015","t":"名詞をくださる","ko":"(윗사람이 나에게) ~을 주시다 (존경)","cat":"경어","conn":[{"w":"명사(물건) + を","f":"本をくださる"},{"w":"주는 사람 + が, 받는 사람 + に","f":"先生が私に本をくださる"},{"w":"정중형 (불규칙)","f":"くださいます"},{"w":"과거","f":"くださった / くださいました"}],"rule":["くれる를 존경어 くださる로 바꾼다. 조사는 그대로: 先生が本をくれる → 先生が本をくださる.","정중형은 특수하게 어미 る가 い로 바뀌어 くださいます(×くださります)가 된다. 과거 정중형은 くださいました.","보통 과거는 くださった, て형은 くださって."],"why":"くださる(下さる)는 '내리다'라는 뜻의 下す(くだす)에서 온 말로, 윗사람에게서 아래(나) 쪽으로 물건이 내려오는 방향을 나타낸다.","nu":"경어(존경어). 주어는 주는 윗사람이고 받는 쪽은 나 또는 내 쪽 사람이다. 부탁할 때 쓰는 'ください'도 이 동사의 명령형이다. 정중형을 'くださります'로 잘못 만드는 실수가 많다.","cmp":[{"g":"名詞をくれる","d":"くれる는 대등·아랫사람이 나에게 줄 때. くださる는 윗사람이 나에게 줄 때 높이는 표현."},{"g":"名詞をいただく","d":"いただく는 받는 나를 주어로 해 나를 낮춘다. くださる는 주는 윗사람을 주어로 해 높인다."}],"ex":[{"jp":"先生[せんせい]が私[わたし]に本[ほん]をくださいました。","ko":"선생님께서 저에게 책을 주셨습니다."},{"jp":"お客様[きゃくさま]がお菓子[かし]をくださった。","ko":"손님께서 과자를 주셨다."},{"jp":"社長[しゃちょう]がお土産[みやげ]をくださいました。","ko":"사장님께서 기념품을 주셨습니다."}],"dr":[{"t":"make","q":"先生がペンをくれました → 존경어로","a":"先生がペンをくださいました","hint":"くれる를 くださる로, 정중형은 る를 い로 바꿔 くださいました."},{"t":"make","q":"くださる → 정중형(현재)","a":"くださいます","hint":"る가 い로 바뀌는 특수 활용 + ます."},{"t":"fill","q":"部長[ぶちょう]が私[わたし]に地図[ちず]を（　）。","a":"くださいました","opts":["くださいました","いただきました","さしあげました","もらいました"]}],"src":["https://en.wiktionary.com/wiki/%E4%B8%8B%E3%81%95%E3%82%8B","https://guidetojapanese.org/learn/?p=249"],"vf":1,"u":14,"g":1,"gp":"gg_N4_09"},{"id":"g4_017","t":"名詞をさしあげる","ko":"(윗사람에게) ~을 드리다 (겸양)","cat":"경어","conn":[{"w":"명사(물건) + を","f":"お茶をさしあげる"},{"w":"받는 사람(윗사람) + に","f":"先生にさしあげる"},{"w":"정중형","f":"さしあげます"},{"w":"권유·제안","f":"さしあげましょうか"}],"rule":["あげる를 겸양어 さしあげる로 바꾼다. 조사는 그대로: 先生に花をあげる → 先生に花をさしあげる.","さしあげる는 2그룹(る) 동사라 어미 る를 떼고 ます를 붙인다: さしあげます.","주는 사람은 나(내 쪽), 받는 사람은 윗사람일 때만 쓴다."],"why":"","nu":"격식체·경어(겸양어). 윗사람의 행동에는 쓸 수 없다(×先生が私にさしあげた). 윗사람 앞에서 'さしあげます'라고 직접 말하면 은혜를 베푸는 듯 들릴 수 있어서, 'どうぞ'나 'さしあげましょうか'처럼 부드럽게 말하는 일이 많다.","cmp":[{"g":"名詞をあげる","d":"あげる는 대등·아랫사람에게 주는 보통 표현. さしあげる는 윗사람에게 드리는 겸양 표현."},{"g":"名詞をくださる","d":"くださる는 윗사람이 나에게 주시는 것(방향이 반대)."}],"ex":[{"jp":"先生[せんせい]に旅行[りょこう]のお土産[みやげ]をさしあげました。","ko":"선생님께 여행 기념품을 드렸습니다."},{"jp":"お客様[きゃくさま]にお茶[ちゃ]をさしあげてください。","ko":"손님께 차를 드리세요."},{"jp":"このパンフレットをさしあげましょうか。","ko":"이 팸플릿을 드릴까요?"}],"dr":[{"t":"make","q":"先生に花をあげます → 겸양어로","a":"先生に花をさしあげます","hint":"あげる를 さしあげる로 바꾸고, る를 떼고 ます."},{"t":"make","q":"社長 / 手紙 → '사장님께 편지를 드렸습니다'","a":"社長に手紙をさしあげました","hint":"받는 사람 + に, 물건 + を + さしあげました."},{"t":"fill","q":"私[わたし]は部長[ぶちょう]にお茶[ちゃ]を（　）。","a":"さしあげました","opts":["さしあげました","くださいました","くれました","いただきました"]}],"src":["https://smartlog.jp/142320","https://guidetojapanese.org/learn/?p=249"],"vf":1,"u":14,"g":1,"gp":"gg_N4_10"},{"id":"g4_008","t":"名詞にする","ko":"~로 하다(정하다)","cat":"기타","conn":[{"w":"명사","f":"ピザにする"},{"w":"명사 (정중형)","f":"コーヒーにします"},{"w":"의문사","f":"何にする？"},{"w":"과거형","f":"赤いのにした"}],"rule":["고를 대상인 명사 뒤에 に를 붙인다.","그 뒤에 する를 놓는다: ピザ + に + する.","する는 불규칙 동사라 정중형은 し + ます(します), 과거는 した / しました가 된다."],"why":"に가 결과·선택의 도달점을 나타내고, する(하다)가 말하는 사람의 의지적인 행동을 나타내서 '~를 고르는 쪽으로 하다 = ~로 정하다'가 된다.","nu":"회화에서 아주 많이 쓴다. 가게 주문(コーヒーにします)이나 약속 정하기에 자주 나온다. 말하는 사람이 스스로 선택한다는 느낌이다. 한국어 '~로 할게요'와 거의 같다. を를 쓰는 실수(×ピザをします)에 주의한다.","cmp":[{"g":"名詞になる","d":"になる는 저절로 또는 결과적으로 그렇게 '되는' 것(변화). にする는 자기 의지로 '정하는' 것."},{"g":"動詞ことにする","d":"ことにする는 동사(행동)를 하기로 정하는 것이고, にする는 명사(물건·대상)를 고르는 것."}],"ex":[{"jp":"飲[の]み物[もの]は紅茶[こうちゃ]にします。","ko":"음료는 홍차로 할게요."},{"jp":"今度[こんど]の旅行[りょこう]は京都[きょうと]にしよう。","ko":"이번 여행은 교토로 하자."},{"jp":"プレゼントは時計[とけい]にしました。","ko":"선물은 시계로 했어요."}],"dr":[{"t":"make","q":"ラーメン → '라멘으로 할게요(정중)'","a":"ラーメンにします","hint":"명사 + に + する의 정중형 します."},{"t":"make","q":"赤いかばん → '빨간 가방으로 했다(보통 과거)'","a":"赤いかばんにした","hint":"명사구 + に, する의 과거 した."},{"t":"fill","q":"A「何[なに]を飲[の]む？」B「私[わたし]はジュース（　）する。」","a":"に","opts":["に","を","が","で"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%99%E3%82%8B"],"vf":1,"u":14,"g":1,"gp":"gg_N4_10"},{"id":"g4_009","t":"名詞になる","ko":"~이/가 되다","cat":"기타","conn":[{"w":"명사","f":"医者になる"},{"w":"な형용사","f":"きれいになる"},{"w":"い형용사 (い→く)","f":"寒くなる"},{"w":"いい (불규칙)","f":"よくなる"}],"rule":["명사 뒤에 に를 붙이고 なる를 놓는다: 医者 + に + なる.","な형용사도 어간 + に + なる(きれいになる).","い형용사는 に를 쓰지 않고 끝의 い를 く로 바꾼다(寒い → 寒くなる). いい는 よくなる.","なる의 정중 과거는 어미 る를 り로 바꾸고 ました: なりました."],"why":"に가 변화가 도달하는 결과점을 나타내고, なる가 '되다'라는 변화 동사라서 'A라는 결과에 이르다'가 된다.","nu":"회화·문장 모두 쓴다. 저절로 일어나는 변화나 결과를 말한다. 한국어 '~이/가 되다'에 끌려 が를 쓰는 실수(×医者がなる)가 많다. 반드시 に를 쓴다.","cmp":[{"g":"名詞にする","d":"にする는 누군가 의지로 그렇게 만들거나 고르는 것. になる는 변화의 결과를 말하는 것."},{"g":"～くなる","d":"い형용사는 に 대신 く형을 쓴다. 명사·な형용사만 に + なる."}],"ex":[{"jp":"兄[あに]は去年[きょねん]、医者[いしゃ]になりました。","ko":"형은 작년에 의사가 되었어요."},{"jp":"部屋[へや]がきれいになった。","ko":"방이 깨끗해졌다."},{"jp":"もうすぐ春[はる]になりますね。","ko":"곧 봄이 되네요."}],"dr":[{"t":"make","q":"先生 → '선생님이 되고 싶다'","a":"先生になりたい","hint":"명사 + に + なる의 ます형 なり + たい."},{"t":"make","q":"静か → '조용해졌다(보통 과거)'","a":"静かになった","hint":"な형용사 어간 + に + なった."},{"t":"fill","q":"大人[おとな]（　）なったら、外国[がいこく]に住[す]みたい。","a":"に","opts":["に","が","を","で"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%AA%E3%82%8B-%E3%81%8F%E3%81%AA%E3%82%8B"],"vf":1,"u":14,"g":1,"gp":"gg_N4_10"},{"id":"g4_050","t":"～ないことがある","ko":"~하지 않을 때가 있다","cat":"기타","conn":[{"w":"1그룹 동사","f":"行く → 行かない + ことがある"},{"w":"2그룹 동사","f":"食べる → 食べない + ことがある"},{"w":"する 동사","f":"返事する → 返事しない + ことがある"},{"w":"来る","f":"来る → 来ない(こない) + ことがある"}],"rule":["1. 동사를 ない형으로 바꾼다. 1그룹은 어미 う단을 あ단으로 바꾸고 ない(行く→行かない, 단 う는 わ: 買う→買わない), 2그룹은 る를 떼고 ない(食べる→食べない), する→しない, 来る→来ない(こない).","2. ない형 뒤에 ことがある를 붙인다: 食べない + ことがある.","3. 정중체는 ことがあります. が 대신 も를 쓰면 '~하지 않을 때도 있다'."],"why":"こと(일, 것) + が + ある(있다). '~하지 않는 일이 있다'는 구조라 '가끔 ~하지 않는다'는 뜻이 된다.","nu":"평소에는 하지만 가끔 하지 않는 일을 말한다. 과거 경험의 た형 + ことがある(~한 적이 있다)와 헷갈리지 말 것: 食べないことがある(가끔 안 먹는다) / 食べたことがない(먹은 적이 없다). 한 번뿐인 일에는 쓰지 않는다.","cmp":[{"g":"～たことがある","d":"과거에 한 경험(~한 적이 있다). ～ないことがある는 반복되는 일 중 가끔 안 하는 경우."}],"ex":[{"jp":"忙[いそが]しい日[ひ]は朝[あさ]ご飯[はん]を食[た]べないことがある。","ko":"바쁜 날에는 아침밥을 안 먹을 때가 있다."},{"jp":"この電車[でんしゃ]は時間[じかん]どおりに来[こ]ないことがあります。","ko":"이 전철은 시간대로 오지 않을 때가 있어요."},{"jp":"兄[あに]はメールに返事[へんじ]をしないことがある。","ko":"형(오빠)은 메일에 답장을 안 할 때가 있다."}],"dr":[{"t":"make","q":"行く → ～ないことがある","a":"行かないことがある","hint":"く를 か로 바꾸고 ない, 뒤에 ことがある."},{"t":"make","q":"来る → ～ないことがある","a":"来ないことがある","hint":"来る의 ない형은 来ない(こない)."},{"t":"fill","q":"父[ちち]は疲[つか]れていると、晩[ばん]ご飯[はん]を食[た]べないこと（　）ある。","a":"が","opts":["が","を","に","で"]}],"src":["https://bunpro.jp/grammar_points/ことがある"],"vf":1,"u":14,"g":1,"gp":"gg_N4_10"}];
